window.WORD_LABELS = {"water":{"label":{"en":"Water","ja":"水","ko":"물","zh":"水","yue":"水","vi":"Nước","th":"น้ำ","id":"Air","hi":"पानी","de":"Wasser","fr":"Eau","it":"Acqua","es":"Agua","es_eu":"Agua","es_mx":"Agua","pt":"Água","pt_eu":"Água","pt_br":"Água","ru":"Вода","uk":"Вода","ar":"ماء","he":"מים","sw":"Maji"},"definition":{"en":"Drinkable water (H₂O); the basic substance, not a body of water.","ja":"飲用・生活用の水 (H₂O)。川・湖・海などの水域そのものではない。","ko":"마시거나 일상에 쓰는 물 (H₂O). 강·호수·바다 같은 수역 자체가 아니다.","zh":"可饮用或日常使用的水 (H₂O)；不是河流、湖泊、海洋等水域本身。","yue":"可以飲嘅水 (H₂O)；唔係指河、湖、海呢類水域本身。","vi":"Nước uống / sinh hoạt (H₂O); không phải sông, hồ, biển.","th":"น้ำดื่มหรือใช้ทั่วไป (H₂O); ไม่ใช่แหล่งน้ำเอง","id":"Air minum atau pakai sehari-hari (H₂O); bukan sungai/danau/laut sebagai badan air.","hi":"पीने योग्य पानी (H₂O); नदी, झील या समुद्र जैसे जलाशय नहीं।","de":"Trinkbares Wasser (H₂O); kein Gewässer wie Fluss oder See.","fr":"Eau potable (H₂O); pas un cours d'eau ni la mer.","it":"Acqua potabile (H₂O); non un fiume, lago o mare.","es":"Agua potable (H₂O); no un río, lago o mar.","es_eu":"Agua potable (H₂O); no un río, lago o mar.","es_mx":"Agua potable (H₂O); no un río, lago o mar.","pt":"Água potável (H₂O); não um rio, lago ou mar.","pt_eu":"Água potável (H₂O); não um rio, lago ou mar.","pt_br":"Água potável (H₂O); não um rio, lago ou mar.","ru":"Питьевая вода (H₂O); не водоём (река, озеро, море).","uk":"Питна вода (H₂O); не водойма (річка, озеро, море).","ar":"الماء الصالح للشرب (H₂O)؛ ليس النهر أو البحيرة أو البحر.","he":"מים לשתייה (H₂O); לא נהר, אגם או ים.","sw":"Maji ya kunywa au matumizi (H₂O); si mto/ziwa/bahari."}},"fire":{"label":{"en":"Fire","ja":"火","ko":"불","zh":"火","yue":"火","vi":"Lửa","th":"ไฟ","id":"Api","hi":"आग","de":"Feuer","fr":"Feu","it":"Fuoco","es":"Fuego","es_eu":"Fuego","es_mx":"Fuego","pt":"Fogo","pt_eu":"Fogo","pt_br":"Fogo","ru":"Огонь","uk":"Вогонь","ar":"نار","he":"אש","sw":"Moto"},"definition":{"en":"Fire / flame as a phenomenon; not \"match\" or \"campfire\".","ja":"燃焼現象としての火・炎。「マッチ」や「焚き火」のような特定の対象ではない。","ko":"연소 현상으로서의 불·불꽃. \"성냥\"이나 \"모닥불\" 같은 구체적 대상이 아니다.","zh":"作为燃烧现象的火、火焰；不是\"火柴\"或\"营火\"等具体对象。","yue":"燃燒現象嘅火、火焰；唔係「火柴」、「篝火」呢類具體物件。","vi":"Lửa / ngọn lửa như hiện tượng cháy; không phải \"diêm\" hay \"lửa trại\".","th":"ไฟ/เปลวไฟในฐานะปรากฏการณ์เผาไหม้; ไม่ใช่ \"ไม้ขีด\" หรือ \"กองไฟ\"","id":"Api / nyala sebagai fenomena pembakaran; bukan \"korek\" atau \"api unggun\".","hi":"जलने की क्रिया के रूप में आग/लौ; \"माचिस\" या \"अलाव\" नहीं।","de":"Feuer / Flamme als Phänomen; nicht \"Streichholz\" oder \"Lagerfeuer\".","fr":"Feu / flamme en tant que phénomène; pas \"allumette\" ni \"feu de camp\".","it":"Fuoco / fiamma come fenomeno; non \"fiammifero\" o \"falò\".","es":"Fuego / llama como fenómeno; no \"cerilla\" ni \"fogata\".","es_eu":"Fuego / llama como fenómeno; no \"cerilla\" ni \"hoguera\".","es_mx":"Fuego / llama como fenómeno; no \"cerillo\" ni \"fogata\".","pt":"Fogo / chama como fenómeno; não \"fósforo\" nem \"fogueira\".","pt_eu":"Fogo / chama como fenómeno; não \"fósforo\" nem \"fogueira\".","pt_br":"Fogo / chama como fenômeno; não \"fósforo\" nem \"fogueira\".","ru":"Огонь / пламя как явление; не \"спичка\" и не \"костёр\".","uk":"Вогонь / полум’я як явище; не \"сірник\" і не \"вогнище\".","ar":"النار/اللهب كظاهرة؛ ليست \"عود ثقاب\" أو \"نار مخيم\".","he":"אש / להבה כתופעה; לא \"גפרור\" או \"מדורה\".","sw":"Moto / mwali kama jambo la kuwaka; si \"kibiriti\" au \"moto wa kambi\"."}},"sun":{"label":{"en":"Sun","ja":"太陽","ko":"해","zh":"太阳","yue":"日頭","vi":"Mặt trời","th":"ดวงอาทิตย์","id":"Matahari","hi":"सूरज","de":"Sonne","fr":"Soleil","it":"Sole","es":"Sol","es_eu":"Sol","es_mx":"Sol","pt":"Sol","pt_eu":"Sol","pt_br":"Sol","ru":"Солнце","uk":"Сонце","ar":"شمس","he":"שמש","sw":"Jua"},"definition":{"en":"The Sun (our star) seen from Earth; \"the sun in the sky\".","ja":"地球から見える恒星としての太陽。「空の太陽」。","ko":"지구에서 보이는 항성으로서의 해. \"하늘의 해\".","zh":"从地球上看到的太阳；\"天上的太阳\"。","yue":"由地球望到嘅太陽；「天上嘅太陽」。","vi":"Mặt trời nhìn từ Trái Đất; \"mặt trời trên bầu trời\".","th":"ดาวฤกษ์ดวงอาทิตย์ที่มองเห็นจากโลก; \"พระอาทิตย์บนฟ้า\"","id":"Bintang matahari yang terlihat dari Bumi; \"matahari di langit\".","hi":"पृथ्वी से दिखने वाला सूर्य; \"आकाश का सूर्य\"।","de":"Die Sonne, gesehen von der Erde aus; \"die Sonne am Himmel\".","fr":"Le Soleil vu depuis la Terre; \"le soleil dans le ciel\".","it":"Il Sole visto dalla Terra; \"il sole nel cielo\".","es":"El Sol visto desde la Tierra; \"el sol en el cielo\".","es_eu":"El Sol visto desde la Tierra; \"el sol en el cielo\".","es_mx":"El Sol visto desde la Tierra; \"el sol en el cielo\".","pt":"O Sol visto da Terra; \"o sol no céu\".","pt_eu":"O Sol visto da Terra; \"o sol no céu\".","pt_br":"O Sol visto da Terra; \"o sol no céu\".","ru":"Солнце, видимое с Земли; \"солнце на небе\".","uk":"Сонце, видиме з Землі; \"сонце в небі\".","ar":"الشمس كما تُرى من الأرض؛ \"الشمس في السماء\".","he":"השמש כפי שהיא נראית מכדור הארץ; \"השמש בשמיים\".","sw":"Jua kama linavyoonekana kutoka Dunia; \"jua angani\"."}},"moon":{"label":{"en":"Moon","ja":"月","ko":"달","zh":"月亮","yue":"月光","vi":"Mặt trăng","th":"ดวงจันทร์","id":"Bulan","hi":"चाँद","de":"Mond","fr":"Lune","it":"Luna","es":"Luna","es_eu":"Luna","es_mx":"Luna","pt":"Lua","pt_eu":"Lua","pt_br":"Lua","ru":"Луна","uk":"Місяць","ar":"قمر","he":"ירח","sw":"Mwezi"},"definition":{"en":"Earth's natural satellite; not the calendar month.","ja":"地球の衛星としての月。暦の「月」ではない。","ko":"지구의 위성으로서의 달. 달력의 \"월\"이 아니다.","zh":"地球的天然卫星；不是日历上的\"月\"。","yue":"地球嘅天然衛星；唔係指曆法上嘅「月份」。","vi":"Vệ tinh tự nhiên của Trái Đất; không phải \"tháng\" trong lịch.","th":"ดวงจันทร์ ดาวบริวารของโลก; ไม่ใช่ \"เดือน\" ในปฏิทิน","id":"Satelit alami Bumi; bukan \"bulan\" sebagai satuan kalender.","hi":"पृथ्वी का प्राकृतिक उपग्रह; कैलेंडर का \"महीना\" नहीं।","de":"Der natürliche Satellit der Erde; nicht der Kalendermonat.","fr":"Satellite naturel de la Terre; pas le mois calendaire.","it":"Satellite naturale della Terra; non il mese del calendario.","es":"Satélite natural de la Tierra; no el mes del calendario.","es_eu":"Satélite natural de la Tierra; no el mes del calendario.","es_mx":"Satélite natural de la Tierra; no el mes del calendario.","pt":"Satélite natural da Terra; não o mês do calendário.","pt_eu":"Satélite natural da Terra; não o mês do calendário.","pt_br":"Satélite natural da Terra; não o mês do calendário.","ru":"Естественный спутник Земли; не календарный \"месяц\".","uk":"Природний супутник Землі; не календарний \"місяць\".","ar":"القمر التابع الطبيعي للأرض؛ ليس \"الشهر\" التقويمي.","he":"הירח, לוויין טבעי של כדור הארץ; לא \"חודש\" בלוח השנה.","sw":"Mwezi, satilaiti asilia ya Dunia; si \"mwezi\" wa kalenda."}},"star":{"label":{"en":"Star","ja":"星","ko":"별","zh":"星","yue":"星","vi":"Sao","th":"ดาว","id":"Bintang","hi":"तारा","de":"Stern","fr":"Étoile","it":"Stella","es":"Estrella","es_eu":"Estrella","es_mx":"Estrella","pt":"Estrela","pt_eu":"Estrela","pt_br":"Estrela","ru":"Звезда","uk":"Зірка","ar":"نجم","he":"כוכב","sw":"Nyota"},"definition":{"en":"NOUN \"star\" = a celestial star in the night sky. Not \"movie star\" (celebrity) and not a shape/asterisk.","ja":"名詞「星」＝夜空の天体としての恒星。「スター（有名人）」や星形・アスタリスクではない。","ko":"명사 \"별\" = 밤하늘의 천체. \"스타(유명인)\"나 별 모양·별표가 아님.","zh":"名词\"星\"＝夜空中的天体恒星；不是\"明星\"（名人），也不是星形/星号。","yue":"名詞「星」＝夜空嘅天體恆星；唔係「明星」（名人），亦唔係星形／星號。","vi":"Danh từ \"sao\" = ngôi sao trên bầu trời đêm. Không phải \"ngôi sao\" (người nổi tiếng) hay hình sao/dấu sao.","th":"คำนาม \"ดาว\" = ดาวฤกษ์บนท้องฟ้ายามค่ำคืน; ไม่ใช่ \"ดารา\" (คนดัง) และไม่ใช่รูปดาว/เครื่องหมายดอกจัน.","id":"Kata benda \"bintang\" = benda langit di langit malam. Bukan \"bintang film\" (selebritas) atau bentuk bintang/tanda asteris.","hi":"संज्ञा \"तारा\" = रात के आकाश का खगोलीय पिंड। न \"फ़िल्म स्टार\" (मशहूर हस्ती), न तारे का आकार/तारांकन।","de":"Substantiv \"Stern\" = Himmelskörper am Nachthimmel. Nicht \"Star\" (Prominenter) und keine Sternform/kein Sternchen.","fr":"Nom \"étoile\" = astre dans le ciel nocturne. Pas une \"star\" (célébrité) ni une forme d'étoile/un astérisque.","it":"Sostantivo \"stella\" = astro nel cielo notturno. Non una \"star\" (celebrità) né una forma a stella/asterisco.","es":"Sustantivo \"estrella\" = astro en el cielo nocturno. No una \"estrella\" (celebridad) ni una forma de estrella/asterisco.","es_eu":"Sustantivo \"estrella\" = astro en el cielo nocturno. No una \"estrella\" (celebridad) ni una forma de estrella/asterisco.","es_mx":"Sustantivo \"estrella\" = astro en el cielo nocturno. No una \"estrella\" (celebridad) ni una forma de estrella/asterisco.","pt":"Substantivo \"estrela\" = astro no céu noturno. Não uma \"estrela\" (celebridade) nem uma forma de estrela/asterisco.","pt_eu":"Substantivo \"estrela\" = astro no céu noturno. Não uma \"estrela\" (celebridade) nem uma forma de estrela/asterisco.","pt_br":"Substantivo \"estrela\" = astro no céu noturno. Não uma \"estrela\" (celebridade) nem uma forma de estrela/asterisco.","ru":"Существительное \"звезда\" = небесное тело на ночном небе. Не \"звезда\" (знаменитость) и не фигура-звезда/звёздочка.","uk":"Іменник \"зірка\" = небесне тіло на нічному небі. Не \"зірка\" (знаменитість) і не фігура-зірка/зірочка.","ar":"اسم \"نجم\" = جرم سماوي في سماء الليل. ليس \"نجماً\" (مشهوراً) ولا شكلاً نجمياً/علامة نجمية.","he":"שם עצם \"כוכב\" = גרם שמימי בשמי הלילה. לא \"כוכב\" (סלבריטי) ולא צורת כוכב/כוכבית.","sw":"Nomino \"nyota\" = kitu cha angani usiku. Si \"nyota\" (mtu maarufu) wala umbo la nyota/alama ya nyota."}},"night":{"label":{"en":"Night","ja":"夜","ko":"밤","zh":"晚上","yue":"夜晚","vi":"Đêm","th":"คืน","id":"Malam","hi":"रात","de":"Nacht","fr":"Nuit","it":"Notte","es":"Noche","es_eu":"Noche","es_mx":"Noche","pt":"Noite","pt_eu":"Noite","pt_br":"Noite","ru":"Ночь","uk":"Ніч","ar":"ليل","he":"לילה","sw":"Usiku"},"definition":{"en":"The dark part of the day, citation form. The everyday noun (\"at night\"), not \"evening\", not \"midnight\", and not a compound or an adverb. Where a language distinguishes the period from a counted night, the plain period noun is taken.","ja":"一日のうち暗い時間帯、辞書形。日常の名詞（「夜に」）であり、「夕方」でも「真夜中」でもなく、複合語や副詞でもない。時間帯と「一晩」を区別する言語では、時間帯を表す素の名詞を採る。","ko":"하루 중 어두운 시간대, 사전형. 일상적인 명사(\"밤에\")이며 \"저녁\"이나 \"한밤중\"이 아니고 합성어나 부사도 아니다. 시간대와 \"하룻밤\"을 구별하는 언어에서는 시간대를 가리키는 명사를 싣는다.","zh":"一天中天黑的时段，词典形。取日常名词（“在夜里”），不取“傍晚”“午夜”，也不取复合词或副词。若语言区分时段与可数的“一夜”，取表示时段的名词。","yue":"一日之中天黑嘅時段，詞典形。取日常名詞（「喺夜晚」），唔取「傍晚」「午夜」，亦唔取複合詞或副詞。若語言區分時段同可數嘅「一晚」，取表示時段嘅名詞。","vi":"Khoảng thời gian tối trong ngày, dạng từ điển. Danh từ thường ngày (\"vào ban đêm\"), không phải \"chiều tối\", không phải \"nửa đêm\", cũng không phải từ ghép hay trạng từ. Với ngôn ngữ phân biệt khoảng thời gian và \"một đêm\" đếm được, lấy danh từ chỉ khoảng thời gian.","th":"ช่วงเวลาที่มืดของวัน รูปพจนานุกรม เป็นคำนามที่ใช้ทั่วไป (\"ตอนกลางคืน\") ไม่ใช่ \"ตอนเย็น\" ไม่ใช่ \"เที่ยงคืน\" และไม่ใช่คำประสมหรือคำวิเศษณ์ ภาษาที่แยกช่วงเวลาออกจาก \"คืนหนึ่ง\" ที่นับได้ ให้เอาคำนามที่หมายถึงช่วงเวลา","id":"Bagian gelap dari hari, bentuk kamus. Nomina sehari-hari (\"pada malam hari\"), bukan \"petang\", bukan \"tengah malam\", dan bukan gabungan atau adverbia. Untuk bahasa yang membedakan periode dari \"satu malam\" yang terhitung, diambil nomina periodenya.","hi":"दिन का अंधेरा भाग, शब्दकोश-रूप। रोज़मर्रा की संज्ञा (\"रात में\"), न \"साँझ\", न \"आधी रात\", और न कोई समास या क्रियाविशेषण। जो भाषाएँ अवधि और गिनी जाने वाली \"एक रात\" में भेद करती हैं, उनमें अवधि वाली संज्ञा ली गई है।","de":"Der dunkle Teil des Tages, Zitierform. Das alltägliche Substantiv („nachts“), nicht „Abend“, nicht „Mitternacht“, und kein Kompositum oder Adverb. Unterscheidet eine Sprache den Zeitraum von einer gezählten Nacht, steht der Zeitraum.","fr":"La partie sombre de la journée, forme de citation. Le nom courant (« la nuit »), non « soir », non « minuit », ni un composé ou un adverbe. Là où une langue distingue la période d’une nuit comptée, on donne la période.","it":"La parte buia del giorno, forma di citazione. Il sostantivo di uso comune («di notte»), non «sera», non «mezzanotte», né un composto o un avverbio. Dove una lingua distingue il periodo da una notte contata, si dà il periodo.","es":"La parte oscura del día, forma de cita. El sustantivo corriente («de noche»), no «tarde», no «medianoche», ni un compuesto o adverbio. Donde una lengua distingue el período de una noche contada, se da el período.","es_eu":"La parte oscura del día, forma de cita. El sustantivo corriente («de noche»), no «tarde», no «medianoche», ni un compuesto o adverbio. Donde una lengua distingue el período de una noche contada, se da el período.","es_mx":"La parte oscura del día, forma de cita. El sustantivo corriente («de noche»), no «tarde», no «medianoche», ni un compuesto o adverbio. Donde una lengua distingue el período de una noche contada, se da el período.","pt":"A parte escura do dia, forma de citação. O substantivo corrente («à noite»), não «tarde», não «meia-noite», nem um composto ou advérbio. Onde uma língua distingue o período de uma noite contada, dá-se o período.","pt_eu":"A parte escura do dia, forma de citação. O substantivo corrente («à noite»), não «tarde», não «meia-noite», nem um composto ou advérbio. Onde uma língua distingue o período de uma noite contada, dá-se o período.","pt_br":"A parte escura do dia, forma de citação. O substantivo corrente («à noite»), não «tarde», não «meia-noite», nem um composto ou advérbio. Onde uma língua distingue o período de uma noite contada, dá-se o período.","ru":"Тёмная часть суток, словарная форма. Обиходное существительное («ночью»), не «вечер», не «полночь», и не сложное слово или наречие. Если язык различает период и счётную «ночь», берётся период.","uk":"Темна частина доби, словникова форма. Побутовий іменник («вночі»), не «вечір», не «північ», і не складне слово чи прислівник. Якщо мова розрізняє період і лічену «ніч», подано період.","ar":"الجزء المظلم من اليوم، صيغة المعجم. الاسم اليومي («في الليل»)، لا «المساء» ولا «منتصف الليل»، ولا مركّبًا ولا ظرفًا. وحيث تميّز اللغة بين المدة و«ليلة» معدودة، تُذكر المدة.","he":"החלק החשוך של היממה, צורת מילון. שם העצם היומיומי (\"בלילה\"), לא \"ערב\", לא \"חצות\", ולא צירוף או תואר הפועל. במקום שבו שפה מבחינה בין הפרק לבין \"לילה\" ספור, ניתן הפרק.","sw":"Sehemu ya giza ya siku, umbo la kamusi. Nomino ya kawaida (\"usiku\"), si \"jioni\", si \"usiku wa manane\", wala mchanganyiko au kielezi. Pale lugha inapotofautisha kipindi na \"usiku mmoja\" unaohesabika, kipindi ndicho kilichotolewa."}},"rain":{"label":{"en":"Rain","ja":"雨","ko":"비","zh":"雨","yue":"雨","vi":"Mưa","th":"ฝน","id":"Hujan","hi":"बारिश","de":"Regen","fr":"Pluie","it":"Pioggia","es":"Lluvia","es_eu":"Lluvia","es_mx":"Lluvia","pt":"Chuva","pt_eu":"Chuva","pt_br":"Chuva","ru":"Дождь","uk":"Дощ","ar":"مطر","he":"גשם","sw":"Mvua"},"definition":{"en":"Rain (the noun) — water falling from clouds; not the verb 'to rain' or a rainy season.","ja":"雲から降る雨（名詞）。動詞の「雨が降る」や「雨季」ではない。","ko":"구름에서 내리는 비(명사). 동사 '비가 오다'나 '우기'가 아니다.","zh":"从云中落下的雨（名词）；不是动词「下雨」，也不是「雨季」。","yue":"由雲度落落嚟嘅雨（名詞）；唔係動詞「落雨」，都唔係「雨季」。","vi":"Mưa — nước rơi từ mây (danh từ); không phải động từ 'mưa' hay 'mùa mưa'.","th":"ฝน — น้ำที่ตกลงมาจากเมฆ (คำนาม); ไม่ใช่คำกริยา 'ฝนตก' หรือ 'ฤดูฝน'","id":"Hujan — air yang turun dari awan (kata benda); bukan kata kerja 'turun hujan' atau 'musim hujan'.","hi":"बारिश — बादलों से गिरने वाला पानी (संज्ञा); क्रिया 'बारिश होना' या 'बरसात का मौसम' नहीं।","de":"Regen — Wasser, das aus Wolken fällt (das Substantiv); nicht das Verb 'regnen' oder die Regenzeit.","fr":"Pluie — eau qui tombe des nuages (le nom); ni le verbe 'pleuvoir' ni la saison des pluies.","it":"Pioggia — acqua che cade dalle nuvole (il sostantivo); non il verbo 'piovere' né la stagione delle piogge.","es":"Lluvia — agua que cae de las nubes (el sustantivo); no el verbo 'llover' ni la temporada de lluvias.","es_eu":"Lluvia — agua que cae de las nubes (el sustantivo); no el verbo 'llover' ni la temporada de lluvias.","es_mx":"Lluvia — agua que cae de las nubes (el sustantivo); no el verbo 'llover' ni la temporada de lluvias.","pt":"Chuva — água que cai das nuvens (o substantivo); não o verbo 'chover' nem a estação chuvosa.","pt_eu":"Chuva — água que cai das nuvens (o substantivo); não o verbo 'chover' nem a estação chuvosa.","pt_br":"Chuva — água que cai das nuvens (o substantivo); não o verbo 'chover' nem a estação chuvosa.","ru":"Дождь — вода, падающая из облаков (существительное); не глагол 'идти' (о дожде) и не сезон дождей.","uk":"Дощ — вода, що падає з хмар (іменник); не дієслово 'йти' (про дощ) і не сезон дощів.","ar":"المطر — الماء المتساقط من الغيوم (اسم)؛ ليس الفعل 'تمطر' ولا موسم الأمطار.","he":"גשם — מים היורדים מהעננים (שם עצם); לא הפועל 'לרדת' (על גשם) ולא עונת הגשמים.","sw":"Mvua — maji yanayoanguka kutoka mawingu (nomino); si kitenzi 'kunyesha' wala msimu wa mvua."}},"wind":{"label":{"en":"Wind","ja":"風","ko":"바람","zh":"风","yue":"風","vi":"Gió","th":"ลม","id":"Angin","hi":"हवा","de":"Wind","fr":"Vent","it":"Vento","es":"Viento","es_eu":"Viento","es_mx":"Viento","pt":"Vento","pt_eu":"Vento","pt_br":"Vento","ru":"Ветер","uk":"Вітер","ar":"ريح","he":"רוח","sw":"Upepo"},"definition":{"en":"Wind — naturally moving air, especially outdoors; not \"breath\" or \"to wind\" (as in winding a clock).","ja":"風——屋外などで自然に動く空気の流れ。「息」や「（時計を）巻く」という意味ではない。","ko":"바람 — 자연적으로 움직이는 공기(특히 야외의). \"숨\"이나 \"(시계를) 감다\"가 아니다.","zh":"风——自然流动的空气（尤指室外）；不是\"呼吸\"或\"上发条\"的意思。","yue":"風——自然流動嘅空氣（尤其係戶外嘅）；唔係「呼吸」或者「上鏈」嘅意思。","vi":"Gió — luồng không khí chuyển động tự nhiên (ngoài trời); không phải \"hơi thở\" hay \"lên dây (đồng hồ)\".","th":"ลม — อากาศที่เคลื่อนที่ตามธรรมชาติ (โดยเฉพาะกลางแจ้ง); ไม่ใช่ \"ลมหายใจ\" หรือ \"การไขลาน\"","id":"Angin — udara yang bergerak secara alami (terutama di luar ruangan); bukan \"napas\" atau \"memutar\" (jam).","hi":"हवा — प्राकृतिक रूप से चलने वाली वायु (विशेषतः बाहर); \"सांस\" या \"घड़ी की चाबी भरना\" नहीं।","de":"Wind — natürlich bewegte Luft (besonders im Freien); nicht \"Atem\" oder \"aufziehen\" (wie eine Uhr).","fr":"Vent — air en mouvement naturel (surtout en extérieur); pas le \"souffle\" ni \"remonter\" (une horloge).","it":"Vento — aria in movimento naturale (soprattutto all'aperto); non il \"respiro\" né \"caricare\" (un orologio).","es":"Viento — aire en movimiento natural (sobre todo al aire libre); no el \"aliento\" ni \"dar cuerda\" (a un reloj).","es_eu":"Viento — aire en movimiento natural (sobre todo al aire libre); no el \"aliento\" ni \"dar cuerda\" (a un reloj).","es_mx":"Viento — aire en movimiento natural (sobre todo al aire libre); no el \"aliento\" ni \"dar cuerda\" (a un reloj).","pt":"Vento — ar em movimento natural (sobretudo ao ar livre); não a \"respiração\" nem \"dar corda\" (a um relógio).","pt_eu":"Vento — ar em movimento natural (sobretudo ao ar livre); não a \"respiração\" nem \"dar corda\" (a um relógio).","pt_br":"Vento — ar em movimento natural (sobretudo ao ar livre); não a \"respiração\" nem \"dar corda\" (a um relógio).","ru":"Ветер — естественное движение воздуха (особенно на улице); не \"дыхание\" и не \"завести\" (часы).","uk":"Вітер — природний рух повітря (особливо на вулиці); не \"дихання\" і не \"завести\" (годинник).","ar":"الريح — حركة طبيعية للهواء (خاصة في الخارج)؛ ليست \"النَفَس\" ولا \"لَفّ\" (الساعة).","he":"רוח — תנועה טבעית של אוויר (בעיקר בחוץ); לא \"נשימה\" ולא \"למתוח\" (שעון).","sw":"Upepo — hewa inayosogea kiasili (hasa nje); si \"pumzi\" wala \"kuzungusha\" (saa)."}},"earth":{"label":{"en":"Earth","ja":"土","ko":"흙","zh":"土","yue":"泥","vi":"Đất","th":"ดิน","id":"Tanah","hi":"मिट्टी","de":"Erde","fr":"Terre","it":"Terra","es":"Tierra","es_eu":"Tierra","es_mx":"Tierra","pt":"Terra","pt_eu":"Terra","pt_br":"Terra","ru":"Земля","uk":"Земля","ar":"تراب","he":"אדמה","sw":"Udongo"},"definition":{"en":"Earth as soil / ground underfoot — the physical substance, not the planet.","ja":"地面・大地としての土——足元の物質そのもの。惑星としての地球ではない。","ko":"발밑의 흙·땅 — 그 물질 자체를 가리킨다. 행성으로서의 지구가 아니다.","zh":"脚下的土壤、地面——指这种物质本身，不是行星地球。","yue":"腳下嘅泥土、地面——指嗰種物質本身，唔係話行星地球。","vi":"Đất dưới chân — chất liệu cụ thể, không phải hành tinh Trái Đất.","th":"ดินหรือพื้นดินใต้เท้า — ตัวสารนั้นเอง ไม่ใช่ดาวเคราะห์โลก","id":"Tanah / permukaan bumi di bawah kaki — zatnya sendiri, bukan planet Bumi.","hi":"पैरों तले की मिट्टी/ज़मीन — वह ठोस पदार्थ; ग्रह पृथ्वी नहीं।","de":"Erde als Boden unter den Füßen — der Stoff selbst, nicht der Planet.","fr":"La terre comme sol sous les pieds — la matière elle-même, pas la planète.","it":"La terra come suolo sotto i piedi — la sostanza stessa, non il pianeta.","es":"La tierra como suelo bajo los pies — la sustancia misma, no el planeta.","es_eu":"La tierra como suelo bajo los pies — la sustancia misma, no el planeta.","es_mx":"La tierra como suelo bajo los pies — la sustancia misma, no el planeta.","pt":"A terra como solo sob os pés — a substância em si, não o planeta.","pt_eu":"A terra como solo sob os pés — a substância em si, não o planeta.","pt_br":"A terra como solo sob os pés — a substância em si, não o planeta.","ru":"Земля как почва/грунт под ногами — само вещество, а не планета.","uk":"Земля як ґрунт під ногами — сама речовина, а не планета.","ar":"التراب/الأرض كسطح تحت القدمين — المادة نفسها، وليس الكوكب.","he":"אדמה כקרקע מתחת לרגליים — החומר עצמו, לא כדור הארץ.","sw":"Udongo / ardhi chini ya miguu — dutu yenyewe, si sayari Dunia."}},"snow":{"label":{"en":"Snow","ja":"雪","ko":"눈","zh":"雪","yue":"雪","vi":"Tuyết","th":"หิมะ","id":"Salju","hi":"बर्फ़","de":"Schnee","fr":"Neige","it":"Neve","es":"Nieve","es_eu":"Nieve","es_mx":"Nieve","pt":"Neve","pt_eu":"Neve","pt_br":"Neve","ru":"Снег","uk":"Сніг","ar":"ثلج","he":"שלג","sw":"Theluji"},"definition":{"en":"Snow — frozen precipitation that falls as soft white flakes and settles on the ground; not the verb 'to snow' nor plain ice.","ja":"雪 — 白い結晶となって空から降り、地面に積もる凍った降水。動詞の『雪が降る』でも、単なる氷でもない。","ko":"눈 — 하늘에서 하얀 결정으로 내려 땅에 쌓이는 언 강수; 동사 '눈이 오다'나 단순한 얼음이 아니다.","zh":"雪 — 以白色晶片形式从空中降下并积在地面的冻结降水；不是动词'下雪'，也不是普通的冰。","yue":"雪 — 以白色雪片形式從天上落落嚟、積喺地面嘅凍結降水；唔係動詞'落雪'，亦唔係普通嘅冰。","vi":"Tuyết — mưa đóng băng rơi xuống thành những bông trắng mềm và phủ trên mặt đất; không phải động từ 'đổ tuyết' cũng không phải nước đá thường.","th":"หิมะ — หยาดน้ำฟ้าที่แข็งตัวตกลงมาเป็นเกล็ดสีขาวและทับถมบนพื้น ไม่ใช่กริยา 'หิมะตก' และไม่ใช่น้ำแข็งธรรมดา","id":"Salju — presipitasi beku yang turun sebagai serpihan putih lembut dan menumpuk di tanah; bukan kata kerja 'turun salju' maupun es biasa.","hi":"बर्फ़ — आसमान से सफ़ेद रुई जैसे टुकड़ों में गिरने वाली और ज़मीन पर जमने वाली जमी हुई वर्षा; न तो क्रिया 'बर्फ़ गिरना' और न साधारण बर्फ़ (आइस)।","de":"Schnee — gefrorener Niederschlag, der als weiche weiße Flocken fällt und sich am Boden ablagert; nicht das Verb 'schneien' und nicht bloßes Eis.","fr":"Neige — précipitation gelée qui tombe en flocons blancs et légers et recouvre le sol ; ni le verbe « neiger » ni la simple glace.","it":"Neve — precipitazione ghiacciata che cade in soffici fiocchi bianchi e si posa al suolo; non il verbo 'nevicare' né il semplice ghiaccio.","es":"Nieve — precipitación helada que cae en copos blancos y suaves y se acumula en el suelo; no el verbo 'nevar' ni el simple hielo.","es_eu":"Nieve — precipitación helada que cae en copos blancos y suaves y se acumula en el suelo; no el verbo 'nevar' ni el simple hielo.","es_mx":"Nieve — precipitación helada que cae en copos blancos y suaves y se acumula en el suelo; no el verbo 'nevar' ni el simple hielo.","pt":"Neve — precipitação gelada que cai em flocos brancos e macios e se acumula no solo; não o verbo 'nevar' nem o simples gelo.","pt_eu":"Neve — precipitação gelada que cai em flocos brancos e macios e se acumula no solo; não o verbo 'nevar' nem o simples gelo.","pt_br":"Neve — precipitação congelada que cai em flocos brancos e macios e se acumula no solo; não o verbo 'nevar' nem o simples gelo.","ru":"Снег — замёрзшие осадки, выпадающие белыми хлопьями и ложащиеся на землю; не глагол 'идёт снег' и не обычный лёд.","uk":"Сніг — замерзлі опади, що падають білими сніжинками й лягають на землю; не дієслово 'йде сніг' і не звичайний лід.","ar":"ثلج — تساقط متجمّد ينزل على هيئة رقائق بيضاء ناعمة ويتراكم على الأرض؛ ليس الفعل 'تُثلج' ولا الجليد العادي.","he":"שלג — משקעים קפואים היורדים כפתיתים לבנים ומצטברים על הקרקע; לא הפועל 'יורד שלג' ולא קרח רגיל.","sw":"Theluji — mvua iliyoganda inayoanguka kama vipande vyeupe laini na kujilundika ardhini; si kitenzi 'kunyesha theluji' wala barafu ya kawaida."}},"stone":{"label":{"en":"Stone","ja":"石","ko":"돌","zh":"石头","yue":"石頭","vi":"Đá","th":"หิน","id":"Batu","hi":"पत्थर","de":"Stein","fr":"Pierre","it":"Pietra","es":"Piedra","es_eu":"Piedra","es_mx":"Piedra","pt":"Pedra","pt_eu":"Pedra","pt_br":"Pedra","ru":"Камень","uk":"Камінь","ar":"حجر","he":"אבן","sw":"Jiwe"},"definition":{"en":"Stone — a small-to-mid piece of hard rock or mineral matter; not a gemstone, not rock music.","ja":"石 — 手に取れるくらいの硬い岩・鉱物のかたまり。宝石でもロック音楽でもない。","ko":"돌 — 단단한 기암이나 광물의 작은 덩어리; 보석이나 록 음악이 아니다.","zh":"石头 — 一块坚硬的岩石或矿物；不是宝石，也不是摇滚乐。","yue":"石頭 — 一嚿硬嘅岩石或礦物；唔係寶石，亦唔係搖滾音樂。","vi":"Đá — một mảnh đá hoặc khoáng chất cứng nhỏ đến vừa; không phải đá quý, không phải nhạc rock.","th":"หิน — ก้อนหินหรือแร่แข็งขนาดเล็กถึงกลาง ไม่ใช่อัญมณี ไม่ใช่เพลงร็อก","id":"Batu — bongkahan batuan atau mineral keras berukuran kecil hingga sedang; bukan permata, bukan musik rok.","hi":"पत्थर — कठोर चट्टान या खनिज का छोटा-मझोला टुकड़ा; रत्न नहीं, रॉक संगीत नहीं।","de":"Stein — ein kleines bis mittelgroßes Stück harten Gesteins oder Minerals; kein Edelstein, keine Rockmusik.","fr":"Pierre — un petit à moyen morceau de roche ou de matière minérale dure; pas une pierre précieuse, pas la musique rock.","it":"Pietra — un pezzo piccolo o medio di roccia o materia minerale dura; non una gemma, non la musica rock.","es":"Piedra — un trozo pequeño o mediano de roca o materia mineral dura; no una gema, no la música rock.","es_eu":"Piedra — un trozo pequeño o mediano de roca o materia mineral dura; no una gema, no la música rock.","es_mx":"Piedra — un trozo pequeño o mediano de roca o materia mineral dura; no una gema, no la música rock.","pt":"Pedra — um pedaço pequeno a médio de rocha ou matéria mineral dura; não uma gema, não música rock.","pt_eu":"Pedra — um pedaço pequeno a médio de rocha ou matéria mineral dura; não uma gema, não música rock.","pt_br":"Pedra — um pedaço pequeno a médio de rocha ou matéria mineral dura; não uma gema, não música rock.","ru":"Камень — небольшой или средний кусок твёрдой породы или минерала; не драгоценный камень и не рок-музыка.","uk":"Камінь — невеликий чи середній шматок твердої породи або мінералу; не коштовний камінь і не рок-музика.","ar":"حجر — قطعة صغيرة إلى متوسطة من الصخر أو المادة المعدنية الصلبة؛ ليست جوهرة ولا موسيقى الروك.","he":"אבן — פיסה קטנה עד בינונית של סלע או חומר מינרלי קשה; לא אבן חן ולא מוזיקת רוק.","sw":"Jiwe — kipande kidogo hadi cha wastani cha mwamba au madini magumu; si johari wala muziki wa rock."}},"mother":{"label":{"en":"Mother","ja":"母","ko":"어머니","zh":"母亲","yue":"母親","vi":"Mẹ","th":"แม่","id":"Ibu","hi":"माता","de":"Mutter","fr":"Mère","it":"Madre","es":"Madre","es_eu":"Madre","es_mx":"Madre","pt":"Mãe","pt_eu":"Mãe","pt_br":"Mãe","ru":"Мать","uk":"Мати","ar":"أم","he":"אמא","sw":"Mama"},"definition":{"en":"Female parent — neutral/citation form. Register varies by language.","ja":"女親（母）の中立的・辞書形。フォーマル/カジュアルの区別は言語による。","ko":"여성 부모(어머니)의 중립적/사전형. 격식 차이는 언어마다 다르다.","zh":"女性家长（母亲）的中性/词典形式。语体级别因语言而异。","yue":"女家長（母親）嘅中性／詞典形；語體區別因語言而異。","vi":"Mẹ — dạng trung tính/từ điển; sắc thái thay đổi theo ngôn ngữ.","th":"แม่ในรูปกลาง/รูปอ้างอิงในพจนานุกรม; ระดับภาษาขึ้นกับภาษานั้น ๆ","id":"Ibu — bentuk netral/kamus; ragam formal/akrab berbeda per bahasa.","hi":"माता का तटस्थ/शब्दकोश रूप; भाषा के अनुसार शैली बदलती है।","de":"Mutter — neutrale Wörterbuchform; Register variiert je nach Sprache.","fr":"Mère — forme neutre/lexicale; le registre varie selon la langue.","it":"Madre — forma neutra/lessicografica; il registro varia per lingua.","es":"Madre — forma neutra/de diccionario; el registro varía por lengua.","es_eu":"Madre — forma neutra/de diccionario; el registro varía por lengua.","es_mx":"Madre — forma neutra/de diccionario; el registro varía por lengua.","pt":"Mãe — forma neutra/de dicionário; o registo varia por língua.","pt_eu":"Mãe — forma neutra/de dicionário; o registo varia por língua.","pt_br":"Mãe — forma neutra/de dicionário; o registro varia por língua.","ru":"Мать — нейтральная/словарная форма; регистр зависит от языка.","uk":"Мати — нейтральна/словникова форма; регістр залежить від мови.","ar":"الأم — الصيغة المحايدة/المعجمية؛ يختلف المستوى اللغوي بحسب اللغة.","he":"אם — צורת מילון/ניטרלית; הרגיסטר משתנה בין שפות.","sw":"Mama — umbo la kawaida/la kamusi; usawa wa lugha hutofautiana."}},"father":{"label":{"en":"Father","ja":"父","ko":"아버지","zh":"父亲","yue":"父親","vi":"Cha","th":"พ่อ","id":"Ayah","hi":"पिता","de":"Vater","fr":"Père","it":"Padre","es":"Padre","es_eu":"Padre","es_mx":"Padre","pt":"Pai","pt_eu":"Pai","pt_br":"Pai","ru":"Отец","uk":"Батько","ar":"أب","he":"אבא","sw":"Baba"},"definition":{"en":"Male parent — neutral/citation form. Same register convention as mother.","ja":"男親（父）の中立的・辞書形。母と同じ語法ポリシー。","ko":"남성 부모(아버지)의 중립적/사전형. 어머니와 동일한 어법 정책.","zh":"男性家长（父亲）的中性/词典形式。语体规范同\"母亲\"。","yue":"男家長（父親）嘅中性／詞典形；語體政策同「母親」一樣。","vi":"Cha — dạng trung tính/từ điển; chính sách giống \"mẹ\".","th":"พ่อในรูปกลาง/รูปอ้างอิง; นโยบายเดียวกับ \"แม่\"","id":"Ayah — bentuk netral/kamus; kebijakan sama seperti \"ibu\".","hi":"पिता का तटस्थ/शब्दकोश रूप; नीति \"माता\" के समान।","de":"Vater — neutrale Wörterbuchform; Konvention wie bei Mutter.","fr":"Père — forme neutre/lexicale; même règle que pour mère.","it":"Padre — forma neutra/lessicografica; stessa regola di \"madre\".","es":"Padre — forma neutra/de diccionario; mismo criterio que \"madre\".","es_eu":"Padre — forma neutra/de diccionario; mismo criterio que \"madre\".","es_mx":"Padre — forma neutra/de diccionario; mismo criterio que \"madre\".","pt":"Pai — forma neutra/de dicionário; mesmo critério de \"mãe\".","pt_eu":"Pai — forma neutra/de dicionário; mesmo critério de \"mãe\".","pt_br":"Pai — forma neutra/de dicionário; mesmo critério de \"mãe\".","ru":"Отец — нейтральная/словарная форма; та же конвенция, что у \"мать\".","uk":"Батько — нейтральна/словникова форма; та сама конвенція, що в \"мати\".","ar":"الأب — الصيغة المحايدة/المعجمية؛ نفس قاعدة \"الأم\".","he":"אב — צורת מילון/ניטרלית; אותה מדיניות כמו \"אם\".","sw":"Baba — umbo la kamusi/la kawaida; sera ile ile kama \"mama\"."}},"i":{"label":{"en":"I","ja":"私","ko":"나","zh":"我","yue":"我","vi":"Tôi","th":"ฉัน","id":"Saya","hi":"मैं","de":"Ich","fr":"Je","it":"Io","es":"Yo","es_eu":"Yo","es_mx":"Yo","pt":"Eu","pt_eu":"Eu","pt_br":"Eu","ru":"Я","uk":"Я","ar":"أنا","he":"אני","sw":"Mimi"},"definition":{"en":"1st-person SINGULAR subject pronoun \"I / me\"; everyday plain form. Not the plural \"we\".","ja":"一人称単数の主格代名詞「私（わたし）」の日常的な語。複数の「私たち」ではない。","ko":"일상적인 1인칭 단수 대명사 \"나\"; 복수 \"우리\"가 아님.","zh":"第一人称单数代词\"我\"，日常口语形式；不是复数\"我们\"。","yue":"第一人稱單數代詞「我」，日常口語；唔係複數「我哋」。","vi":"Đại từ nhân xưng ngôi thứ nhất SỐ ÍT \"tôi\"; dạng thông dụng. Không phải số nhiều \"chúng tôi\".","th":"สรรพนามบุรุษที่หนึ่งเอกพจน์ \"ฉัน\" แบบทั่วไป; ไม่ใช่พหูพจน์ \"เรา\".","id":"Kata ganti orang pertama TUNGGAL \"saya\"; bentuk sehari-hari. Bukan jamak \"kami/kita\".","hi":"प्रथम पुरुष एकवचन सर्वनाम \"मैं\"; रोज़मर्रा का रूप। बहुवचन \"हम\" नहीं।","de":"Personalpronomen 1. Person SINGULAR \"ich\"; Alltagsform. Nicht der Plural \"wir\".","fr":"Pronom personnel de 1re personne du SINGULIER \"je / moi\" ; forme courante. Pas le pluriel \"nous\".","it":"Pronome personale di 1ª persona SINGOLARE \"io\"; forma comune. Non il plurale \"noi\".","es":"Pronombre personal de 1ª persona del SINGULAR \"yo\"; forma común. No el plural \"nosotros\".","es_eu":"Pronombre personal de 1ª persona del SINGULAR \"yo\"; forma común. No el plural \"nosotros\".","es_mx":"Pronombre personal de 1ª persona del SINGULAR \"yo\"; forma común. No el plural \"nosotros\".","pt":"Pronome pessoal da 1ª pessoa do SINGULAR \"eu\"; forma comum. Não o plural \"nós\".","pt_eu":"Pronome pessoal da 1ª pessoa do SINGULAR \"eu\"; forma comum. Não o plural \"nós\".","pt_br":"Pronome pessoal da 1ª pessoa do SINGULAR \"eu\"; forma comum. Não o plural \"nós\".","ru":"Личное местоимение 1-го лица ЕДИНСТВЕННОГО числа \"я\"; обычная форма. Не множественное \"мы\".","uk":"Особовий займенник 1-ї особи ОДНИНИ \"я\"; звичайна форма. Не множина \"ми\".","ar":"ضمير المتكلم المفرد \"أنا\"؛ الصيغة اليومية. ليس الجمع \"نحن\".","he":"כינוי גוף ראשון יחיד \"אני\"; צורה יומיומית. לא הרבים \"אנחנו\".","sw":"Kiwakilishi cha nafsi ya kwanza UMOJA \"mimi\"; muundo wa kawaida. Si wingi \"sisi\"."}},"you":{"label":{"en":"You","ja":"あなた","ko":"너","zh":"你","yue":"你","vi":"Bạn","th":"คุณ","id":"Kamu","hi":"तुम","de":"Du","fr":"Tu","it":"Tu","es":"Tú","es_eu":"Tú","es_mx":"Tú","pt":"Tu","pt_eu":"Tu","pt_br":"Você","ru":"Ты","uk":"Ти","ar":"أنت","he":"אתה","sw":"Wewe"},"definition":{"en":"2nd-person SINGULAR pronoun \"you\"; informal/default singular. Not plural, not an honorific-only form.","ja":"二人称単数の代名詞「あなた」；くだけた・標準の単数形。複数や敬称専用ではない。","ko":"2인칭 단수 대명사 \"너\"; 비격식·기본 단수형. 복수나 존칭 전용이 아님.","zh":"第二人称单数代词\"你\"，非正式/默认单数；不是复数，也不是敬称专用\"您\"。","yue":"第二人稱單數代詞「你」，非正式／預設單數；唔係複數，亦唔係敬稱專用。","vi":"Đại từ ngôi thứ hai SỐ ÍT \"bạn\"; dạng thân mật/mặc định. Không phải số nhiều hay chỉ dạng tôn kính.","th":"สรรพนามบุรุษที่สองเอกพจน์ \"คุณ\" แบบไม่เป็นทางการ/ทั่วไป; ไม่ใช่พหูพจน์หรือรูปยกย่องเท่านั้น.","id":"Kata ganti orang kedua TUNGGAL \"kamu\"; bentuk akrab/baku. Bukan jamak atau bentuk hormat khusus.","hi":"द्वितीय पुरुष एकवचन सर्वनाम \"तुम\"; अनौपचारिक/सामान्य रूप। बहुवचन या केवल आदरसूचक \"आप\" नहीं।","de":"Personalpronomen 2. Person SINGULAR \"du\"; informelle/normale Einzahl. Nicht Plural, nicht nur Höflichkeitsform.","fr":"Pronom de 2e personne du SINGULIER \"tu\" ; forme familière/par défaut. Pas le pluriel ni la seule forme de politesse \"vous\".","it":"Pronome di 2ª persona SINGOLARE \"tu\"; forma informale/predefinita. Non il plurale né solo la forma di cortesia.","es":"Pronombre de 2ª persona del SINGULAR \"tú\"; forma informal/por defecto. No el plural ni la forma solo de respeto \"usted\".","es_eu":"Pronombre de 2ª persona del SINGULAR \"tú\"; forma informal/por defecto. No el plural ni la forma solo de respeto \"usted\".","es_mx":"Pronombre de 2ª persona del SINGULAR \"tú\"; forma informal/por defecto. No el plural ni la forma solo de respeto \"usted\".","pt":"Pronome de 2ª pessoa do SINGULAR \"tu\"; forma informal/padrão. Não o plural nem apenas a forma de cortesia.","pt_eu":"Pronome de 2ª pessoa do SINGULAR \"tu\"; forma informal/padrão. Não o plural nem apenas a forma de cortesia.","pt_br":"Pronome de 2ª pessoa do SINGULAR \"você\"; forma informal/padrão. Não o plural nem apenas a forma de cortesia.","ru":"Личное местоимение 2-го лица ЕДИНСТВЕННОГО числа \"ты\"; неформальная/базовая форма. Не множественное и не только вежливое \"вы\".","uk":"Особовий займенник 2-ї особи ОДНИНИ \"ти\"; неформальна/базова форма. Не множина й не лише ввічливе \"ви\".","ar":"ضمير المخاطب المفرد \"أنتَ\"؛ الصيغة غير الرسمية/الاعتيادية. ليس الجمع ولا صيغة التبجيل فقط.","he":"כינוי גוף שני יחיד \"אתה\"; צורה לא רשמית/רגילה. לא רבים ולא צורת כבוד בלבד.","sw":"Kiwakilishi cha nafsi ya pili UMOJA \"wewe\"; muundo wa kawaida/isiyo rasmi. Si wingi wala muundo wa heshima pekee."}},"name":{"label":{"en":"Name","ja":"名前","ko":"이름","zh":"名字","yue":"名","vi":"Tên","th":"ชื่อ","id":"Nama","hi":"नाम","de":"Name","fr":"Nom","it":"Nome","es":"Nombre","es_eu":"Nombre","es_mx":"Nombre","pt":"Nome","pt_eu":"Nome","pt_br":"Nome","ru":"Имя","uk":"Ім'я","ar":"اسم","he":"שם","sw":"Jina"},"definition":{"en":"Common NOUN \"name\" (a person's appellation, as in \"my name is…\"). Not a proper name and not the verb \"to name\".","ja":"普通名詞「名前」（人の呼び名。「私の名前は…」の意）。固有名や動詞「名付ける」ではない。","ko":"보통명사 \"이름\"（사람의 호칭, \"내 이름은…\"의 뜻). 고유명사나 동사 \"이름 짓다\"가 아님.","zh":"普通名词\"名字\"（人的称谓，如\"我的名字是…\"）；不是专有名称，也不是动词\"命名\"。","yue":"普通名詞「名」（人嘅稱呼，如「我個名係…」）；唔係專有名稱，亦唔係動詞「命名」。","vi":"Danh từ chung \"tên\" (tên gọi của người, như \"tên tôi là…\"). Không phải tên riêng, không phải động từ \"đặt tên\".","th":"คำนามทั่วไป \"ชื่อ\" (ชื่อเรียกของบุคคล เช่น \"ฉันชื่อ…\"); ไม่ใช่ชื่อเฉพาะและไม่ใช่กริยา \"ตั้งชื่อ\".","id":"Kata benda umum \"nama\" (sebutan seseorang, seperti \"nama saya…\"). Bukan nama diri dan bukan kata kerja \"menamai\".","hi":"सामान्य संज्ञा \"नाम\" (व्यक्ति का पुकारने का शब्द, जैसे \"मेरा नाम…\")। न कोई विशेष नाम, न क्रिया \"नाम रखना\"।","de":"Gattungsnomen \"Name\" (Benennung einer Person, wie in \"mein Name ist…\"). Kein Eigenname und nicht das Verb \"nennen\".","fr":"Nom commun \"nom\" (appellation d'une personne, comme \"mon nom est…\"). Pas un nom propre ni le verbe \"nommer\".","it":"Nome comune \"nome\" (appellativo di una persona, come \"il mio nome è…\"). Non un nome proprio né il verbo \"nominare\".","es":"Sustantivo común \"nombre\" (apelativo de una persona, como \"mi nombre es…\"). No un nombre propio ni el verbo \"nombrar\".","es_eu":"Sustantivo común \"nombre\" (apelativo de una persona, como \"mi nombre es…\"). No un nombre propio ni el verbo \"nombrar\".","es_mx":"Sustantivo común \"nombre\" (apelativo de una persona, como \"mi nombre es…\"). No un nombre propio ni el verbo \"nombrar\".","pt":"Substantivo comum \"nome\" (designação de uma pessoa, como \"o meu nome é…\"). Não um nome próprio nem o verbo \"nomear\".","pt_eu":"Substantivo comum \"nome\" (designação de uma pessoa, como \"o meu nome é…\"). Não um nome próprio nem o verbo \"nomear\".","pt_br":"Substantivo comum \"nome\" (designação de uma pessoa, como \"meu nome é…\"). Não um nome próprio nem o verbo \"nomear\".","ru":"Нарицательное СУЩЕСТВИТЕЛЬНОЕ \"имя\" (наименование человека, как в \"меня зовут…\"). Не имя собственное и не глагол \"называть\".","uk":"Загальний ІМЕННИК \"ім'я\" (найменування людини, як у \"мене звати…\"). Не власна назва й не дієслово \"називати\".","ar":"اسم عام \"اسم\" (تسمية الشخص، كما في \"اسمي…\")؛ ليس اسم عَلَم ولا الفعل \"سمّى\".","he":"שם עצם כללי \"שם\" (כינוי של אדם, כמו \"שמי…\"); לא שם פרטי ולא הפועל \"לקרוא בשם\".","sw":"Nomino ya kawaida \"jina\" (jina la mtu, kama \"jina langu ni…\"). Si jina la pekee wala kitenzi \"kutaja/kuita\"."}},"eye":{"label":{"en":"Eye","ja":"目","ko":"눈","zh":"眼睛","yue":"眼","vi":"Mắt","th":"ตา","id":"Mata","hi":"आँख","de":"Auge","fr":"Œil","it":"Occhio","es":"Ojo","es_eu":"Ojo","es_mx":"Ojo","pt":"Olho","pt_eu":"Olho","pt_br":"Olho","ru":"Глаз","uk":"Око","ar":"عين","he":"עין","sw":"Jicho"},"definition":{"en":"Eye (organ of sight); singular form preferred.","ja":"目（視覚器官）。単数形を優先。","ko":"눈 (시각 기관). 단수형을 우선.","zh":"眼（视觉器官）；优先使用单数形式。","yue":"眼（視覺器官）；優先用單數形。","vi":"Mắt (cơ quan thị giác); ưu tiên dạng số ít.","th":"ตา (อวัยวะการเห็น); เลือกใช้รูปเอกพจน์","id":"Mata (organ penglihatan); diutamakan bentuk tunggal.","hi":"आँख (दृष्टि अंग); एकवचन रूप वरीयता।","de":"Auge (Sehorgan); Singularform bevorzugt.","fr":"Œil (organe de la vue); forme du singulier privilégiée.","it":"Occhio (organo della vista); preferenza per il singolare.","es":"Ojo (órgano de la vista); se prefiere el singular.","es_eu":"Ojo (órgano de la vista); se prefiere el singular.","es_mx":"Ojo (órgano de la vista); se prefiere el singular.","pt":"Olho (órgão da visão); preferir o singular.","pt_eu":"Olho (órgão da visão); preferir o singular.","pt_br":"Olho (órgão da visão); preferir o singular.","ru":"Глаз (орган зрения); предпочтительна форма единственного числа.","uk":"Око (орган зору); бажано форма однини.","ar":"العين (عضو الإبصار)؛ تُفضَّل صيغة المفرد.","he":"עין (איבר הראייה); מועדפת צורת היחיד.","sw":"Jicho (kiungo cha kuona); umbo la umoja hupendekezwa."}},"ear":{"label":{"en":"Ear","ja":"耳","ko":"귀","zh":"耳朵","yue":"耳仔","vi":"Tai","th":"หู","id":"Telinga","hi":"कान","de":"Ohr","fr":"Oreille","it":"Orecchio","es":"Oreja","es_eu":"Oreja","es_mx":"Oreja","pt":"Orelha","pt_eu":"Orelha","pt_br":"Orelha","ru":"Ухо","uk":"Вухо","ar":"أذن","he":"אוזן","sw":"Sikio"},"definition":{"en":"The ear — the external body organ of hearing (not corn-on-the-cob, not hearing itself).","ja":"耳——聴覚をつかさどる体の外部器官（トウモロコシの「穂」でも、聴覚そのものでもない）。","ko":"귀 — 청각을 담당하는 몸의 외부 기관(옥수수 '이삭'이나 청각 그 자체가 아니다).","zh":"耳朵——负责听觉的身体外部器官（不是玉米穗，也不是听觉本身）。","yue":"耳仔——負責聽覺嘅身體外部器官（唔係粟米嘅「穗」，亦都唔係聽覺本身）。","vi":"Tai — cơ quan bên ngoài cơ thể phụ trách thính giác (không phải bắp ngô, không phải bản thân thính giác).","th":"หู — อวัยวะภายนอกร่างกายที่ทำหน้าที่การได้ยิน (ไม่ใช่ฝักข้าวโพด ไม่ใช่การได้ยินเอง)","id":"Telinga — organ luar tubuh untuk mendengar (bukan tongkol jagung, bukan indra pendengaran itu sendiri).","hi":"कान — सुनने का बाहरी शरीर अंग (मक्के की बाली नहीं, न ही सुनने की क्षमता स्वयं)।","de":"Das Ohr — das äußere Körperorgan des Hörens (kein Maiskolben, nicht das Hören selbst).","fr":"L'oreille — l'organe corporel externe de l'audition (pas un épi de maïs, pas l'ouïe elle-même).","it":"L'orecchio — l'organo corporeo esterno dell'udito (non una pannocchia di mais, non l'udito stesso).","es":"La oreja — el órgano corporal externo de la audición (no una mazorca de maíz, no el oído en sí).","es_eu":"La oreja — el órgano corporal externo de la audición (no una mazorca de maíz, no el oído en sí).","es_mx":"La oreja — el órgano corporal externo de la audición (no una mazorca de maíz, no el oído en sí).","pt":"A orelha — o órgão corporal externo da audição (não uma espiga de milho, não a audição em si).","pt_eu":"A orelha — o órgão corporal externo da audição (não uma espiga de milho, não a audição em si).","pt_br":"A orelha — o órgão corporal externo da audição (não uma espiga de milho, não a audição em si).","ru":"Ухо — внешний орган тела, отвечающий за слух (не початок кукурузы и не сам слух).","uk":"Вухо — зовнішній орган тіла, що відповідає за слух (не кукурудзяний качан і не сам слух).","ar":"الأذن — العضو الخارجي في الجسم المسؤول عن السمع (ليست كوز الذرة، وليست حاسة السمع نفسها).","he":"האוזן — האיבר החיצוני בגוף האחראי על השמיעה (לא קלח תירס ולא חוש השמיעה עצמו).","sw":"Sikio — kiungo cha nje cha mwili kinachohusika na kusikia (si gunzi la mahindi, wala si hisia ya kusikia yenyewe)."}},"nose":{"label":{"en":"Nose","ja":"鼻","ko":"코","zh":"鼻子","yue":"鼻哥","vi":"Mũi","th":"จมูก","id":"Hidung","hi":"नाक","de":"Nase","fr":"Nez","it":"Naso","es":"Nariz","es_eu":"Nariz","es_mx":"Nariz","pt":"Nariz","pt_eu":"Nariz","pt_br":"Nariz","ru":"Нос","uk":"Ніс","ar":"أنف","he":"אף","sw":"Pua"},"definition":{"en":"Nose — the external facial organ of smell and breathing; not the sense of smell, and not a verb.","ja":"鼻 — 顔の中央にある、匂いを嗅ぎ呼吸するための器官。嗅覚そのものでも動詞でもない。","ko":"코 — 냄새를 맡고 숨을 쉬는 얼굴 가운데의 기관. 후각 자체나 동사가 아님.","zh":"鼻子 — 面部用于嗅觉和呼吸的器官；不是嗅觉本身，也不是动词。","yue":"鼻哥 — 面部用嚟聞味同呼吸嘅器官；唔係嗅覺本身，亦唔係動詞。","vi":"Mũi — cơ quan trên khuôn mặt để ngửi và thở; không phải khứu giác, cũng không phải động từ.","th":"จมูก — อวัยวะบนใบหน้าสำหรับดมกลิ่นและหายใจ ไม่ใช่ประสาทรับกลิ่นและไม่ใช่คำกริยา","id":"Hidung — organ pada wajah untuk mencium bau dan bernapas; bukan indra penciuman, bukan pula kata kerja.","hi":"नाक — सूँघने और साँस लेने का चेहरे का अंग; यह गंध की इंद्रिय नहीं और न ही कोई क्रिया है।","de":"Nase — das äußere Gesichtsorgan zum Riechen und Atmen; nicht der Geruchssinn und kein Verb.","fr":"Nez — l'organe du visage servant à sentir et à respirer ; ni l'odorat, ni un verbe.","it":"Naso — l'organo del viso per l'olfatto e la respirazione; non l'olfatto stesso né un verbo.","es":"Nariz — el órgano de la cara para oler y respirar; no el sentido del olfato ni un verbo.","es_eu":"Nariz — el órgano de la cara para oler y respirar; no el sentido del olfato ni un verbo.","es_mx":"Nariz — el órgano de la cara para oler y respirar; no el sentido del olfato ni un verbo.","pt":"Nariz — o órgão do rosto para cheirar e respirar; não o olfato nem um verbo.","pt_eu":"Nariz — o órgão do rosto para cheirar e respirar; não o olfato nem um verbo.","pt_br":"Nariz — o órgão do rosto para cheirar e respirar; não o olfato nem um verbo.","ru":"Нос — орган на лице для обоняния и дыхания; не само обоняние и не глагол.","uk":"Ніс — орган на обличчі для нюху й дихання; не саме нюхання і не дієслово.","ar":"الأنف — عضو الوجه المستخدم للشمّ والتنفّس؛ ليس حاسة الشمّ ولا فعلًا.","he":"אף — האיבר שבפנים המשמש להרחה ולנשימה; לא חוש הריח ולא פועל.","sw":"Pua — kiungo cha usoni kinachotumika kunusa na kupumua; si hisia ya kunusa wala kitenzi."}},"tooth":{"label":{"en":"Tooth","ja":"歯","ko":"이","zh":"牙","yue":"牙","vi":"Răng","th":"ฟัน","id":"Gigi","hi":"दाँत","de":"Zahn","fr":"Dent","it":"Dente","es":"Diente","es_eu":"Diente","es_mx":"Diente","pt":"Dente","pt_eu":"Dente","pt_br":"Dente","ru":"Зуб","uk":"Зуб","ar":"سن","he":"שן","sw":"Jino"},"definition":{"en":"One tooth, citation form. The singular noun for an ordinary tooth — not the collective \"teeth\", not a tusk or fang, and not a compound naming one kind (molar, incisor). Where a language splits the front teeth from the back, the general or front-tooth word is taken.","ja":"歯（一本）、辞書形。ふつうの歯を指す単数形であり、集合としての「歯」でも、牙でも、種類を限定した複合語（臼歯・門歯）でもない。前歯と奥歯を語彙的に分ける言語では、総称または前歯の語を採る。","ko":"이 한 개, 사전형. 보통의 이를 가리키는 단수형이며, 집합으로서의 \"이빨\"이나 엄니, 어금니·앞니처럼 종류를 한정한 합성어가 아니다. 앞니와 어금니를 어휘적으로 구분하는 언어에서는 총칭 또는 앞니의 낱말을 싣는다.","zh":"一颗牙，词典形。指普通牙齿的单数名词——不取集合义的“牙齿”，不取獠牙，也不取限定种类的复合词（臼齿、门齿）。若语言把前齿与后齿分成两个词，取总称或前齿的那个。","yue":"一隻牙，詞典形。指普通牙齒嘅單數名詞——唔取集合義嘅「牙齒」，唔取獠牙，亦唔取限定種類嘅複合詞（臼齒、門齒）。若語言將前齒同後齒分成兩個詞，取總稱或者前齒嗰個。","vi":"Một cái răng, dạng từ điển. Danh từ số ít chỉ chiếc răng thông thường — không phải \"răng\" theo nghĩa tập hợp, không phải nanh, cũng không phải từ ghép chỉ một loại (răng hàm, răng cửa). Với ngôn ngữ tách răng trước khỏi răng sau, lấy từ tổng quát hoặc từ chỉ răng cửa.","th":"ฟันหนึ่งซี่ รูปพจนานุกรม เป็นคำนามเอกพจน์ที่หมายถึงฟันธรรมดา ไม่ใช่ \"ฟัน\" ในความหมายรวม ไม่ใช่เขี้ยว และไม่ใช่คำประสมที่ระบุชนิด (ฟันกราม ฟันหน้า) ภาษาที่แยกฟันหน้าออกจากฟันหลัง ให้เอาคำรวมหรือคำที่หมายถึงฟันหน้า","id":"Satu gigi, bentuk kamus. Nomina tunggal untuk gigi biasa — bukan \"gigi\" dalam arti kolektif, bukan taring, dan bukan gabungan yang menyebut satu jenis (geraham, gigi seri). Untuk bahasa yang memisahkan gigi depan dari gigi belakang, diambil kata umum atau kata gigi depan.","hi":"एक दाँत, शब्दकोश-रूप। साधारण दाँत का एकवचन नाम — समूहवाचक \"दाँत\" नहीं, न दंतशूल, न किसी एक प्रकार का समास (दाढ़, कृंतक)। जो भाषाएँ अगले और पिछले दाँतों को अलग शब्दों से कहती हैं, उनमें सामान्य या अगले दाँत का शब्द लिया गया है।","de":"Ein Zahn, Zitierform. Das Substantiv im Singular für einen gewöhnlichen Zahn — nicht das kollektive „Gebiss“, kein Hauer oder Fangzahn, und kein Kompositum für eine Sorte (Backenzahn, Schneidezahn). Trennt eine Sprache Vorder- von Backenzähnen, steht das allgemeine oder das Vorderzahn-Wort.","fr":"Une dent, forme de citation. Le nom au singulier pour une dent ordinaire — non le collectif « dents », ni une défense ou un croc, ni un composé désignant une sorte (molaire, incisive). Là où une langue sépare les dents de devant de celles du fond, on donne le mot général ou celui des dents de devant.","it":"Un dente, forma di citazione. Il sostantivo singolare per un dente comune — non il collettivo «denti», né una zanna, né un composto che nomina un tipo (molare, incisivo). Dove una lingua separa i denti anteriori da quelli posteriori, si dà la parola generale o quella dei denti anteriori.","es":"Un diente, forma de cita. El sustantivo en singular para un diente corriente — no el colectivo «dentadura», ni un colmillo, ni un compuesto que nombre una clase (muela, incisivo). Donde una lengua separa los dientes delanteros de los traseros, se da la palabra general o la de los delanteros.","es_eu":"Un diente, forma de cita. El sustantivo en singular para un diente corriente — no el colectivo «dentadura», ni un colmillo, ni un compuesto que nombre una clase (muela, incisivo). Donde una lengua separa los dientes delanteros de los traseros, se da la palabra general o la de los delanteros.","es_mx":"Un diente, forma de cita. El sustantivo en singular para un diente corriente — no el colectivo «dentadura», ni un colmillo, ni un compuesto que nombre una clase (muela, incisivo). Donde una lengua separa los dientes delanteros de los traseros, se da la palabra general o la de los delanteros.","pt":"Um dente, forma de citação. O substantivo no singular para um dente comum — não o coletivo «dentes», nem uma presa, nem um composto que nomeie um tipo (molar, incisivo). Onde uma língua separa os dentes da frente dos de trás, dá-se a palavra geral ou a dos dentes da frente.","pt_eu":"Um dente, forma de citação. O substantivo no singular para um dente comum — não o coletivo «dentes», nem uma presa, nem um composto que nomeie um tipo (molar, incisivo). Onde uma língua separa os dentes da frente dos de trás, dá-se a palavra geral ou a dos dentes da frente.","pt_br":"Um dente, forma de citação. O substantivo no singular para um dente comum — não o coletivo «dentes», nem uma presa, nem um composto que nomeie um tipo (molar, incisivo). Onde uma língua separa os dentes da frente dos de trás, dá-se a palavra geral ou a dos dentes da frente.","ru":"Один зуб, словарная форма. Существительное в единственном числе для обычного зуба — не собирательное «зубы», не клык или бивень, и не сложное слово для разновидности (коренной, резец). Если язык различает передние и задние зубы, берётся общее слово или слово для передних.","uk":"Один зуб, словникова форма. Іменник в однині для звичайного зуба — не збірне «зуби», не ікло чи бивень, і не складне слово для різновиду (кутній, різець). Якщо мова розрізняє передні та задні зуби, береться загальне слово або слово для передніх.","ar":"سِنٌّ واحدة، صيغة المعجم. الاسم المفرد للسن العادية — لا «الأسنان» بالمعنى الجمعي، ولا الناب، ولا مركّبًا يسمّي نوعًا بعينه (الضرس، القاطع). وحيث تفصل اللغة أسنان المقدّمة عن أسنان المؤخّرة، تُذكر الكلمة العامة أو كلمة أسنان المقدّمة.","he":"שן אחת, צורת מילון. שם העצם ביחיד לשן רגילה — לא \"שיניים\" במובן הקיבוצי, לא ניב או חט, ולא צירוף המציין סוג (טוחנת, חותכת). במקום ששפה מפרידה בין שיני הקדמה לשיני האחור, ניתנת המילה הכללית או זו של שיני הקדמה.","sw":"Jino moja, umbo la kamusi. Nomino ya umoja kwa jino la kawaida — si \"meno\" kwa maana ya jumla, wala pembe au chonge, wala mchanganyiko unaotaja aina moja (gego, kato). Pale lugha inapotenganisha meno ya mbele na ya nyuma, neno la jumla au la meno ya mbele ndilo lililotolewa."}},"hand":{"label":{"en":"Hand","ja":"手","ko":"손","zh":"手","yue":"手","vi":"Tay","th":"มือ","id":"Tangan","hi":"हाथ","de":"Hand","fr":"Main","it":"Mano","es":"Mano","es_eu":"Mano","es_mx":"Mano","pt":"Mão","pt_eu":"Mão","pt_br":"Mão","ru":"Рука","uk":"Рука","ar":"يد","he":"יד","sw":"Mkono"},"definition":{"en":"Hand (distal upper limb); not \"arm\". Some languages do not distinguish hand vs arm.","ja":"手（上肢の末端部）。「腕」ではない。手と腕を区別しない言語もある。","ko":"손 (팔의 말단부). \"팔\"이 아니다. 손과 팔을 구별하지 않는 언어도 있다.","zh":"手（上肢末端）；不是\"手臂\"。部分语言不区分手与手臂。","yue":"手（前臂末端）；唔係「手臂」。部分語言唔分手同臂。","vi":"Bàn tay (đầu xa của chi trên); không phải \"cánh tay\". Một số ngôn ngữ không tách hai khái niệm.","th":"มือ (ปลายแขนส่วนล่าง); ไม่ใช่ \"แขน\" บางภาษาไม่แยกสองคำนี้","id":"Tangan (ujung anggota atas); bukan \"lengan\". Beberapa bahasa tidak membedakan keduanya.","hi":"हाथ (बांह का सिरा); \"बांह\" नहीं। कुछ भाषाएँ हाथ-बांह में अंतर नहीं करतीं।","de":"Hand (distales Ende der oberen Extremität); nicht \"Arm\". Manche Sprachen unterscheiden Hand und Arm nicht.","fr":"Main (extrémité du membre supérieur); pas le \"bras\". Certaines langues ne les distinguent pas.","it":"Mano (estremità dell'arto superiore); non \"braccio\". Alcune lingue non li distinguono.","es":"Mano (extremo del miembro superior); no \"brazo\". Algunas lenguas no los distinguen.","es_eu":"Mano (extremo del miembro superior); no \"brazo\". Algunas lenguas no los distinguen.","es_mx":"Mano (extremo del miembro superior); no \"brazo\". Algunas lenguas no los distinguen.","pt":"Mão (extremidade do membro superior); não \"braço\". Algumas línguas não fazem essa distinção.","pt_eu":"Mão (extremidade do membro superior); não \"braço\". Algumas línguas não fazem essa distinção.","pt_br":"Mão (extremidade do membro superior); não \"braço\". Algumas línguas não fazem essa distinção.","ru":"Кисть руки (дистальная часть верхней конечности); не \"рука\" в значении \"плечо/предплечье\". В некоторых языках различия нет.","uk":"Кисть руки (дистальна частина верхньої кінцівки); не \"рука\" як \"плече/передпліччя\". У деяких мовах немає такого розрізнення.","ar":"اليد (طرف الذراع البعيد)؛ ليست \"الذراع\". بعض اللغات لا تفرق بينهما.","he":"כף יד (קצה הגפה העליונה); לא \"זרוע\". בחלק מהשפות אין הבחנה בין השתיים.","sw":"Mkono (sehemu ya mbali ya kiungo cha juu); si \"mkono mzima\" (kuanzia bega). Lugha kadhaa hazitofautishi."}},"heart":{"label":{"en":"Heart","ja":"心","ko":"마음","zh":"心","yue":"心","vi":"Tim","th":"ใจ","id":"Hati","hi":"दिल","de":"Herz","fr":"Cœur","it":"Cuore","es":"Corazón","es_eu":"Corazón","es_mx":"Corazón","pt":"Coração","pt_eu":"Coração","pt_br":"Coração","ru":"Сердце","uk":"Серце","ar":"قلب","he":"לב","sw":"Moyo"},"definition":{"en":"Default: the basic emotional/cognitive heart/mind term. Use anatomical heart only where it is the normal basic word; document the choice with wordEvidence.note.","ja":"既定: 感情・思考の中心としての「心」を表す基本語。解剖学的「心臓」は、それがその言語の基本語である場合のみ採用 (wordEvidence.note に記録)。","ko":"기본값: 감정·인지의 중심으로서의 \"마음\"을 나타내는 기본어. 해부학적 \"심장\"은 그것이 해당 언어의 기본 어휘인 경우에 한함 (wordEvidence.note에 기록).","zh":"默认：表示情感·认知中心的\"心\"的基本词。仅当解剖学\"心脏\"是该语言的基础词时使用，并在 wordEvidence.note 注明。","yue":"預設：作為情感／思維中心嘅「心」嘅基本詞。解剖學嘅「心臟」只喺嗰係該語言基本詞時用，並喺 wordEvidence.note 記錄。","vi":"Mặc định: từ cơ bản chỉ \"tim/lòng\" như trung tâm cảm xúc/tư duy. Dùng \"tim\" giải phẫu chỉ khi đó là từ cơ bản; ghi vào wordEvidence.note.","th":"ค่าเริ่มต้น: คำพื้นฐานสำหรับ \"ใจ/หัวใจ\" ในเชิงอารมณ์/ความคิด; ใช้ \"หัวใจ\" กายวิภาคเฉพาะเมื่อเป็นคำพื้นฐาน และระบุใน wordEvidence.note","id":"Default: kata dasar untuk \"hati\" sebagai pusat emosi/pikiran. Pakai jantung anatomis hanya bila itu kata dasar; catat di wordEvidence.note.","hi":"डिफ़ॉल्ट: भाव/मन के रूप में \"दिल/मन\" का मूल शब्द। शारीरिक \"हृदय\" तभी जब वह भाषा का मूल शब्द हो; wordEvidence.note में दर्ज करें।","de":"Standard: Grundwort für \"Herz/Gemüt\" als Sitz des Empfindens. Anatomisches Herz nur, wenn es die übliche Grundform ist; in wordEvidence.note vermerken.","fr":"Par défaut : mot de base pour \"cœur/esprit\" comme siège des émotions. Le cœur anatomique est admis seulement si c'est le terme courant; à noter via wordEvidence.note.","it":"Predefinito: parola base per \"cuore/mente\" come sede emotiva. Il cuore anatomico è usato solo se è il termine corrente; documentare con wordEvidence.note.","es":"Por defecto: palabra base para \"corazón/mente\" emocional. El corazón anatómico se usa solo si es la palabra básica; documentar en wordEvidence.note.","es_eu":"Por defecto: palabra base para \"corazón/mente\" emocional. El corazón anatómico se usa solo si es la palabra básica; documentar en wordEvidence.note.","es_mx":"Por defecto: palabra base para \"corazón/mente\" emocional. El corazón anatómico se usa solo si es la palabra básica; documentar en wordEvidence.note.","pt":"Padrão: palavra base para \"coração/mente\" emocional. O coração anatómico só quando é a palavra básica; registar em wordEvidence.note.","pt_eu":"Padrão: palavra base para \"coração/mente\" emocional. O coração anatómico só quando é a palavra básica; registar em wordEvidence.note.","pt_br":"Padrão: palavra base para \"coração/mente\" emocional. O coração anatômico só quando é a palavra básica; registrar em wordEvidence.note.","ru":"По умолчанию: базовое слово для \"сердце/душа\" как центра чувств. Анатомическое сердце — только если это основная лексема языка; фиксируйте в wordEvidence.note.","uk":"За замовчуванням: базове слово для \"серце/душа\" як осередку чуттів. Анатомічне серце — лише якщо це основне слово мови; занотовуйте у wordEvidence.note.","ar":"الافتراضي: كلمة \"القلب/الفؤاد\" بوصفها مركز العاطفة. القلب التشريحي فقط إذا كان الكلمة الأساسية في اللغة؛ يُوثَّق في wordEvidence.note.","he":"ברירת מחדל: המילה הבסיסית ל\"לב/נפש\" כמוקד רגש/מחשבה. לב אנטומי — רק אם זו המילה הבסיסית בשפה; לתעד ב־wordEvidence.note.","sw":"Chaguo-msingi: neno la msingi la \"moyo/akili\" kama kitovu cha hisia. \"Moyo\" wa kianatomia hutumika tu ikiwa ndilo neno la msingi; weka noti katika wordEvidence.note."}},"blood":{"label":{"en":"Blood","ja":"血","ko":"피","zh":"血","yue":"血","vi":"Máu","th":"เลือด","id":"Darah","hi":"खून","de":"Blut","fr":"Sang","it":"Sangue","es":"Sangre","es_eu":"Sangre","es_mx":"Sangre","pt":"Sangue","pt_eu":"Sangue","pt_br":"Sangue","ru":"Кровь","uk":"Кров","ar":"دم","he":"דם","sw":"Damu"},"definition":{"en":"The red fluid that circulates in the body, citation form. The plain mass noun (\"lose blood\"), not the sense \"lineage/descent\", and not a compound such as \"blood vessel\". Where nouns are obligatorily possessed, the citation stem is given.","ja":"体内をめぐる赤い液体、辞書形。素の物質名詞（「血が出る」の「血」）であり、「血統」の意でも「血管」のような複合語でもない。所有形が必須の言語では引用形（語幹）を挙げる。","ko":"몸속을 도는 붉은 액체, 사전형. 물질명사 그대로의 뜻이며 \"혈통\"의 뜻이나 \"혈관\" 같은 합성어가 아니다. 소유형이 필수인 언어에서는 인용형(어간)을 싣는다.","zh":"体内循环的红色液体，词典形。取物质名词本义（“流血”的“血”），不取“血统”义，也不取“血管”一类复合词。名词必须带领属的语言取引用词干。","yue":"體內循環嘅紅色液體，詞典形。取物質名詞本義（「流血」嘅「血」），唔係「血統」義，亦唔係「血管」嗰類複合詞。名詞必須帶領屬嘅語言取引用詞幹。","vi":"Chất lỏng màu đỏ chảy trong cơ thể, dạng từ điển. Lấy nghĩa danh từ khối thông thường (\"chảy máu\"), không phải nghĩa \"dòng dõi\", cũng không phải từ ghép như \"mạch máu\". Với ngôn ngữ danh từ bắt buộc có sở hữu, lấy dạng trích dẫn.","th":"ของเหลวสีแดงที่ไหลเวียนในร่างกาย รูปพจนานุกรม เป็นคำนามมวลสารตามปกติ (\"เลือดออก\") ไม่ใช่ความหมาย \"เชื้อสาย\" และไม่ใช่คำประสมอย่าง \"เส้นเลือด\" ภาษาที่คำนามต้องมีรูปแสดงความเป็นเจ้าของ ใช้รูปอ้างอิง","id":"Cairan merah yang beredar dalam tubuh, bentuk kamus. Nomina massa biasa (\"berdarah\"), bukan makna \"keturunan\", bukan pula gabungan seperti \"pembuluh darah\". Untuk bahasa dengan nomina wajib berpemilik, diberikan bentuk kutipan.","hi":"शरीर में बहने वाला लाल तरल, शब्दकोश-रूप। सामान्य द्रव्यवाचक संज्ञा (\"खून बहना\"), \"वंश\" के अर्थ में नहीं और \"रक्तवाहिनी\" जैसे समास में नहीं। जिन भाषाओं में संज्ञा अनिवार्यतः सम्बन्धसूचक होती है, वहाँ उद्धरण-रूप दिया गया है।","de":"Die rote Körperflüssigkeit, Zitierform. Das schlichte Stoffsubstantiv („Blut verlieren“), nicht der Sinn „Abstammung“ und kein Kompositum wie „Blutgefäß“. Bei Sprachen mit obligatorisch possessiven Nomen steht die Zitierform.","fr":"Le liquide rouge qui circule dans le corps, forme de citation. Le nom massif ordinaire (« perdre du sang »), non le sens « lignée », ni un composé comme « vaisseau sanguin ». Pour les langues à noms obligatoirement possédés, on donne la forme de citation.","it":"Il liquido rosso che circola nel corpo, forma di citazione. Il sostantivo di massa comune («perdere sangue»), non il senso «stirpe» né un composto come «vaso sanguigno». Per le lingue con nomi obbligatoriamente posseduti si dà la forma di citazione.","es":"El líquido rojo que circula por el cuerpo, forma de cita. El sustantivo de masa corriente («perder sangre»), no el sentido «linaje» ni un compuesto como «vaso sanguíneo». En lenguas con sustantivos de posesión obligatoria se da la forma de cita.","es_eu":"El líquido rojo que circula por el cuerpo, forma de cita. El sustantivo de masa corriente («perder sangre»), no el sentido «linaje» ni un compuesto como «vaso sanguíneo». En lenguas con sustantivos de posesión obligatoria se da la forma de cita.","es_mx":"El líquido rojo que circula por el cuerpo, forma de cita. El sustantivo de masa corriente («perder sangre»), no el sentido «linaje» ni un compuesto como «vaso sanguíneo». En lenguas con sustantivos de posesión obligatoria se da la forma de cita.","pt":"O líquido vermelho que circula no corpo, forma de citação. O substantivo de massa comum («perder sangue»), não o sentido «linhagem» nem um composto como «vaso sanguíneo». Em línguas com substantivos de posse obrigatória, dá-se a forma de citação.","pt_eu":"O líquido vermelho que circula no corpo, forma de citação. O substantivo de massa comum («perder sangue»), não o sentido «linhagem» nem um composto como «vaso sanguíneo». Em línguas com substantivos de posse obrigatória, dá-se a forma de citação.","pt_br":"O líquido vermelho que circula no corpo, forma de citação. O substantivo de massa comum («perder sangue»), não o sentido «linhagem» nem um composto como «vaso sanguíneo». Em línguas com substantivos de posse obrigatória, dá-se a forma de citação.","ru":"Красная жидкость, циркулирующая в теле, словарная форма. Обычное вещественное существительное («терять кровь»), не значение «род, происхождение» и не сложное слово вроде «кровеносный сосуд». В языках с обязательной посессивностью даётся цитатная форма.","uk":"Червона рідина, що циркулює в тілі, словникова форма. Звичайний речовинний іменник («втрачати кров»), не значення «рід, походження» і не складне слово на кшталт «кровоносна судина». У мовах з обовʼязковою присвійністю подано цитатну форму.","ar":"السائل الأحمر الذي يجري في الجسم، صيغة المعجم. اسم المادة العادي («نزف الدم»)، لا بمعنى «النسب» ولا مركّبًا مثل «وعاء دموي». وفي اللغات التي تلزم فيها الإضافة، تُذكر صيغة الاستشهاد.","he":"הנוזל האדום הזורם בגוף, צורת מילון. שם עצם חומרי רגיל (\"לאבד דם\"), לא במובן \"ייחוס\" ולא צירוף כמו \"כלי דם\". בשפות שבהן שם העצם חייב נטיית קניין, ניתנת צורת הציטוט.","sw":"Umajimaji mwekundu unaozunguka mwilini, umbo la kamusi. Nomino ya kawaida ya kiasi (\"kutokwa damu\"), si maana ya \"ukoo\" wala mchanganyiko kama \"mshipa wa damu\". Katika lugha ambazo nomino lazima iwe na mmiliki, umbo la kunukuu limetolewa."}},"tongue":{"label":{"en":"Tongue","ja":"舌","ko":"혀","zh":"舌头","yue":"脷","vi":"Lưỡi","th":"ลิ้น","id":"Lidah","hi":"जीभ","de":"Zunge","fr":"Langue","it":"Lingua","es":"Lengua","es_eu":"Lengua","es_mx":"Lengua","pt":"Língua","pt_eu":"Língua","pt_br":"Língua","ru":"Язык","uk":"Язик","ar":"لسان","he":"לשון","sw":"Ulimi"},"definition":{"en":"The muscular organ in the mouth, citation form. The body part only — not the derived sense \"language\" (\"mother tongue\"), which many of these same words also carry, and not a compound. Where nouns are obligatorily possessed, the citation stem is given.","ja":"口の中の筋肉器官、辞書形。身体部位の意味のみを採る——同じ語が担うことの多い「言語」の意（「母語」）ではなく、複合語でもない。所有形が必須の言語では引用形（語幹）を挙げる。","ko":"입 안의 근육 기관, 사전형. 신체 부위의 뜻만 취하며, 같은 낱말이 흔히 함께 지니는 \"언어\"의 뜻(모국어)이나 합성어가 아니다. 소유형이 필수인 언어에서는 인용형(어간)을 싣는다.","zh":"口腔中的肌肉器官，词典形。只取身体部位义——不取同一个词常兼有的“语言”义（“母语”），也不取复合词。名词必须带领属的语言取引用词干。","yue":"口腔入面嘅肌肉器官，詞典形。只取身體部位義——唔取同一個詞常兼有嘅「語言」義（「母語」），亦唔取複合詞。名詞必須帶領屬嘅語言取引用詞幹。","vi":"Cơ quan cơ bắp trong miệng, dạng từ điển. Chỉ lấy nghĩa bộ phận cơ thể — không lấy nghĩa \"ngôn ngữ\" mà chính những từ này thường kiêm (\"tiếng mẹ đẻ\"), cũng không phải từ ghép. Với ngôn ngữ danh từ bắt buộc có sở hữu, lấy dạng trích dẫn.","th":"อวัยวะกล้ามเนื้อในช่องปาก รูปพจนานุกรม เอาเฉพาะความหมายอวัยวะ ไม่เอาความหมาย \"ภาษา\" ที่คำเดียวกันมักมีด้วย (\"ภาษาแม่\") และไม่ใช่คำประสม ภาษาที่คำนามต้องมีรูปแสดงความเป็นเจ้าของ ใช้รูปอ้างอิง","id":"Organ berotot di dalam mulut, bentuk kamus. Hanya makna bagian tubuh — bukan makna \"bahasa\" yang sering juga dibawa kata yang sama (\"bahasa ibu\"), dan bukan gabungan. Untuk bahasa dengan nomina wajib berpemilik, diberikan bentuk kutipan.","hi":"मुँह के भीतर की माँसपेशीय इंद्रिय, शब्दकोश-रूप। केवल शरीर-अंग का अर्थ — वही शब्द जो प्रायः \"भाषा\" का अर्थ भी रखता है (\"मातृभाषा\"), वह अर्थ यहाँ नहीं, और न ही कोई समास। जिन भाषाओं में संज्ञा अनिवार्यतः सम्बन्धसूचक होती है, वहाँ उद्धरण-रूप दिया गया है।","de":"Das Muskelorgan im Mund, Zitierform. Nur das Körperteil — nicht die Bedeutung „Sprache“, die viele derselben Wörter mittragen („Muttersprache“), und kein Kompositum. Bei Sprachen mit obligatorisch possessiven Nomen steht die Zitierform.","fr":"L’organe musculaire de la bouche, forme de citation. Seulement la partie du corps — non le sens « langue (idiome) » que portent souvent ces mêmes mots (« langue maternelle »), ni un composé. Pour les langues à noms obligatoirement possédés, on donne la forme de citation.","it":"L’organo muscolare della bocca, forma di citazione. Solo la parte del corpo — non il senso «lingua (idioma)» che molte di queste stesse parole portano («lingua madre»), né un composto. Per le lingue con nomi obbligatoriamente posseduti si dà la forma di citazione.","es":"El órgano muscular de la boca, forma de cita. Solo la parte del cuerpo — no el sentido «idioma» que muchas de estas mismas palabras también llevan («lengua materna»), ni un compuesto. En lenguas con sustantivos de posesión obligatoria se da la forma de cita.","es_eu":"El órgano muscular de la boca, forma de cita. Solo la parte del cuerpo — no el sentido «idioma» que muchas de estas mismas palabras también llevan («lengua materna»), ni un compuesto. En lenguas con sustantivos de posesión obligatoria se da la forma de cita.","es_mx":"El órgano muscular de la boca, forma de cita. Solo la parte del cuerpo — no el sentido «idioma» que muchas de estas mismas palabras también llevan («lengua materna»), ni un compuesto. En lenguas con sustantivos de posesión obligatoria se da la forma de cita.","pt":"O órgão muscular da boca, forma de citação. Apenas a parte do corpo — não o sentido «idioma» que muitas destas mesmas palavras também carregam («língua materna»), nem um composto. Em línguas com substantivos de posse obrigatória, dá-se a forma de citação.","pt_eu":"O órgão muscular da boca, forma de citação. Apenas a parte do corpo — não o sentido «idioma» que muitas destas mesmas palavras também carregam («língua materna»), nem um composto. Em línguas com substantivos de posse obrigatória, dá-se a forma de citação.","pt_br":"O órgão muscular da boca, forma de citação. Apenas a parte do corpo — não o sentido «idioma» que muitas destas mesmas palavras também carregam («língua materna»), nem um composto. Em línguas com substantivos de posse obrigatória, dá-se a forma de citação.","ru":"Мышечный орган во рту, словарная форма. Только часть тела — не значение «язык (речь)», которое часто несут те же слова («родной язык»), и не сложное слово. В языках с обязательной посессивностью даётся цитатная форма.","uk":"Мʼязовий орган у роті, словникова форма. Лише частина тіла — не значення «мова», яке часто мають ті самі слова («рідна мова»), і не складне слово. У мовах з обовʼязковою присвійністю подано цитатну форму.","ar":"العضو العضلي في الفم، صيغة المعجم. الجزء من الجسم فقط — لا معنى «اللغة» الذي تحمله كثير من هذه الكلمات نفسها («اللغة الأم»)، ولا مركّبًا. وفي اللغات التي تلزم فيها الإضافة، تُذكر صيغة الاستشهاد.","he":"האיבר השרירי שבפה, צורת מילון. אך ורק איבר הגוף — לא במובן \"שפה\" שרבות מאותן מילים נושאות גם (\"שפת אם\"), ולא צירוף. בשפות שבהן שם העצם חייב נטיית קניין, ניתנת צורת הציטוט.","sw":"Kiungo cha misuli kilicho mdomoni, umbo la kamusi. Sehemu ya mwili tu — si maana ya \"lugha\" ambayo maneno hayohayo mara nyingi hubeba (\"lugha mama\"), wala mchanganyiko. Katika lugha ambazo nomino lazima iwe na mmiliki, umbo la kunukuu limetolewa."}},"love":{"label":{"en":"Love","ja":"愛","ko":"사랑","zh":"爱","yue":"愛","vi":"Yêu","th":"รัก","id":"Cinta","hi":"प्रेम","de":"Liebe","fr":"Amour","it":"Amore","es":"Amor","es_eu":"Amor","es_mx":"Amor","pt":"Amor","pt_eu":"Amor","pt_br":"Amor","ru":"Любовь","uk":"Любов","ar":"حب","he":"אהבה","sw":"Upendo"},"definition":{"en":"Basic word/root for love or affection — noun or verb citation form depending on language; not a greeting.","ja":"愛・愛情を表す基本語・語根。言語により名詞または動詞の辞書形。挨拶ではない。","ko":"사랑·애정을 나타내는 기본 단어/어근. 언어에 따라 명사 또는 동사 사전형. 인사가 아니다.","zh":"表示爱或感情的基础词/词根；视语言而定，名词或动词词典形式。不是问候语。","yue":"表示愛、情感嘅基本詞／字根；按語言而定為名詞或動詞詞典形；唔係問候語。","vi":"Từ/gốc cơ bản chỉ tình yêu hoặc tình cảm; danh từ hoặc động từ tuỳ ngôn ngữ; không phải lời chào.","th":"คำหรือรากศัพท์พื้นฐานสำหรับ \"รัก\"; รูปคำนาม/กริยาตามภาษา; ไม่ใช่คำทักทาย","id":"Kata/akar dasar untuk cinta atau kasih; kata benda atau verba sesuai bahasa; bukan sapaan.","hi":"\"प्रेम\" का मूल शब्द; भाषा के अनुसार संज्ञा या क्रिया रूप; अभिवादन नहीं।","de":"Grundwort/Stamm für Liebe oder Zuneigung; Substantiv oder Verb je nach Sprache; keine Begrüßung.","fr":"Mot/racine de \"amour\" ou affection; nom ou verbe selon la langue; pas un salut.","it":"Parola/radice base per amore o affetto; nome o verbo a seconda della lingua; non è un saluto.","es":"Palabra/raíz base para amor o afecto; sustantivo o verbo según la lengua; no es un saludo.","es_eu":"Palabra/raíz base para amor o afecto; sustantivo o verbo según la lengua; no es un saludo.","es_mx":"Palabra/raíz base para amor o afecto; sustantivo o verbo según la lengua; no es un saludo.","pt":"Palavra/raiz base para amor ou afeto; substantivo ou verbo conforme a língua; não é saudação.","pt_eu":"Palavra/raiz base para amor ou afeto; substantivo ou verbo conforme a língua; não é saudação.","pt_br":"Palavra/raiz base para amor ou afeto; substantivo ou verbo conforme a língua; não é saudação.","ru":"Базовое слово/корень \"любовь\" или привязанность; существительное или глагол в зависимости от языка; не приветствие.","uk":"Базове слово/корінь \"любов\" чи прихильність; іменник або дієслово залежно від мови; не привітання.","ar":"كلمة/جذر أساسي للحب أو المودة؛ اسم أو فعل بحسب اللغة؛ ليس تحية.","he":"מילה/שורש בסיסי ל\"אהבה\" או חיבה; שם עצם או פועל לפי שפה; לא ברכה.","sw":"Neno/shina la msingi la upendo au kupendana; nomino au kitenzi kulingana na lugha; si salamu."}},"tree":{"label":{"en":"Tree","ja":"木","ko":"나무","zh":"树","yue":"樹","vi":"Cây","th":"ต้นไม้","id":"Pohon","hi":"पेड़","de":"Baum","fr":"Arbre","it":"Albero","es":"Árbol","es_eu":"Árbol","es_mx":"Árbol","pt":"Árvore","pt_eu":"Árvore","pt_br":"Árvore","ru":"Дерево","uk":"Дерево","ar":"شجرة","he":"עץ","sw":"Mti"},"definition":{"en":"Tree (woody plant); not specifically a tree species or \"wood\".","ja":"木（木本植物）。特定の樹種や「木材」ではない。","ko":"나무 (목본 식물). 특정 수종이나 \"목재\"가 아니다.","zh":"树（木本植物）；不特指树种或\"木材\"。","yue":"樹（木本植物）；唔係指特定樹種或者「木材」。","vi":"Cây gỗ; không phải một loài cây cụ thể hay \"gỗ\".","th":"ต้นไม้ (พืชยืนต้น); ไม่ใช่ชื่อชนิดต้นไม้ หรือ \"ไม้\" (วัสดุ)","id":"Pohon (tumbuhan berkayu); bukan spesies tertentu atau \"kayu\".","hi":"काष्ठीय पौधा (पेड़); किसी विशेष प्रजाति या \"लकड़ी\" नहीं।","de":"Baum (Holzgewächs); nicht eine bestimmte Baumart oder \"Holz\".","fr":"Arbre (plante ligneuse); pas une espèce particulière ni \"bois\".","it":"Albero (pianta legnosa); non una specie particolare né \"legno\".","es":"Árbol (planta leñosa); no una especie concreta ni \"madera\".","es_eu":"Árbol (planta leñosa); no una especie concreta ni \"madera\".","es_mx":"Árbol (planta leñosa); no una especie concreta ni \"madera\".","pt":"Árvore (planta lenhosa); não uma espécie nem \"madeira\".","pt_eu":"Árvore (planta lenhosa); não uma espécie nem \"madeira\".","pt_br":"Árvore (planta lenhosa); não uma espécie nem \"madeira\".","ru":"Дерево (древесное растение); не вид и не \"древесина\".","uk":"Дерево (деревна рослина); не вид і не \"деревина\".","ar":"الشجرة (نبات خشبي)؛ ليست نوعًا محددًا ولا تعني \"الخشب\".","he":"עץ (צמח מעוצה); לא מין ספציפי ולא \"עץ\" כחומר.","sw":"Mti (mmea wa miti); si aina maalum wala si \"mbao\"."}},"house":{"label":{"en":"House","ja":"家","ko":"집","zh":"房子","yue":"屋","vi":"Nhà","th":"บ้าน","id":"Rumah","hi":"घर","de":"Haus","fr":"Maison","it":"Casa","es":"Casa","es_eu":"Casa","es_mx":"Casa","pt":"Casa","pt_eu":"Casa","pt_br":"Casa","ru":"Дом","uk":"Дім","ar":"بيت","he":"בית","sw":"Nyumba"},"definition":{"en":"House / dwelling — the natural everyday word for one's residence; in some varieties this surfaces as a locative compound (e.g. \"in-the-house\") that has lexicalized as \"house/home\".","ja":"家・住居。住居を指す自然な日常語。変種によっては位置詞構造(例:「家の中」)が「家・うち」として語彙化された形を取ることがある。","ko":"집/주거 — 거주지를 가리키는 자연스러운 일상어. 일부 변종에서는 위치 구문(예: \"집 안\")이 \"집/집안\"으로 어휘화된 형태로 나타나기도 한다.","zh":"房屋/住所——指住所的日常用语；某些方言中由方位短语(如\"屋里\")词汇化为表示\"家/住所\"的词。","yue":"屋／住所——指住所嘅日常用語；某啲方言中由方位短語(例如「屋裏」)詞彙化為表示「家／住所」嘅詞。","vi":"Nhà / nơi cư trú — từ thường dùng chỉ chỗ ở; ở một số biến thể có thể là cụm định vị (ví dụ \"trong nhà\") được từ vựng hóa thành \"nhà\".","th":"บ้าน/ที่อยู่อาศัย — คำที่ใช้ในชีวิตประจำวันสำหรับที่อยู่; ในบางสำเนียงอาจเป็นวลีบอกตำแหน่ง (เช่น \"ในบ้าน\") ที่ถูกทำให้กลายเป็นคำหมายถึง \"บ้าน\"","id":"Rumah / tempat tinggal — kata sehari-hari untuk tempat tinggal; pada sebagian varietas dapat berupa frasa lokatif (mis. \"di dalam rumah\") yang terleksikalisasi menjadi \"rumah\".","hi":"घर/आवास — निवास के लिए सामान्य रोज़मर्रा का शब्द; कुछ बोलियों में स्थानवाचक यौगिक (जैसे \"घर के अंदर\") \"घर/आवास\" के अर्थ में शब्दीकृत हो जाता है।","de":"Haus / Wohnung — das alltägliche Wort für den eigenen Wohnsitz; in manchen Varietäten erscheint es als lokatives Kompositum (z. B. \"im Haus\"), das als \"Haus/Zuhause\" lexikalisiert ist.","fr":"Maison / habitation — terme courant pour le lieu de résidence; dans certaines variétés peut apparaître sous forme de composé locatif (ex. \"à l'intérieur de la maison\") lexicalisé comme \"maison/chez-soi\".","it":"Casa / abitazione — termine quotidiano per la residenza; in alcune varietà può essere un composto locativo (es. \"dentro casa\") lessicalizzato come \"casa\".","es":"Casa / vivienda — palabra cotidiana para el lugar de residencia; en algunas variedades puede ser un compuesto locativo (p. ej. \"dentro de la casa\") lexicalizado como \"casa\".","es_eu":"Casa / vivienda — palabra cotidiana para el lugar de residencia; en algunas variedades puede ser un compuesto locativo (p. ej. \"dentro de la casa\") lexicalizado como \"casa\".","es_mx":"Casa / vivienda — palabra cotidiana para el lugar de residencia; en algunas variedades puede ser un compuesto locativo (p. ej. \"dentro de la casa\") lexicalizado como \"casa\".","pt":"Casa / habitação — palavra cotidiana para o local de residência; em algumas variedades pode ser um composto locativo (ex. \"dentro de casa\") lexicalizado como \"casa\".","pt_eu":"Casa / habitação — palavra cotidiana para o local de residência; em algumas variedades pode ser um composto locativo (ex. \"dentro de casa\") lexicalizado como \"casa\".","pt_br":"Casa / habitação — palavra cotidiana para o local de residência; em algumas variedades pode ser um composto locativo (ex. \"dentro de casa\") lexicalizado como \"casa\".","ru":"Дом / жильё — обычное слово для места проживания; в некоторых вариантах может выступать как локативная конструкция (например, \"в доме\"), лексикализованная как \"дом\".","uk":"Дім / житло — повсякденне слово для місця проживання; у деяких варіантах може бути локативною конструкцією (наприклад, \"у домі\"), лексикалізованою як \"дім\".","ar":"البيت / المسكن — كلمة يومية للإقامة؛ قد يكون في بعض اللهجات تركيبًا ظرفيًّا (مثل \"داخل البيت\") اكتسب معنى \"البيت\" بالاستخدام.","he":"בית / מעון — מילה יומיומית למקום מגורים; בכמה ניבים יכול להיות צירוף לוקטיבי (לדוגמה \"בתוך הבית\") שעבר לקסיקליזציה למשמעות \"בית\".","sw":"Nyumba / makazi — neno la kila siku la makazi; katika baadhi ya lahaja laweza kuwa kifungu cha mahali (mfano \"ndani ya nyumba\") kilichotwaliwa kuwa neno la \"nyumba\"."}},"dog":{"label":{"en":"Dog","ja":"犬","ko":"개","zh":"狗","yue":"狗","vi":"Chó","th":"หมา","id":"Anjing","hi":"कुत्ता","de":"Hund","fr":"Chien","it":"Cane","es":"Perro","es_eu":"Perro","es_mx":"Perro","pt":"Cão","pt_eu":"Cão","pt_br":"Cachorro","ru":"Собака","uk":"Собака","ar":"كلب","he":"כלב","sw":"Mbwa"},"definition":{"en":"Domestic dog (Canis familiaris); generic, not a breed or sex-specific.","ja":"家畜化されたイヌ (Canis familiaris)。一般語、犬種や性別を限定しない。","ko":"가축화된 개 (Canis familiaris). 일반어, 견종이나 성별을 한정하지 않음.","zh":"家犬 (Canis familiaris)；通称，不指特定品种或性别。","yue":"家犬 (Canis familiaris)；通稱，唔指品種或者性別。","vi":"Chó nhà (Canis familiaris); chung chung, không phân biệt giống hay giới tính.","th":"สุนัขบ้าน (Canis familiaris); คำกลาง ไม่ระบุพันธุ์หรือเพศ","id":"Anjing peliharaan (Canis familiaris); umum, bukan ras atau kelamin tertentu.","hi":"पालतू कुत्ता (Canis familiaris); सामान्य, नस्ल या लिंग सीमित नहीं।","de":"Haushund (Canis familiaris); generisch, nicht rasse- oder geschlechtsspezifisch.","fr":"Chien domestique (Canis familiaris); générique, sans race ni sexe.","it":"Cane domestico (Canis familiaris); generico, non specifico per razza o sesso.","es":"Perro doméstico (Canis familiaris); genérico, sin raza ni sexo.","es_eu":"Perro doméstico (Canis familiaris); genérico, sin raza ni sexo.","es_mx":"Perro doméstico (Canis familiaris); genérico, sin raza ni sexo.","pt":"Cão doméstico (Canis familiaris); genérico, sem raça ou sexo.","pt_eu":"Cão doméstico (Canis familiaris); genérico, sem raça ou sexo.","pt_br":"Cachorro doméstico (Canis familiaris); genérico, sem raça ou sexo.","ru":"Домашняя собака (Canis familiaris); обобщённое слово, без породы и пола.","uk":"Домашній собака (Canis familiaris); загальне, без породи й статі.","ar":"الكلب الأليف (Canis familiaris)؛ كلمة عامة، دون تحديد سلالة أو جنس.","he":"כלב ביתי (Canis familiaris); כללי, ללא ציון גזע או מין.","sw":"Mbwa wa kufugwa (Canis familiaris); jumla, si aina au jinsia maalum."}},"cat":{"label":{"en":"Cat","ja":"猫","ko":"고양이","zh":"猫","yue":"貓","vi":"Mèo","th":"แมว","id":"Kucing","hi":"बिल्ली","de":"Katze","fr":"Chat","it":"Gatto","es":"Gato","es_eu":"Gato","es_mx":"Gato","pt":"Gato","pt_eu":"Gato","pt_br":"Gato","ru":"Кошка","uk":"Кішка","ar":"قطة","he":"חתול","sw":"Paka"},"definition":{"en":"Generic domestic cat (Felis catus); use the normal generic/citation form for that language, and note gender (in wordEvidence.note) if it matters.","ja":"一般的な家猫 (Felis catus)。各言語の通常の一般形・辞書形を用い、性別が重要な場合は wordEvidence.note に記録。","ko":"일반 집고양이 (Felis catus). 각 언어의 통상적 일반형/사전형을 사용하고, 성별이 중요하면 wordEvidence.note에 기록.","zh":"一般家猫 (Felis catus)；使用各语言的通常通用/词典形式，若性别有意义则在 wordEvidence.note 注明。","yue":"一般家貓 (Felis catus)；用每種語言通用詞典形，性別重要時喺 wordEvidence.note 記錄。","vi":"Mèo nhà (Felis catus); dùng dạng từ điển chung; ghi giới tính nếu cần.","th":"แมวบ้านทั่วไป (Felis catus); ใช้รูปคำกลาง; ระบุเพศหากจำเป็นใน wordEvidence.note","id":"Kucing peliharaan (Felis catus); pakai bentuk kamus standar; catat kelamin bila perlu.","hi":"पालतू बिल्ली (Felis catus); सामान्य/शब्दकोश रूप; लिंग आवश्यक हो तो wordEvidence.note में दर्ज।","de":"Hauskatze (Felis catus); Standard-Wörterbuchform; Geschlecht bei Bedarf in wordEvidence.note.","fr":"Chat domestique (Felis catus); forme lexicale générique; sexe noté via wordEvidence.note si pertinent.","it":"Gatto domestico (Felis catus); forma lessicale generica; sesso annotato in wordEvidence.note se rilevante.","es":"Gato doméstico (Felis catus); forma genérica/de diccionario; sexo en wordEvidence.note si importa.","es_eu":"Gato doméstico (Felis catus); forma genérica/de diccionario; sexo en wordEvidence.note si importa.","es_mx":"Gato doméstico (Felis catus); forma genérica/de diccionario; sexo en wordEvidence.note si importa.","pt":"Gato doméstico (Felis catus); forma de dicionário; sexo em wordEvidence.note se relevante.","pt_eu":"Gato doméstico (Felis catus); forma de dicionário; sexo em wordEvidence.note se relevante.","pt_br":"Gato doméstico (Felis catus); forma de dicionário; sexo em wordEvidence.note se relevante.","ru":"Домашняя кошка (Felis catus); обычная словарная форма; пол — в wordEvidence.note, если важен.","uk":"Домашня кішка (Felis catus); звичайна словникова форма; стать — у wordEvidence.note, якщо важлива.","ar":"القط الأليف (Felis catus)؛ الصيغة العامة/المعجمية؛ الجنس يُذكر في wordEvidence.note عند الحاجة.","he":"חתול ביתי (Felis catus); צורת מילון כללית; מין יתועד ב־wordEvidence.note אם רלוונטי.","sw":"Paka wa nyumbani (Felis catus); umbo la kamusi/la kawaida; jinsia katika wordEvidence.note inapohitajika."}},"fish":{"label":{"en":"Fish","ja":"魚","ko":"물고기","zh":"鱼","yue":"魚","vi":"Cá","th":"ปลา","id":"Ikan","hi":"मछली","de":"Fisch","fr":"Poisson","it":"Pesce","es":"Pez","es_eu":"Pez","es_mx":"Pez","pt":"Peixe","pt_eu":"Peixe","pt_br":"Peixe","ru":"Рыба","uk":"Риба","ar":"سمكة","he":"דג","sw":"Samaki"},"definition":{"en":"NOUN \"fish\" = the live aquatic animal, singular. Not fish as food/flesh where the language separates them (es pescado, ko 생선, ja 魚 covers both), not \"to fish\", and not a specific species.","ja":"名詞「魚」＝水中に生きる動物としての魚、単数形。食材としての魚と語が分かれる言語ではそちら（es pescado、ko 생선）ではない。「釣る」という動詞や特定の魚種でもない。","ko":"명사 \"물고기\" = 물에 사는 동물로서의 물고기, 단수형. 식재료를 따로 이르는 언어에서는 그 말(es pescado, ko 생선)이 아니다. \"낚다\"라는 동사나 특정 어종도 아니다.","zh":"名词\"鱼\"＝作为水生动物的鱼，单数。若该语言区分食用鱼，则不取食用义（es pescado、ko 생선）；也不是动词\"钓鱼\"或某一具体鱼类。","yue":"名詞「魚」＝作為水生動物嘅魚，單數。如果嗰種語言分開食用魚，唔取食用義（es pescado、ko 생선）；亦唔係動詞「釣魚」或者某一種魚。","vi":"Danh từ \"cá\" = con vật sống dưới nước, số ít. Không phải cá làm thức ăn ở những ngôn ngữ tách riêng (es pescado, ko 생선), không phải động từ \"câu cá\", cũng không phải một loài cụ thể.","th":"คำนาม \"ปลา\" = สัตว์น้ำที่มีชีวิต รูปเอกพจน์ ไม่ใช่ปลาที่เป็นอาหารในภาษาที่แยกคำ (es pescado, ko 생선) ไม่ใช่กริยา \"ตกปลา\" และไม่ใช่ชนิดใดชนิดหนึ่ง","id":"Kata benda \"ikan\" = hewan air yang hidup, bentuk tunggal. Bukan ikan sebagai bahan makanan pada bahasa yang membedakannya (es pescado, ko 생선), bukan kata kerja \"memancing\", dan bukan spesies tertentu.","hi":"संज्ञा \"मछली\" = जल में रहने वाला जीव, एकवचन। जिन भाषाओं में खाद्य मछली का अलग शब्द है वहाँ वह नहीं (es pescado, ko 생선); न क्रिया \"मछली पकड़ना\", न कोई विशेष प्रजाति।","de":"Substantiv \"Fisch\" = das lebende Wassertier, Singular. Nicht Fisch als Speise, wo die Sprache trennt (es pescado, ko 생선), nicht das Verb \"angeln\" und keine bestimmte Art.","fr":"Nom \"poisson\" = l'animal aquatique vivant, au singulier. Pas le poisson comme aliment là où la langue distingue (es pescado, ko 생선), ni le verbe \"pêcher\", ni une espèce particulière.","it":"Sostantivo \"pesce\" = l'animale acquatico vivo, singolare. Non il pesce come alimento dove la lingua distingue (es pescado, ko 생선), non il verbo \"pescare\" né una specie particolare.","es":"Sustantivo \"pez\" = el animal acuático vivo, en singular. No \"pescado\" (el alimento), no el verbo \"pescar\" ni una especie concreta.","es_eu":"Sustantivo \"pez\" = el animal acuático vivo, en singular. No \"pescado\" (el alimento), no el verbo \"pescar\" ni una especie concreta.","es_mx":"Sustantivo \"pez\" = el animal acuático vivo, en singular. No \"pescado\" (el alimento), no el verbo \"pescar\" ni una especie concreta.","pt":"Substantivo \"peixe\" = o animal aquático vivo, no singular. Não o peixe como alimento onde a língua distingue (es pescado, ko 생선), não o verbo \"pescar\" nem uma espécie específica.","pt_eu":"Substantivo \"peixe\" = o animal aquático vivo, no singular. Não o peixe como alimento onde a língua distingue (es pescado, ko 생선), não o verbo \"pescar\" nem uma espécie específica.","pt_br":"Substantivo \"peixe\" = o animal aquático vivo, no singular. Não o peixe como alimento onde a língua distingue (es pescado, ko 생선), não o verbo \"pescar\" nem uma espécie específica.","ru":"Существительное \"рыба\" = живое водное животное, единственное число. Не рыба как еда там, где язык их различает (es pescado, ko 생선), не глагол \"ловить рыбу\" и не конкретный вид.","uk":"Іменник \"риба\" = жива водяна тварина, однина. Не риба як їжа там, де мова їх розрізняє (es pescado, ko 생선), не дієслово \"ловити рибу\" й не конкретний вид.","ar":"اسم \"سمكة\" = الحيوان المائي الحي، بصيغة المفرد. لا السمك بوصفه طعامًا حيث تفرّق اللغة (es pescado، ko 생선)، ولا الفعل \"يصطاد\"، ولا نوعًا بعينه.","he":"שם עצם \"דג\" = בעל החיים המימי החי, ביחיד. לא דג כמאכל בשפות שמפרידות (es pescado, ko 생선), לא הפועל \"לדוג\" ולא מין מסוים.","sw":"Nomino \"samaki\" = mnyama wa majini aliye hai, umoja. Si samaki kama chakula pale lugha inapotofautisha (es pescado, ko 생선), si kitenzi \"kuvua\", wala si spishi fulani."}},"bird":{"label":{"en":"Bird","ja":"鳥","ko":"새","zh":"鸟","yue":"鳥","vi":"Chim","th":"นก","id":"Burung","hi":"पक्षी","de":"Vogel","fr":"Oiseau","it":"Uccello","es":"Pájaro","es_eu":"Pájaro","es_mx":"Pájaro","pt":"Pássaro","pt_eu":"Pássaro","pt_br":"Pássaro","ru":"Птица","uk":"Птах","ar":"طائر","he":"ציפור","sw":"Ndege"},"definition":{"en":"Bird — a feathered, winged, egg-laying animal (the general category); not a specific species.","ja":"鳥 — 羽毛と翼をもち、卵を産む動物の総称。特定の種ではなく、カテゴリー全体を指す。","ko":"새 — 깃털과 날개가 있고 알을 낳는 동물의 총칭. 특정 종이 아니라 전체 부류를 가리킨다.","zh":"鸟 — 有羽毛和翅膀、会下蛋的动物的总称；指整个类别，而非某一特定物种。","yue":"鳥 — 有羽毛同翼、會生蛋嘅動物嘅統稱；指成個類別，唔係某一種雀。","vi":"Chim — loài động vật có lông vũ, có cánh và đẻ trứng (phạm trù chung); không phải một loài cụ thể.","th":"นก — สัตว์มีขน มีปีก และออกไข่ (หมวดหมู่ทั่วไป) ไม่ใช่ชนิดใดชนิดหนึ่งโดยเฉพาะ","id":"Burung — hewan berbulu, bersayap, dan bertelur (kategori umum); bukan spesies tertentu.","hi":"पक्षी — पंख और डैनों वाला, अंडे देने वाला प्राणी (सामान्य श्रेणी); कोई विशिष्ट प्रजाति नहीं।","de":"Vogel — ein gefiedertes, geflügeltes, eierlegendes Tier (die allgemeine Kategorie); keine bestimmte Art.","fr":"Oiseau — animal à plumes, ailé et pondeur d'œufs (la catégorie générale) ; pas une espèce en particulier.","it":"Uccello — animale con piume, alato e che depone uova (la categoria generale); non una specie particolare.","es":"Pájaro — animal con plumas, alas y que pone huevos (la categoría general); no una especie concreta.","es_eu":"Pájaro — animal con plumas, alas y que pone huevos (la categoría general); no una especie concreta.","es_mx":"Pájaro — animal con plumas, alas y que pone huevos (la categoría general); no una especie en concreto.","pt":"Pássaro — animal com penas, asas e que põe ovos (a categoria geral); não uma espécie específica.","pt_eu":"Pássaro — animal com penas, asas e que põe ovos (a categoria geral); não uma espécie específica.","pt_br":"Pássaro — animal com penas, asas e que põe ovos (a categoria geral); não uma espécie específica.","ru":"Птица — покрытое перьями крылатое животное, откладывающее яйца (общая категория); не конкретный вид.","uk":"Птах — вкрита пір'ям крилата тварина, що відкладає яйця (загальна категорія); не конкретний вид.","ar":"طائر — حيوان مكسوّ بالريش، له جناحان ويبيض (الفئة العامة)؛ وليس نوعًا بعينه.","he":"ציפור — בעל חיים מכוסה נוצות ובעל כנפיים שמטיל ביצים (הקטגוריה הכללית); לא מין מסוים.","sw":"Ndege — mnyama mwenye manyoya na mabawa anayetaga mayai (jamii ya jumla); si spishi maalum."}},"egg":{"label":{"en":"Egg","ja":"卵","ko":"달걀","zh":"鸡蛋","yue":"雞蛋","vi":"Trứng","th":"ไข่","id":"Telur","hi":"अंडा","de":"Ei","fr":"Œuf","it":"Uovo","es":"Huevo","es_eu":"Huevo","es_mx":"Huevo","pt":"Ovo","pt_eu":"Ovo","pt_br":"Ovo","ru":"Яйцо","uk":"Яйце","ar":"بيضة","he":"ביצה","sw":"Yai"},"definition":{"en":"Egg — the rounded object laid by a bird (esp. a hen's egg as food); not a verb, not a technical ovum.","ja":"卵（たまご）— 鳥（特にニワトリ）が産む丸い殻に包まれたもので、食品となるもの。動詞や生物学用語の「卵子」ではない。","ko":"달걀 — 새(특히 암탉)가 낳는 둥근 알로, 음식으로 먹는 것. 동사나 전문 용어 '난자'가 아님.","zh":"鸡蛋 — 鸟类（尤指母鸡）所产的圆形带壳之物，可作食物；不是动词，也不是专业术语中的卵子。","yue":"雞蛋 — 雀鳥（尤其係雞乸）生嘅圓形有殼嘅嘢，可以食；唔係動詞，亦唔係專業意義嘅卵子。","vi":"Trứng — vật hình bầu dục do chim (nhất là gà mái) đẻ ra, dùng làm thức ăn; không phải động từ, không phải noãn theo nghĩa chuyên môn.","th":"ไข่ — สิ่งทรงรีที่นก (โดยเฉพาะแม่ไก่) ออกมา ใช้เป็นอาหาร; ไม่ใช่คำกริยา และไม่ใช่เซลล์ไข่ในความหมายทางเทคนิค.","id":"Telur — benda bulat lonjong yang dikeluarkan burung (terutama ayam betina), dimakan sebagai makanan; bukan kata kerja, bukan sel telur dalam arti teknis.","hi":"अंडा — पक्षी (विशेषकर मुर्गी) द्वारा दिया गया गोल कवचयुक्त पिंड जो भोजन के रूप में खाया जाता है; क्रिया नहीं, न ही तकनीकी अर्थ में डिंब।","de":"Ei — das rundliche, von einem Vogel (bes. einer Henne) gelegte Objekt, das als Nahrung dient; kein Verb, keine Eizelle im Fachsinn.","fr":"Œuf — objet arrondi pondu par un oiseau (surtout une poule), consommé comme aliment ; pas un verbe, pas l'ovule au sens technique.","it":"Uovo — l'oggetto tondeggiante deposto da un uccello (spec. una gallina), usato come alimento; non un verbo, non l'ovulo in senso tecnico.","es":"Huevo — objeto redondeado puesto por un ave (esp. una gallina) que se come como alimento; no un verbo, no el óvulo en sentido técnico.","es_eu":"Huevo — objeto redondeado puesto por un ave (esp. una gallina) que se come como alimento; no un verbo, no el óvulo en sentido técnico.","es_mx":"Huevo — objeto redondeado puesto por un ave (esp. una gallina) que se come como alimento; no un verbo, no el óvulo en sentido técnico.","pt":"Ovo — objeto arredondado posto por uma ave (esp. uma galinha), consumido como alimento; não é um verbo nem o óvulo no sentido técnico.","pt_eu":"Ovo — objeto arredondado posto por uma ave (esp. uma galinha), consumido como alimento; não é um verbo nem o óvulo no sentido técnico.","pt_br":"Ovo — objeto arredondado posto por uma ave (esp. uma galinha), consumido como alimento; não é um verbo nem o óvulo no sentido técnico.","ru":"Яйцо — округлый предмет в скорлупе, снесённый птицей (особенно курицей) и употребляемый в пищу; не глагол и не яйцеклетка в специальном смысле.","uk":"Яйце — округлий предмет у шкаралупі, знесений птахом (особливо куркою), який їдять як їжу; не дієслово й не яйцеклітина у спеціальному значенні.","ar":"بيضة — الجسم المستدير الذي يضعه الطائر (خاصة الدجاجة) ويؤكل طعامًا؛ ليس فعلًا ولا البويضة بالمعنى التقني.","he":"ביצה — העצם המעוגל שמטיל עוף (בייחוד תרנגולת) ונאכל כמזון; לא פועל ולא ביצית במובן המדעי.","sw":"Yai — kitu cha mviringo kinachotagwa na ndege (hasa kuku), kinacholiwa kama chakula; si kitenzi wala yai la uzazi kwa maana ya kitaalamu."}},"eat":{"label":{"en":"Eat","ja":"食べる","ko":"먹다","zh":"吃","yue":"食","vi":"Ăn","th":"กิน","id":"Makan","hi":"खाना","de":"Essen","fr":"Manger","it":"Mangiare","es":"Comer","es_eu":"Comer","es_mx":"Comer","pt":"Comer","pt_eu":"Comer","pt_br":"Comer","ru":"Есть","uk":"Їсти","ar":"أكل","he":"לאכול","sw":"Kula"},"definition":{"en":"Verb \"to eat\" — use the language's normal dictionary/citation convention; document exceptions with wordEvidence.note.","ja":"動詞「食べる」。各言語の通常の辞書形・引用形を用いる。例外は wordEvidence.note で記録。","ko":"동사 \"먹다\". 각 언어의 통상적 사전형·인용형을 사용. 예외는 wordEvidence.note에 기록.","zh":"动词\"吃\"。使用各语言通常的词典/引用形式。例外通过 wordEvidence.note 记录。","yue":"動詞「食」。每種語言用佢慣常嘅詞典／引用形；例外用 wordEvidence.note 記錄。","vi":"Động từ \"ăn\" — dùng dạng từ điển thông dụng; ghi ngoại lệ vào wordEvidence.note.","th":"กริยา \"กิน\" ใช้รูปอ้างอิงปกติของภาษานั้น; ระบุข้อยกเว้นใน wordEvidence.note","id":"Verba \"makan\"; pakai bentuk kamus standar bahasa, catat pengecualian via wordEvidence.note.","hi":"क्रिया \"खाना\" — प्रत्येक भाषा का सामान्य शब्दकोश रूप; अपवाद wordEvidence.note में दर्ज।","de":"Verb \"essen\" — übliche Wörterbuchform der Sprache; Ausnahmen in wordEvidence.note.","fr":"Verbe \"manger\" — forme lexicale usuelle; exceptions notées via wordEvidence.note.","it":"Verbo \"mangiare\" — forma lessicale standard; eccezioni in wordEvidence.note.","es":"Verbo \"comer\" — forma de diccionario estándar; excepciones en wordEvidence.note.","es_eu":"Verbo \"comer\" — forma de diccionario estándar; excepciones en wordEvidence.note.","es_mx":"Verbo \"comer\" — forma de diccionario estándar; excepciones en wordEvidence.note.","pt":"Verbo \"comer\" — forma de dicionário; exceções em wordEvidence.note.","pt_eu":"Verbo \"comer\" — forma de dicionário; exceções em wordEvidence.note.","pt_br":"Verbo \"comer\" — forma de dicionário; exceções em wordEvidence.note.","ru":"Глагол \"есть\" — обычная словарная/цитатная форма; исключения — в wordEvidence.note.","uk":"Дієслово \"їсти\" — звична словникова/цитатна форма; винятки — у wordEvidence.note.","ar":"الفعل \"أكل\" — استخدم الصيغة المعجمية المعتادة؛ وثّق الاستثناءات في wordEvidence.note.","he":"הפועל \"לאכול\" — צורת הציטוט/המילון הרגילה; חריגות מתועדות ב־wordEvidence.note.","sw":"Kitenzi \"kula\" — tumia umbo la kawaida la kamusi; toa noti kupitia wordEvidence.note."}},"drink":{"label":{"en":"Drink","ja":"飲む","ko":"마시다","zh":"喝","yue":"飲","vi":"Uống","th":"ดื่ม","id":"Minum","hi":"पीना","de":"Trinken","fr":"Boire","it":"Bere","es":"Beber","es_eu":"Beber","es_mx":"Beber","pt":"Beber","pt_eu":"Beber","pt_br":"Beber","ru":"Пить","uk":"Пити","ar":"شرب","he":"לשתות","sw":"Kunywa"},"definition":{"en":"Verb \"to drink\" — same form policy as eat. May overlap with eat in Iranian/Old Thai (noted via wordEvidence).","ja":"動詞「飲む」。eat と同じ形態ポリシー。イラン語派・古タイ語では eat と語形が重なることあり (wordEvidence で記録)。","ko":"동사 \"마시다\". eat와 동일한 형태 정책. 이란어파·고타이어에서는 eat와 어형이 겹치기도 함 (wordEvidence에 기록).","zh":"动词\"喝\"。形式策略同\"吃\"。伊朗语支、古泰语中可能与\"吃\"同形（通过 wordEvidence 记录）。","yue":"動詞「飲」。同「食」一樣嘅形態政策；伊朗語族／古泰語可能同「食」同形（用 wordEvidence 記錄）。","vi":"Động từ \"uống\" — chính sách giống \"ăn\"; có thể trùng với \"ăn\" trong tiếng Iran/Thái cổ.","th":"กริยา \"ดื่ม\" นโยบายเดียวกับ \"กิน\"; อิหร่าน/ไทยโบราณอาจซ้ำกับ \"กิน\"","id":"Verba \"minum\"; kebijakan sama dengan \"makan\"; bisa tumpang-tindih di rumpun Iran/Thai kuno.","hi":"क्रिया \"पीना\" — नीति \"खाना\" जैसी; ईरानी/प्राचीन थाई में \"खाना\" से मिल सकती है।","de":"Verb \"trinken\" — wie bei \"essen\"; im Iranischen/Altthai mit \"essen\" formgleich.","fr":"Verbe \"boire\" — règle identique à \"manger\"; recouvrement possible en iranien/thaï ancien.","it":"Verbo \"bere\" — stessa regola di \"mangiare\"; sovrapposizione in iranico/thai antico.","es":"Verbo \"beber\" — misma regla que \"comer\"; puede solaparse con \"comer\" en iranio/thai antiguo.","es_eu":"Verbo \"beber\" — misma regla que \"comer\"; puede solaparse con \"comer\" en iranio/thai antiguo.","es_mx":"Verbo \"beber\" — misma regla que \"comer\"; puede solaparse con \"comer\" en iranio/thai antiguo.","pt":"Verbo \"beber\" — mesma regra de \"comer\"; pode coincidir com \"comer\" em iraniano/tailandês antigo.","pt_eu":"Verbo \"beber\" — mesma regra de \"comer\"; pode coincidir com \"comer\" em iraniano/tailandês antigo.","pt_br":"Verbo \"beber\" — mesma regra de \"comer\"; pode coincidir com \"comer\" em iraniano/tailandês antigo.","ru":"Глагол \"пить\" — та же политика, что и \"есть\"; в иранских / древнетайском возможно совпадение.","uk":"Дієслово \"пити\" — та ж політика, що й \"їсти\"; в іранських / давньотайській можливе збігання.","ar":"الفعل \"شرب\" — نفس قاعدة \"أكل\"؛ قد يتداخل مع \"أكل\" في الإيرانية/التايلندية القديمة.","he":"הפועל \"לשתות\" — אותה מדיניות כמו \"לאכול\"; חפיפה אפשרית באיראנית/תאית קדומה.","sw":"Kitenzi \"kunywa\" — sera ile ile kama \"kula\"; linaweza kuingiliana na \"kula\" katika lugha za Kiirani/Kithai cha kale."}},"sleep":{"label":{"en":"Sleep","ja":"寝る","ko":"자다","zh":"睡觉","yue":"瞓覺","vi":"Ngủ","th":"นอน","id":"Tidur","hi":"सोना","de":"Schlafen","fr":"Dormir","it":"Dormire","es":"Dormir","es_eu":"Dormir","es_mx":"Dormir","pt":"Dormir","pt_eu":"Dormir","pt_br":"Dormir","ru":"Спать","uk":"Спати","ar":"نام","he":"לישון","sw":"Kulala"},"definition":{"en":"Sleep — to be in the natural, recurring state of rest with reduced consciousness; the verb, not the noun.","ja":"寝る — 意識が低下し体を休める、自然で周期的な休息の状態にあること。名詞ではなく動詞。","ko":"자다 — 의식이 낮아지고 몸이 쉬는, 자연스럽고 주기적인 휴식 상태에 있다; 명사가 아닌 동사.","zh":"睡觉 — 处于意识降低、身体休息的自然、周期性状态；指动词，而非名词。","yue":"瞓覺 — 處於意識降低、身體休息嘅自然、週期性狀態；係動詞，唔係名詞。","vi":"Ngủ — ở trong trạng thái nghỉ ngơi tự nhiên, lặp lại với ý thức giảm; là động từ, không phải danh từ.","th":"นอน — อยู่ในภาวะพักผ่อนตามธรรมชาติที่เกิดซ้ำโดยรู้สึกตัวน้อยลง; เป็นคำกริยา ไม่ใช่คำนาม","id":"Tidur — berada dalam keadaan istirahat alami dan berulang dengan kesadaran berkurang; kata kerja, bukan kata benda.","hi":"सोना — कम चेतना के साथ विश्राम की स्वाभाविक, आवर्ती अवस्था में होना; क्रिया, संज्ञा नहीं।","de":"Schlafen — sich im natürlichen, wiederkehrenden Ruhezustand mit vermindertem Bewusstsein befinden; das Verb, nicht das Substantiv.","fr":"Dormir — être dans l'état de repos naturel et récurrent où la conscience est réduite ; le verbe, pas le nom.","it":"Dormire — trovarsi nello stato di riposo naturale e ricorrente con coscienza ridotta; il verbo, non il sostantivo.","es":"Dormir — estar en el estado natural y recurrente de reposo con la consciencia reducida; el verbo, no el sustantivo.","es_eu":"Dormir — estar en el estado natural y recurrente de reposo con la consciencia reducida; el verbo, no el sustantivo.","es_mx":"Dormir — estar en el estado natural y recurrente de reposo con la conciencia reducida; el verbo, no el sustantivo.","pt":"Dormir — estar no estado natural e recorrente de repouso com a consciência reduzida; o verbo, não o substantivo.","pt_eu":"Dormir — estar no estado natural e recorrente de repouso com a consciência reduzida; o verbo, não o substantivo.","pt_br":"Dormir — estar no estado natural e recorrente de repouso com a consciência reduzida; o verbo, não o substantivo.","ru":"Спать — находиться в естественном периодическом состоянии покоя с пониженным сознанием; глагол, а не существительное.","uk":"Спати — перебувати в природному періодичному стані спокою зі зниженою свідомістю; дієслово, а не іменник.","ar":"نام — أن يكون في حالة الراحة الطبيعية المتكررة مع انخفاض الوعي؛ الفعل لا الاسم.","he":"לישון — להיות במצב המנוחה הטבעי והמחזורי שבו ההכרה מופחתת; הפועל, לא שם העצם.","sw":"Kulala — kuwa katika hali ya asili ya kupumzika inayojirudia huku fahamu zikipungua; kitenzi, si nomino."}},"one":{"label":{"en":"One","ja":"一","ko":"하나","zh":"一","yue":"一","vi":"Một","th":"หนึ่ง","id":"Satu","hi":"एक","de":"Eins","fr":"Un","it":"Uno","es":"Uno","es_eu":"Uno","es_mx":"Uno","pt":"Um","pt_eu":"Um","pt_br":"Um","ru":"Один","uk":"Один","ar":"واحد","he":"אחד","sw":"Moja"},"definition":{"en":"Cardinal numeral 1; masculine/default citation form where languages distinguish gender (e.g. ar واحد, he אחד, fr un, es uno).","ja":"基数 1。性別区別がある言語では男性形・既定形 (例: ar واحد, he אחד, fr un, es uno)。","ko":"기수 1. 성을 구분하는 언어에서는 남성형/기본형 (예: ar واحد, he אחד, fr un, es uno).","zh":"基数 1。区分性别的语言中使用阳性/默认形式 (如 ar واحد, he אחד, fr un, es uno)。","yue":"基數 1。分性別嘅語言用陽性／預設形（例如 ar واحد、he אחד、fr un、es uno）。","vi":"Số đếm 1. Với ngôn ngữ phân biệt giống, dùng dạng giống đực/mặc định (ar واحد, he אחד, fr un, es uno).","th":"เลขนับ 1; ภาษาที่จำแนกเพศใช้รูปบุรุษ/รูปอ้างอิงพื้นฐาน (เช่น ar واحد, he אחד, fr un, es uno)","id":"Bilangan kardinal 1. Bahasa bergender pakai bentuk maskulin/standar (ar واحد, he אחד, fr un, es uno).","hi":"गणना अंक 1; लिंग-भेदी भाषाओं में पुल्लिंग/मूल रूप (जैसे ar واحد, he אחד, fr un, es uno)।","de":"Kardinalzahl 1; in genusmarkierten Sprachen die Maskulin-/Standardform (z. B. ar واحد, he אחד, fr un, es uno).","fr":"Numéral cardinal 1; forme masculine/par défaut dans les langues à genre (ar واحد, he אחד, fr un, es uno).","it":"Cardinale 1; forma maschile/predefinita nelle lingue con genere (ar واحد, he אחד, fr un, es uno).","es":"Numeral cardinal 1; forma masculina/predeterminada en lenguas con género (ar واحد, he אחד, fr un, es uno).","es_eu":"Numeral cardinal 1; forma masculina/predeterminada en lenguas con género (ar واحد, he אחד, fr un, es uno).","es_mx":"Numeral cardinal 1; forma masculina/predeterminada en lenguas con género (ar واحد, he אחד, fr un, es uno).","pt":"Numeral cardinal 1; forma masculina/padrão em línguas com género (ar واحد, he אחד, fr un, es uno).","pt_eu":"Numeral cardinal 1; forma masculina/padrão em línguas com género (ar واحد, he אחד, fr un, es uno).","pt_br":"Numeral cardinal 1; forma masculina/padrão em línguas com gênero (ar واحد, he אחד, fr un, es uno).","ru":"Кардинальное число 1; в языках с родом — мужская/основная форма (ar واحد, he אחד, fr un, es uno).","uk":"Кардинальне число 1; у мовах із родом — чоловіча/основна форма (ar واحد, he אחד, fr un, es uno).","ar":"العدد الأصلي 1؛ في اللغات المُذكَّرة/المؤنَّثة الصيغة المذكَّرة/الافتراضية (ar واحد، he אחד، fr un، es uno).","he":"מספר מונה 1; בשפות בעלות מין דקדוקי — צורת הזכר/ברירת המחדל (ar واحد, he אחד, fr un, es uno).","sw":"Idadi 1 (kardinali); katika lugha zinazotofautisha jinsia, umbo la kiume/la msingi (ar واحد, he אחד, fr un, es uno)."}},"two":{"label":{"en":"Two","ja":"二","ko":"둘","zh":"二","yue":"二","vi":"Hai","th":"สอง","id":"Dua","hi":"दो","de":"Zwei","fr":"Deux","it":"Due","es":"Dos","es_eu":"Dos","es_mx":"Dos","pt":"Dois","pt_eu":"Dois","pt_br":"Dois","ru":"Два","uk":"Два","ar":"اثنان","he":"שתיים","sw":"Mbili"},"definition":{"en":"The cardinal NUMERAL 2 (\"two\"); counting number. Not the ordinal \"second\".","ja":"基数の数詞「2（に／ふたつ）」；数を数える語。序数の「2番目」ではない。","ko":"기수 \"둘/2\"; 개수를 세는 수. 서수 \"둘째\"가 아님.","zh":"基数词\"二/2\"，用于计数；不是序数\"第二\"。","yue":"基數詞「二／2」，用嚟數數；唔係序數「第二」。","vi":"Số đếm 2 (\"hai\"); số dùng để đếm. Không phải số thứ tự \"thứ hai\".","th":"เลขจำนวนนับ 2 (\"สอง\"); ใช้นับจำนวน. ไม่ใช่ลำดับที่ \"ที่สอง\".","id":"Bilangan pokok 2 (\"dua\"); angka untuk menghitung. Bukan bilangan tingkat \"kedua\".","hi":"मूल संख्या 2 (\"दो\"); गिनती की संख्या। क्रमसूचक \"दूसरा\" नहीं।","de":"Kardinalzahl 2 (\"zwei\"); Zählzahl. Nicht die Ordnungszahl \"zweite\".","fr":"Numéral cardinal 2 (\"deux\") ; nombre pour compter. Pas l'ordinal \"deuxième\".","it":"Numerale cardinale 2 (\"due\"); numero per contare. Non l'ordinale \"secondo\".","es":"Numeral cardinal 2 (\"dos\"); número para contar. No el ordinal \"segundo\".","es_eu":"Numeral cardinal 2 (\"dos\"); número para contar. No el ordinal \"segundo\".","es_mx":"Numeral cardinal 2 (\"dos\"); número para contar. No el ordinal \"segundo\".","pt":"Numeral cardinal 2 (\"dois\"); número para contar. Não o ordinal \"segundo\".","pt_eu":"Numeral cardinal 2 (\"dois\"); número para contar. Não o ordinal \"segundo\".","pt_br":"Numeral cardinal 2 (\"dois\"); número para contar. Não o ordinal \"segundo\".","ru":"Количественное числительное 2 (\"два\"); счётное число. Не порядковое \"второй\".","uk":"Кількісний числівник 2 (\"два\"); лічильне число. Не порядковий \"другий\".","ar":"العدد الأصلي 2 (\"اثنان\")؛ عدد للعدّ. ليس العدد الترتيبي \"الثاني\".","he":"מספר מונה 2 (\"שתיים\"); מספר לספירה. לא המספר הסודר \"שני\".","sw":"Nambari kamili 2 (\"mbili\"); nambari ya kuhesabu. Si nambari ya mpangilio \"pili\"."}},"three":{"label":{"en":"Three","ja":"三","ko":"셋","zh":"三","yue":"三","vi":"Ba","th":"สาม","id":"Tiga","hi":"तीन","de":"Drei","fr":"Trois","it":"Tre","es":"Tres","es_eu":"Tres","es_mx":"Tres","pt":"Três","pt_eu":"Três","pt_br":"Três","ru":"Три","uk":"Три","ar":"ثلاثة","he":"שלוש","sw":"Tatu"},"definition":{"en":"The cardinal numeral \"three\" (3), citation form. Where a language keeps two numeral series, the one used for plain counting is taken — the same series as this atlas's \"one\" and \"two\" rows (Japanese 一・二・三 san, Korean 하나・둘・셋 set). Not the ordinal \"third\" and not a counting classifier.","ja":"基数詞「三」（3）の辞書形。数詞の系統が二つある言語では、素で数え上げるときの系統を採る——本アトラスの「一」「二」の行と同じ系統（日本語 一・二・三、韓国語 하나・둘・셋）。序数「三番目」や助数詞ではない。","ko":"기수사 \"셋\"(3)의 사전형. 수사 계열이 둘인 언어에서는 그냥 세어 나갈 때 쓰는 계열을 취한다 — 이 지도의 \"하나\"·\"둘\" 행과 같은 계열(일본어 一・二・三, 한국어 하나・둘・셋). 서수 \"셋째\"나 분류사가 아니다.","zh":"基数词\"三\"（3）的词典形式。若某语言有两套数词，取平常数数时所用的那套——与本图\"一\"\"二\"两行相同的一套（日语 一・二・三，韩语 하나・둘・셋）。不是序数\"第三\"，也不是量词。","yue":"基數詞「三」（3）嘅詞典形。如果某語言有兩套數詞，取平時數數嗰套——同本圖「一」「二」兩行相同（日語 一・二・三，韓語 하나・둘・셋）。唔係序數「第三」，亦唔係量詞。","vi":"Số đếm \"ba\" (3), dạng từ điển. Với ngôn ngữ có hai dãy số, lấy dãy dùng để đếm thường — cùng dãy với hàng \"một\" và \"hai\" của bản đồ này (tiếng Nhật 一・二・三, tiếng Hàn 하나・둘・셋). Không phải số thứ tự \"thứ ba\", cũng không phải loại từ.","th":"เลขจำนวนนับ \"สาม\" (3) รูปอ้างอิง หากภาษาใดมีชุดคำเลขสองชุด ให้ใช้ชุดที่ใช้นับตามปกติ — ชุดเดียวกับแถว \"หนึ่ง\" และ \"สอง\" ของแผนที่นี้ (ญี่ปุ่น 一・二・三, เกาหลี 하나・둘・셋) ไม่ใช่เลขลำดับ \"ที่สาม\" และไม่ใช่ลักษณนาม","id":"Numeralia pokok \"tiga\" (3), bentuk kamus. Jika sebuah bahasa punya dua deret bilangan, dipakai deret untuk menghitung biasa — deret yang sama dengan baris \"satu\" dan \"dua\" pada peta ini (Jepang 一・二・三, Korea 하나・둘・셋). Bukan bilangan tingkat \"ketiga\", bukan pula kata penggolong.","hi":"मूल संख्यावाचक \"तीन\" (3), शब्दकोश रूप। जिन भाषाओं में दो शृंखलाएँ हैं, वहाँ साधारण गिनती की शृंखला ली गई है — वही जो इस मानचित्र की \"एक\" और \"दो\" पंक्तियों में है (जापानी 一・二・三, कोरियाई 하나・둘・셋)। क्रमवाचक \"तीसरा\" या गणक शब्द नहीं।","de":"Grundzahlwort \"drei\" (3), Zitierform. Hat eine Sprache zwei Zahlreihen, wird die des einfachen Zählens genommen — dieselbe wie in den Zeilen \"eins\" und \"zwei\" dieses Atlas (Japanisch 一・二・三, Koreanisch 하나・둘・셋). Nicht die Ordnungszahl \"dritte\" und kein Zählklassifikator.","fr":"Numéral cardinal \"trois\" (3), forme de citation. Si une langue a deux séries de numéraux, on retient celle du comptage ordinaire — la même que les lignes \"un\" et \"deux\" de cet atlas (japonais 一・二・三, coréen 하나・둘・셋). Pas l'ordinal \"troisième\" ni un classificateur.","it":"Numerale cardinale \"tre\" (3), forma di citazione. Se una lingua ha due serie di numerali, si usa quella del conteggio ordinario — la stessa delle righe \"uno\" e \"due\" di questo atlante (giapponese 一・二・三, coreano 하나・둘・셋). Non l'ordinale \"terzo\" né un classificatore.","es":"Numeral cardinal \"tres\" (3), forma de cita. Si una lengua tiene dos series de numerales, se toma la del conteo corriente — la misma que las filas \"uno\" y \"dos\" de este atlas (japonés 一・二・三, coreano 하나・둘・셋). No el ordinal \"tercero\" ni un clasificador.","es_eu":"Numeral cardinal \"tres\" (3), forma de cita. Si una lengua tiene dos series de numerales, se toma la del conteo corriente — la misma que las filas \"uno\" y \"dos\" de este atlas (japonés 一・二・三, coreano 하나・둘・셋). No el ordinal \"tercero\" ni un clasificador.","es_mx":"Numeral cardinal \"tres\" (3), forma de cita. Si una lengua tiene dos series de numerales, se toma la del conteo corriente — la misma que las filas \"uno\" y \"dos\" de este atlas (japonés 一・二・三, coreano 하나・둘・셋). No el ordinal \"tercero\" ni un clasificador.","pt":"Numeral cardinal \"três\" (3), forma de citação. Se uma língua tem duas séries de numerais, usa-se a da contagem comum — a mesma das linhas \"um\" e \"dois\" deste atlas (japonês 一・二・三, coreano 하나・둘・셋). Não o ordinal \"terceiro\" nem um classificador.","pt_eu":"Numeral cardinal \"três\" (3), forma de citação. Se uma língua tem duas séries de numerais, usa-se a da contagem comum — a mesma das linhas \"um\" e \"dois\" deste atlas (japonês 一・二・三, coreano 하나・둘・셋). Não o ordinal \"terceiro\" nem um classificador.","pt_br":"Numeral cardinal \"três\" (3), forma de citação. Se uma língua tem duas séries de numerais, usa-se a da contagem comum — a mesma das linhas \"um\" e \"dois\" deste atlas (japonês 一・二・三, coreano 하나・둘・셋). Não o ordinal \"terceiro\" nem um classificador.","ru":"Количественное числительное \"три\" (3), словарная форма. Если в языке два ряда числительных, берётся тот, которым обычно считают, — тот же, что в строках \"один\" и \"два\" этого атласа (японский 一・二・三, корейский 하나・둘・셋). Не порядковое \"третий\" и не счётное слово.","uk":"Кількісний числівник \"три\" (3), словникова форма. Якщо в мові два ряди числівників, береться той, яким зазвичай лічать, — той самий, що в рядках \"один\" і \"два\" цього атласу (японська 一・二・三, корейська 하나・둘・셋). Не порядкове \"третій\" і не лічильне слово.","ar":"العدد الأصلي \"ثلاثة\" (3) بصيغته المعجمية. إذا كان في اللغة سلسلتان للأعداد، تُؤخذ سلسلة العدّ المعتاد — نفس السلسلة الواردة في صفّي \"واحد\" و\"اثنان\" في هذا الأطلس (اليابانية 一・二・三، الكورية 하나・둘・셋). لا العدد الترتيبي \"الثالث\" ولا أداة تمييز العدد.","he":"מספר מונה \"שלוש\" (3), צורת מילון. בשפה שיש בה שתי סדרות מספרים נלקחת זו של הספירה הרגילה — אותה סדרה שבשורות \"אחת\" ו\"שתיים\" באטלס הזה (יפנית 一・二・三, קוריאנית 하나・둘・셋). לא המספר הסודר \"שלישי\" ולא מילת מניין.","sw":"Nambari kamili \"tatu\" (3), umbo la kamusi. Lugha ikiwa na mifululizo miwili ya nambari, hutumika ule wa kuhesabu kwa kawaida — ule ule wa safu za \"moja\" na \"mbili\" katika ramani hii (Kijapani 一・二・三, Kikorea 하나・둘・셋). Si nambari ya mpangilio \"tatu\" wala kiainishi."}},"five":{"label":{"en":"Five","ja":"五","ko":"다섯","zh":"五","yue":"五","vi":"Năm","th":"ห้า","id":"Lima","hi":"पाँच","de":"Fünf","fr":"Cinq","it":"Cinque","es":"Cinco","es_eu":"Cinco","es_mx":"Cinco","pt":"Cinco","pt_eu":"Cinco","pt_br":"Cinco","ru":"Пять","uk":"П'ять","ar":"خمسة","he":"חמש","sw":"Tano"},"definition":{"en":"Five — the cardinal number 5, one more than four.","ja":"五（ご）——基数の5。4より一つ大きい数。数え上げの系統は「一・二・三」の行と同じ。","ko":"다섯 — 기수 5. 넷보다 하나 큰 수. (이 지도의 하나·둘·셋과 같은 고유어 계열.)","zh":"五 — 基数5，比四多一。","yue":"五 — 基數5，比四多一。","vi":"Năm — số đếm 5, lớn hơn bốn một đơn vị.","th":"ห้า — จำนวนนับ 5 มากกว่าสี่อยู่หนึ่ง","id":"Lima — bilangan pokok 5, satu lebih banyak daripada empat.","hi":"पाँच — गणन संख्या 5, चार से एक अधिक।","de":"Fünf — die Kardinalzahl 5, eins mehr als vier.","fr":"Cinq — le nombre cardinal 5, un de plus que quatre.","it":"Cinque — il numero cardinale 5, uno in più di quattro.","es":"Cinco — el número cardinal 5, uno más que cuatro.","es_eu":"Cinco — el número cardinal 5, uno más que cuatro.","es_mx":"Cinco — el número cardinal 5, uno más que cuatro.","pt":"Cinco — o número cardinal 5, um a mais que quatro.","pt_eu":"Cinco — o número cardinal 5, um a mais que quatro.","pt_br":"Cinco — o número cardinal 5, um a mais que quatro.","ru":"Пять — количественное числительное 5, на один больше четырёх.","uk":"П'ять — кількісний числівник 5, на один більший за чотири.","ar":"خمسة — العدد الأصلي 5، أكبر من أربعة بواحد.","he":"חמש — המספר המונה 5, אחד יותר מארבע.","sw":"Tano — nambari kamili 5, moja zaidi ya nne."}},"hello":{"label":{"en":"Hello","ja":"こんにちは","ko":"안녕하세요","zh":"你好","yue":"你好","vi":"Xin chào","th":"สวัสดี","id":"Halo","hi":"नमस्ते","de":"Hallo","fr":"Bonjour","it":"Ciao","es":"Hola","es_eu":"Hola","es_mx":"Hola","pt":"Olá","pt_eu":"Olá","pt_br":"Olá","ru":"Привет","uk":"Привіт","ar":"مرحبا","he":"שלום","sw":"Habari"},"definition":{"en":"Neutral everyday greeting. Time-of-day forms (morning/evening) only if the language has no neutral form. Blessings (e.g. \"peace\") accepted only as the normal greeting.","ja":"中立的な日常挨拶。時刻別の挨拶 (おはよう・こんばんは) は中立形がない場合のみ。「平安」などの祝福語も、それが通常の挨拶である場合のみ。","ko":"중립적 일상 인사. 시간대별 인사 (아침/저녁)는 중립형이 없을 때만 사용. \"평안\" 등 축복어는 그것이 통상적 인사일 경우에만.","zh":"中性日常问候语。仅当语言无中性形式时才使用时段问候 (早安/晚安)。\"平安\"等祝福语仅在它本身就是日常问候时使用。","yue":"中性日常問候語。時間性問候（早晨／晚上）淨喺冇中性形時用。「平安」呢類祝福只喺佢本身就係日常問候時用。","vi":"Lời chào trung tính hàng ngày. Chào theo thời điểm chỉ khi không có dạng trung tính. \"Bình an\" chỉ khi đó là lời chào thường ngày.","th":"คำทักทายกลางๆ ประจำวัน; ใช้คำตามช่วงเวลาเฉพาะเมื่อไม่มีคำกลาง; ใช้คำอวยพร (\"สันติ\") เฉพาะเมื่อเป็นคำทักทายปกติ","id":"Sapaan sehari-hari yang netral. Sapaan waktu (pagi/malam) hanya jika tak ada bentuk netral; \"salam\" hanya jika itu sapaan biasa.","hi":"तटस्थ रोज़मर्रा अभिवादन। समय-आधारित अभिवादन तभी जब तटस्थ रूप नहीं है। \"शांति\" जैसे आशीर्वाद तभी जब वह सामान्य अभिवादन हो।","de":"Neutraler Alltagsgruß. Tageszeit-Grüße (Guten Morgen/Abend) nur wenn es keinen neutralen Gruß gibt; Segenswünsche (\"Friede\") nur, wenn es der übliche Gruß ist.","fr":"Salutation neutre du quotidien. Forme selon l'heure (matin/soir) uniquement faute de neutre; les bénédictions (\"paix\") seulement si c'est la salutation usuelle.","it":"Saluto neutro quotidiano. Forme orarie (buongiorno/buonasera) solo se manca un neutro; benedizioni (\"pace\") solo se sono il saluto abituale.","es":"Saludo neutro del día a día. Las formas por hora (buenos días/noches) solo si no hay neutro; bendiciones (\"paz\") solo si son el saludo habitual.","es_eu":"Saludo neutro del día a día. Las formas por hora (buenos días/noches) solo si no hay neutro; bendiciones (\"paz\") solo si son el saludo habitual.","es_mx":"Saludo neutro del día a día. Las formas por hora (buenos días/noches) solo si no hay neutro; bendiciones (\"paz\") solo si son el saludo habitual.","pt":"Saudação neutra do dia a dia. Formas por hora (bom dia/boa noite) apenas se não houver neutra; bênçãos (\"paz\") apenas se forem a saudação habitual.","pt_eu":"Saudação neutra do dia a dia. Formas por hora (bom dia/boa noite) apenas se não houver neutra; bênçãos (\"paz\") apenas se forem a saudação habitual.","pt_br":"Saudação neutra do dia a dia. Formas por hora (bom dia/boa noite) apenas se não houver neutra; bênçãos (\"paz\") apenas se forem a saudação habitual.","ru":"Нейтральное повседневное приветствие. Формы \"доброе утро/вечер\" — только при отсутствии нейтральной; благословения (\"мир\") — лишь если это обычное приветствие.","uk":"Нейтральне повсякденне привітання. Форми за часом доби — лише за відсутності нейтральної; благословення (\"мир\") — лише якщо це звичне привітання.","ar":"تحية يومية محايدة. صيغ الأوقات (صباح/مساء الخير) فقط عند غياب صيغة محايدة؛ صيغ البركة (\"سلام\") فقط إذا كانت التحية المعتادة.","he":"ברכת שלום יומיומית ניטרלית. ברכות לפי שעות (בוקר/ערב) רק בהיעדר צורה ניטרלית; איחולי ברכה (\"שלום\") רק אם זוהי הברכה השגרתית.","sw":"Salamu ya kawaida isiyo na ushawishi wa wakati. Salamu za saa (asubuhi/jioni) ikiwa hakuna umbo la jumla; baraka kama \"amani\" zinapokubaliwa kama salamu ya kawaida."}},"thanks":{"label":{"en":"Thank you","ja":"ありがとう","ko":"감사합니다","zh":"谢谢","yue":"多謝","vi":"Cảm ơn","th":"ขอบคุณ","id":"Terima kasih","hi":"धन्यवाद","de":"Danke","fr":"Merci","it":"Grazie","es":"Gracias","es_eu":"Gracias","es_mx":"Gracias","pt":"Obrigado","pt_eu":"Obrigado","pt_br":"Obrigado","ru":"Спасибо","uk":"Дякую","ar":"شكرا","he":"תודה","sw":"Asante"},"definition":{"en":"Spoken thank-you formula for modern languages. For historical languages, use — or a clearly noted liturgical/gratitude noun rather than inventing a formula.","ja":"現代語では話し言葉の感謝表現。歴史言語では「—」または明記された宗教/感謝名詞を用い、表現を捏造しない。","ko":"현대어에서는 구어 감사 표현. 역사 언어에서는 \"—\" 또는 명기된 종교/감사 명사를 사용하고 임의로 만들어내지 않음.","zh":"现代语言使用口语感谢表达。历史语言用 \"—\" 或明确标注的礼仪/感谢名词，而非杜撰表达。","yue":"現代語：口語感謝表達。歷史語言用「—」或者明確標記嘅祈福／感謝名詞，唔好捏造。","vi":"Lời cảm ơn nói thường ngày trong ngôn ngữ hiện đại. Ngôn ngữ lịch sử dùng \"—\" hoặc danh từ tạ ơn có chú giải, không bịa.","th":"คำขอบคุณเชิงพูดในภาษาสมัยใหม่ ภาษาประวัติศาสตร์ใช้ \"—\" หรือคำนามขอบคุณ/ศาสนา; ห้ามสร้างขึ้นเอง","id":"Ungkapan terima kasih sehari-hari untuk bahasa modern. Bahasa historis pakai \"—\" atau kata benda doa/syukur yang dicatat; jangan mengarang.","hi":"आधुनिक भाषाओं के लिए मौखिक धन्यवाद। ऐतिहासिक भाषाओं में \"—\" या स्पष्ट रूप से नोट किया गया धार्मिक/कृतज्ञता संज्ञा; कुछ गढ़ें नहीं।","de":"Mündliche Dankesformel für moderne Sprachen. Bei historischen Sprachen \"—\" oder ein klar belegtes liturgisches/Dank-Substantiv — nichts erfinden.","fr":"Formule orale de remerciement pour les langues modernes. Pour les langues historiques, utiliser \"—\" ou un nom de gratitude/liturgique attesté — ne pas inventer.","it":"Formula orale di ringraziamento nelle lingue moderne. Per quelle storiche, usare \"—\" o un sostantivo di gratitudine/liturgico documentato — niente invenzioni.","es":"Fórmula oral de agradecimiento en lenguas modernas. En lenguas históricas, usar \"—\" o un sustantivo de gratitud/litúrgico atestiguado; no inventar.","es_eu":"Fórmula oral de agradecimiento en lenguas modernas. En lenguas históricas, usar \"—\" o un sustantivo de gratitud/litúrgico atestiguado; no inventar.","es_mx":"Fórmula oral de agradecimiento en lenguas modernas. En lenguas históricas, usar \"—\" o un sustantivo de gratitud/litúrgico atestiguado; no inventar.","pt":"Fórmula oral de agradecimento em línguas modernas. Em línguas históricas, usar \"—\" ou um substantivo de gratidão/litúrgico atestado; não inventar.","pt_eu":"Fórmula oral de agradecimento em línguas modernas. Em línguas históricas, usar \"—\" ou um substantivo de gratidão/litúrgico atestado; não inventar.","pt_br":"Fórmula oral de agradecimento em línguas modernas. Em línguas históricas, usar \"—\" ou um substantivo de gratidão/litúrgico atestado; não inventar.","ru":"Устная формула благодарности для современных языков. В исторических — \"—\" или явно отмеченное литургическое/благодарственное существительное; не выдумывать.","uk":"Усна формула подяки для сучасних мов. У історичних — \"—\" або явно позначений літургійний/вдячний іменник; не вигадувати.","ar":"صيغة شكر شفوية في اللغات الحديثة. في اللغات التاريخية، استخدم \"—\" أو اسمًا ليتورجيًّا/شكرًا موثّقًا؛ لا تختلق.","he":"נוסח תודה דיבורי בשפות מודרניות. בשפות היסטוריות — \"—\" או שם עצם תודתי/ליטורגי מתועד; אין להמציא.","sw":"Msemo wa shukrani unaonenwa katika lugha za kisasa. Kwa lugha za kihistoria tumia \"—\" au nomino ya shukrani/kiimani iliyotajwa; usitunge."}},"good":{"label":{"en":"Good","ja":"良い","ko":"좋은","zh":"好","yue":"好","vi":"Tốt","th":"ดี","id":"Baik","hi":"अच्छा","de":"Gut","fr":"Bon","it":"Buono","es":"Bueno","es_eu":"Bueno","es_mx":"Bueno","pt":"Bom","pt_eu":"Bom","pt_br":"Bom","ru":"Хороший","uk":"Добрий","ar":"جيد","he":"טוב","sw":"Nzuri"},"definition":{"en":"Basic adjective \"good\" (positive quality); attributive citation form preferred. Avoid adverb \"well\" (e.g. ru хорошо / uk добре) and greeting responses.","ja":"基本形容詞「良い」（肯定的属性）。連体辞書形を優先。副詞「よく」(例: ru хорошо / uk добре) や挨拶返答は避ける。","ko":"기본 형용사 \"좋다\"(긍정적 속성). 관형 사전형을 우선. 부사 \"잘\"(예: ru хорошо / uk добре)과 인사 응답 형은 피한다.","zh":"基本形容词\"好\"（正面属性）；优先使用定语词典形式。避免副词\"好（地）\"(如 ru хорошо / uk добре) 和问候应答形式。","yue":"基本形容詞「好」（正面屬性）；優先用定語詞典形。避免副詞「好咁」（如 ru хорошо / uk добре）同問候回應形。","vi":"Tính từ cơ bản \"tốt\" (phẩm chất tích cực); ưu tiên dạng định ngữ; tránh trạng từ \"tốt\" (ru хорошо / uk добре) và lời đáp chào.","th":"คำคุณศัพท์พื้นฐาน \"ดี\" (คุณภาพเชิงบวก); ใช้รูปขยาย/รูปอ้างอิง; เลี่ยงคำกริยาวิเศษณ์ (ru хорошо / uk добре) และคำตอบทักทาย","id":"Adjektiva dasar \"baik\" (sifat positif); pakai bentuk atributif standar; hindari adverbia (ru хорошо / uk добре) dan jawaban sapaan.","hi":"मूल विशेषण \"अच्छा\" (सकारात्मक गुण); विशेषण शब्दकोश रूप वरीयता; क्रिया-विशेषण (जैसे ru хорошо / uk добре) और अभिवादन उत्तर रूपों से बचें।","de":"Grundadjektiv \"gut\" (positive Eigenschaft); attributive Wörterbuchform bevorzugt. Adverbien (ru хорошо / uk добре) und Begrüßungs-Antworten vermeiden.","fr":"Adjectif de base \"bon\" (qualité positive); forme attributive privilégiée. Éviter l'adverbe (ru хорошо / uk добре) et les réponses de salutation.","it":"Aggettivo base \"buono\" (qualità positiva); preferenza per la forma attributiva. Evitare l'avverbio (ru хорошо / uk добре) e le risposte di saluto.","es":"Adjetivo básico \"bueno\" (cualidad positiva); preferencia por la forma atributiva. Evitar el adverbio (ru хорошо / uk добре) y respuestas de saludo.","es_eu":"Adjetivo básico \"bueno\" (cualidad positiva); preferencia por la forma atributiva. Evitar el adverbio (ru хорошо / uk добре) y respuestas de saludo.","es_mx":"Adjetivo básico \"bueno\" (cualidad positiva); preferencia por la forma atributiva. Evitar el adverbio (ru хорошо / uk добре) y respuestas de saludo.","pt":"Adjetivo básico \"bom\" (qualidade positiva); preferir a forma atributiva. Evitar o advérbio (ru хорошо / uk добре) e respostas de saudação.","pt_eu":"Adjetivo básico \"bom\" (qualidade positiva); preferir a forma atributiva. Evitar o advérbio (ru хорошо / uk добре) e respostas de saudação.","pt_br":"Adjetivo básico \"bom\" (qualidade positiva); preferir a forma atributiva. Evitar o advérbio (ru хорошо / uk добре) e respostas de saudação.","ru":"Базовое прилагательное \"хороший\" (положительное качество); предпочтительна определительная/словарная форма. Избегать наречия \"хорошо\" и ответных формул.","uk":"Базовий прикметник \"добрий\" (позитивна якість); надавайте перевагу означальній/словниковій формі. Уникайте прислівника \"добре\" та формул-відповідей на привітання.","ar":"صفة أساسية \"جيد\" (صفة إيجابية)؛ تُفضَّل صيغة الصفة المعجمية. تجنّب الظرف (مثل хорошо/добре) وردود التحية.","he":"שם תואר בסיסי \"טוב\" (איכות חיובית); מועדפת צורת המילון. להימנע מצורת תואר הפועל (\"היטב\") ומתשובות לברכה.","sw":"Kivumishi cha msingi \"nzuri\" (ubora chanya); umbo la sifa/la kamusi hupendelewa. Epuka kielezi (kama хорошо / добре) na majibu ya salamu."}},"red":{"label":{"en":"Red","ja":"赤い","ko":"빨강","zh":"红","yue":"紅","vi":"Đỏ","th":"แดง","id":"Merah","hi":"लाल","de":"Rot","fr":"Rouge","it":"Rosso","es":"Rojo","es_eu":"Rojo","es_mx":"Rojo","pt":"Vermelho","pt_eu":"Vermelho","pt_br":"Vermelho","ru":"Красный","uk":"Червоний","ar":"أحمر","he":"אדום","sw":"Nyekundu"},"definition":{"en":"Basic colour adjective \"red\"; attributive/citation form preferred. The colour itself — not \"red\" in the political sense (communist/left-wing), not red hair, and not \"ripe\". Where a language has no basic red term, the everyday descriptive word is used.","ja":"基本色彩形容詞「赤い」。連体・辞書形を優先。色そのものを指し、政治的な「赤」（共産主義・左派）や赤毛、「熟した」の意味ではない。基本色彩語として赤を持たない言語では、日常的な記述表現を採る。","ko":"기본 색채 형용사 \"빨갛다\". 관형·사전형을 우선. 색 자체를 뜻하며 정치적 \"빨강\"(공산주의·좌파), 붉은 머리카락, \"익은\"의 뜻이 아니다. 기본 색채어로 빨강이 없는 언어에서는 일상적 서술 표현을 쓴다.","zh":"基本颜色形容词\"红\"；优先使用定语/词典形式。指颜色本身，不是政治意义上的\"红\"（共产主义／左翼），也不是红头发或\"成熟\"。若某语言没有基本红色词，则采用日常的描述性说法。","yue":"基本顏色形容詞「紅」；優先用定語／詞典形。指顏色本身，唔係政治意義嘅「紅」（共產主義／左派），亦唔係紅頭髮或者「熟咗」。如果某語言冇基本紅色詞，就用日常描述講法。","vi":"Tính từ màu cơ bản \"đỏ\"; ưu tiên dạng định ngữ/từ điển. Chỉ bản thân màu sắc — không phải \"đỏ\" theo nghĩa chính trị (cộng sản/cánh tả), không phải tóc đỏ, cũng không phải \"chín\". Nếu một ngôn ngữ không có từ chỉ đỏ cơ bản, dùng lối nói miêu tả thường ngày.","th":"คำคุณศัพท์สีพื้นฐาน \"แดง\"; ใช้รูปขยาย/รูปอ้างอิง หมายถึงสีเอง ไม่ใช่ \"แดง\" ในความหมายการเมือง (คอมมิวนิสต์/ฝ่ายซ้าย) ไม่ใช่ผมสีแดง และไม่ใช่ \"สุก\" หากภาษาใดไม่มีคำสีแดงพื้นฐาน ให้ใช้คำบรรยายที่ใช้ในชีวิตประจำวัน","id":"Adjektiva warna dasar \"merah\"; bentuk atributif/kamus diutamakan. Warnanya sendiri — bukan \"merah\" dalam arti politik (komunis/kiri), bukan rambut merah, bukan pula \"matang\". Jika sebuah bahasa tidak punya istilah merah dasar, dipakai ungkapan deskriptif sehari-hari.","hi":"मूल रंग-विशेषण \"लाल\"; विशेषण/शब्दकोश रूप वरीयता। रंग स्वयं — राजनीतिक अर्थ में \"लाल\" (साम्यवादी/वामपंथी), लाल बाल या \"पका हुआ\" नहीं। जिन भाषाओं में मूल लाल शब्द नहीं है, वहाँ रोज़मर्रा का वर्णनात्मक शब्द लिया गया है।","de":"Grundfarbadjektiv \"rot\"; attributive Wörterbuchform bevorzugt. Die Farbe selbst — nicht \"rot\" im politischen Sinn (kommunistisch/links), nicht rotes Haar und nicht \"reif\". Fehlt einer Sprache ein Grundwort für Rot, wird der alltägliche beschreibende Ausdruck verwendet.","fr":"Adjectif de couleur de base \"rouge\"; forme attributive/de dictionnaire privilégiée. La couleur elle-même — pas \"rouge\" au sens politique (communiste/de gauche), ni les cheveux roux, ni \"mûr\". Si une langue n'a pas de terme de base pour le rouge, on retient l'expression descriptive courante.","it":"Aggettivo di colore base \"rosso\"; preferita la forma attributiva/di dizionario. Il colore in sé — non \"rosso\" in senso politico (comunista/di sinistra), non i capelli rossi e non \"maturo\". Se una lingua non ha un termine base per il rosso, si usa l'espressione descrittiva quotidiana.","es":"Adjetivo de color básico \"rojo\"; se prefiere la forma atributiva/de diccionario. El color en sí — no \"rojo\" en sentido político (comunista/de izquierda), ni el pelo pelirrojo, ni \"maduro\". Si una lengua carece de término básico para el rojo, se usa la expresión descriptiva cotidiana.","es_eu":"Adjetivo de color básico \"rojo\"; se prefiere la forma atributiva/de diccionario. El color en sí — no \"rojo\" en sentido político (comunista/de izquierda), ni el pelo pelirrojo, ni \"maduro\". Si una lengua carece de término básico para el rojo, se usa la expresión descriptiva cotidiana.","es_mx":"Adjetivo de color básico \"rojo\"; se prefiere la forma atributiva/de diccionario. El color en sí — no \"rojo\" en sentido político (comunista/de izquierda), ni el pelo pelirrojo, ni \"maduro\". Si una lengua carece de término básico para el rojo, se usa la expresión descriptiva cotidiana.","pt":"Adjetivo de cor básico \"vermelho\"; prefere-se a forma atributiva/de dicionário. A cor em si — não \"vermelho\" no sentido político (comunista/de esquerda), nem cabelo ruivo, nem \"maduro\". Se uma língua não tiver termo básico para vermelho, usa-se a expressão descritiva corrente.","pt_eu":"Adjetivo de cor básico \"vermelho\"; prefere-se a forma atributiva/de dicionário. A cor em si — não \"vermelho\" no sentido político (comunista/de esquerda), nem cabelo ruivo, nem \"maduro\". Se uma língua não tiver termo básico para vermelho, usa-se a expressão descritiva corrente.","pt_br":"Adjetivo de cor básico \"vermelho\"; prefere-se a forma atributiva/de dicionário. A cor em si — não \"vermelho\" no sentido político (comunista/de esquerda), nem cabelo ruivo, nem \"maduro\". Se uma língua não tiver termo básico para vermelho, usa-se a expressão descritiva corrente.","ru":"Базовое цветовое прилагательное \"красный\"; предпочтительна определительная/словарная форма. Сам цвет — не \"красный\" в политическом смысле (коммунистический/левый), не рыжие волосы и не \"спелый\". Если в языке нет базового слова для красного, берётся обиходное описательное выражение.","uk":"Базовий колірний прикметник \"червоний\"; перевага означальній/словниковій формі. Сам колір — не \"червоний\" у політичному сенсі (комуністичний/лівий), не руде волосся і не \"стиглий\". Якщо в мові немає базового слова для червоного, беруть побутовий описовий вислів.","ar":"صفة لونية أساسية \"أحمر\"؛ تُفضَّل الصيغة المعجمية. اللون نفسه — لا \"الأحمر\" بالمعنى السياسي (شيوعي/يساري)، ولا الشعر الأحمر، ولا \"الناضج\". وإذا خلت لغة من لفظ أساسي للأحمر، يُؤخذ التعبير الوصفي المتداول.","he":"שם תואר צבע בסיסי \"אדום\"; מועדפת צורת המילון. הצבע עצמו — לא \"אדום\" במובן הפוליטי (קומוניסטי/שמאלני), לא שיער ג'ינג'י ולא \"בשל\". בשפה שאין בה מילת יסוד לאדום, נלקח הביטוי התיאורי היומיומי.","sw":"Kivumishi cha rangi ya msingi \"nyekundu\"; umbo la sifa/la kamusi hupendelewa. Rangi yenyewe — si \"nyekundu\" kwa maana ya kisiasa (kikomunisti/mrengo wa kushoto), si nywele nyekundu, wala si \"iliyoiva\". Lugha isipokuwa na neno la msingi la nyekundu, hutumika maelezo ya kawaida."}},"white":{"label":{"en":"White","ja":"白い","ko":"하양","zh":"白","yue":"白","vi":"Trắng","th":"ขาว","id":"Putih","hi":"सफ़ेद","de":"Weiß","fr":"Blanc","it":"Bianco","es":"Blanco","es_eu":"Blanco","es_mx":"Blanco","pt":"Branco","pt_eu":"Branco","pt_br":"Branco","ru":"Белый","uk":"Білий","ar":"أبيض","he":"לבן","sw":"Nyeupe"},"definition":{"en":"White — the lightest colour, that of snow or milk; the basic colour term, not a skin-colour label.","ja":"白 — 雪や牛乳のような、最も明るい色。肌の色ではなく、基本色名としての「白」。","ko":"하양 — 눈이나 우유같이 가장 밝은 색. 피부색이 아니라 기본 색이름으로서의 흰색.","zh":"白 — 最浅的颜色，如雪或牛奶之色；作为基本颜色词，而非肤色称谓。","yue":"白 — 最淺嘅顏色，好似雪或者牛奶啦；係基本顏色詞，唔係講膚色。","vi":"Trắng — màu sáng nhất, màu của tuyết hay sữa; từ chỉ màu cơ bản, không phải nhãn màu da.","th":"ขาว — สีที่สว่างที่สุด สีของหิมะหรือน้ำนม เป็นคำเรียกสีพื้นฐาน ไม่ใช่คำเรียกสีผิว.","id":"Putih — warna paling terang, seperti salju atau susu; istilah warna dasar, bukan sebutan warna kulit.","hi":"सफ़ेद — सबसे हल्का रंग, बर्फ़ या दूध का; यह मूल रंग-नाम है, त्वचा के रंग का सूचक नहीं।","de":"Weiß — die hellste Farbe, die von Schnee oder Milch; der grundlegende Farbbegriff, keine Hautfarbenbezeichnung.","fr":"Blanc — la couleur la plus claire, celle de la neige ou du lait ; le terme de couleur fondamental, non une désignation de la couleur de peau.","it":"Bianco — il colore più chiaro, quello della neve o del latte; il termine cromatico di base, non un'etichetta per il colore della pelle.","es":"Blanco — el color más claro, el de la nieve o la leche; el término básico de color, no una etiqueta del color de piel.","es_eu":"Blanco — el color más claro, el de la nieve o la leche; el término básico de color, no una etiqueta del color de piel.","es_mx":"Blanco — el color más claro, el de la nieve o la leche; el término básico de color, no una etiqueta del color de piel.","pt":"Branco — a cor mais clara, a da neve ou do leite; o termo básico de cor, não uma designação de cor de pele.","pt_eu":"Branco — a cor mais clara, a da neve ou do leite; o termo básico de cor, não uma designação de cor de pele.","pt_br":"Branco — a cor mais clara, a da neve ou do leite; o termo básico de cor, não uma designação de cor de pele.","ru":"Белый — самый светлый цвет, цвет снега или молока; основное название цвета, а не обозначение цвета кожи.","uk":"Білий — найсвітліший колір, колір снігу чи молока; основна назва кольору, а не позначення кольору шкіри.","ar":"أبيض — أفتح الألوان، لون الثلج أو الحليب؛ مصطلح اللون الأساسي، وليس وصفًا للون البشرة.","he":"לבן — הצבע הבהיר ביותר, צבעם של שלג או חלב; מונח הצבע הבסיסי, ולא כינוי לצבע העור.","sw":"Nyeupe — rangi angavu zaidi, rangi ya theluji au maziwa; neno la msingi la rangi, si jina la rangi ya ngozi."}},"cuckoo":{"label":{"en":"Cuckoo","ja":"カッコウ","ko":"뻐꾸기","zh":"布谷鸟","yue":"布穀鳥","vi":"Chim cu cu","th":"นกคัคคู","id":"Burung kangkok","hi":"कोयल","de":"Kuckuck","fr":"Coucou","it":"Cuculo","es":"Cuco","es_eu":"Cuco","es_mx":"Cuco","pt":"Cuco","pt_eu":"Cuco","pt_br":"Cuco","ru":"Кукушка","uk":"Зозуля","ar":"وقواق","he":"קוקייה","sw":"Kekeo"},"definition":{"en":"The common cuckoo (Cuculus canorus) or a bird of the cuckoo family (Cuculidae) — the grey bird whose two-note call names it in many languages. NOT the cuckoo clock and NOT 'crazy'. Where a language distinguishes the common cuckoo from the koel, prefer the common-cuckoo word.","ja":"カッコウ (Cuculus canorus) またはカッコウ科 (Cuculidae) の鳥。その二音の鳴き声が多くの言語で名前の由来となった灰色の鳥。鳩時計や「頭がおかしい」の意味ではない。","ko":"뻐꾸기 (Cuculus canorus) 또는 두견이과 (Cuculidae)의 새. 두 음절 울음소리가 여러 언어에서 이름의 유래가 된 회색 새.","zh":"大杜鹃／布谷鸟 (Cuculus canorus) 或杜鹃科 (Cuculidae) 的鸟——其两音节叫声在许多语言中成为名称来源的灰色鸟。不是布谷鸟钟，也不是「疯」。","yue":"大杜鵑／布穀鳥 (Cuculus canorus) 或杜鵑科嘅雀——牠兩個音嘅叫聲喺好多語言入面成為名稱嘅來源。唔係布穀鳥鐘，亦唔係「癲」。","vi":"Chim cu cu (Cuculus canorus) hay loài thuộc họ Cuculidae — loài chim xám mà tiếng kêu hai nốt đặt tên cho nó trong nhiều ngôn ngữ. KHÔNG phải đồng hồ, KHÔNG phải 'điên'.","th":"นกคัคคูหรือนกดุเหว่า (Cuculus canorus) วงศ์ Cuculidae — นกสีเทาที่เสียงร้องสองพยางค์เป็นที่มาของชื่อในหลายภาษา ไม่ใช่นาฬิกา ไม่ใช่ 'บ้า'","id":"Burung kangkok (Cuculus canorus) atau anggota suku Cuculidae — burung kelabu yang bunyi dua-nada-nya menjadi asal namanya di banyak bahasa. BUKAN jam, BUKAN 'gila'.","hi":"कोयल/कुक्कू (Cuculus canorus) या Cuculidae कुल का पक्षी — जिसकी दो-स्वर बोली से अनेक भाषाओं में इसका नाम बना। घड़ी या 'पागल' नहीं।","de":"Der Kuckuck (Cuculus canorus) oder ein Vogel der Familie Cuculidae — der Vogel, dessen zweitöniger Ruf ihm in vielen Sprachen den Namen gab. NICHT die Uhr, NICHT 'verrückt'.","fr":"Le coucou gris (Cuculus canorus) ou un oiseau de la famille des Cuculidae — l'oiseau dont le cri à deux notes lui donne son nom dans de nombreuses langues. PAS l'horloge, PAS 'fou'.","it":"Il cuculo (Cuculus canorus) o un uccello della famiglia Cuculidae — l'uccello il cui richiamo a due note gli dà il nome in molte lingue. NON l'orologio, NON 'matto'.","es":"El cuco común (Cuculus canorus) o un ave de la familia Cuculidae — cuyo canto de dos notas le da nombre en muchas lenguas. NO el reloj, NO 'loco'.","es_eu":"El cuco común (Cuculus canorus) o un ave de la familia Cuculidae — cuyo canto de dos notas le da nombre en muchas lenguas. NO el reloj, NO 'loco'.","es_mx":"El cuco común (Cuculus canorus) o un ave de la familia Cuculidae — cuyo canto de dos notas le da nombre en muchas lenguas. NO el reloj, NO 'loco'.","pt":"O cuco-canoro (Cuculus canorus) ou uma ave da família Cuculidae — cujo canto de duas notas lhe dá o nome em muitas línguas. NÃO o relógio, NÃO 'louco'.","pt_eu":"O cuco-canoro (Cuculus canorus) ou uma ave da família Cuculidae — cujo canto de duas notas lhe dá o nome em muitas línguas. NÃO o relógio, NÃO 'louco'.","pt_br":"O cuco (Cuculus canorus) ou uma ave da família Cuculidae — cujo canto de duas notas lhe dá o nome em muitas línguas. NÃO o relógio, NÃO 'louco'.","ru":"Обыкновенная кукушка (Cuculus canorus) или птица семейства кукушковых (Cuculidae) — серая птица, чей двусложный крик дал ей имя во многих языках. НЕ часы, НЕ 'сумасшедший'.","uk":"Зозуля звичайна (Cuculus canorus) або птах родини зозулевих (Cuculidae) — сірий птах, чий двоскладовий крик дав йому назву в багатьох мовах. НЕ годинник, НЕ 'божевільний'.","ar":"الوَقْوَاق (Cuculus canorus) أو طائر من فصيلة الوقواقيات (Cuculidae) — الطائر الرمادي الذي سمّاه صوته ذو النغمتين في كثير من اللغات. ليس ساعة ولا 'مجنون'.","he":"הקוקייה (Cuculus canorus) או ציפור ממשפחת הקוקיים (Cuculidae) — הציפור האפורה שקריאתה בת שני הצלילים העניקה לה את שמה בשפות רבות. לא שעון ולא 'מטורף'.","sw":"Kekeo (Cuculus canorus) au ndege wa familia ya Cuculidae — ndege wa kijivu ambaye mlio wake wa noti mbili ulimpa jina katika lugha nyingi. SIYO saa wala 'kichaa'."},"partial":true},"woof":{"label":{"en":"Woof","ja":"ワンワン","ko":"멍멍","zh":"汪汪","yue":"汪汪","vi":"Gâu gâu","th":"โฮ่ง ๆ","id":"Guk guk","hi":"भौं भौं","de":"Wau wau","fr":"Ouaf","it":"Bau bau","es":"Guau","es_eu":"Guau","es_mx":"Guau","pt":"Au au","pt_eu":"Au au","pt_br":"Au au","ru":"Гав-гав","uk":"Гав-гав","ar":"هَوْ هَوْ","he":"הַב הַב","sw":"Woof"},"definition":{"en":"The onomatopoeia for a dog's bark — the conventional imitative word in each language (English 'woof' / 'bow-wow', Japanese ワンワン, Mandarin 汪汪). NOT the verb 'to bark' and NOT a literal recording; the culturally agreed spelling of the sound.","ja":"犬の吠え声の擬音語 — 各言語で慣用的に用いる写声語（英語 'woof'／'bow-wow'、日本語 ワンワン、中国語 汪汪）。動詞「吠える」ではなく、音を文化的に綴った形。","ko":"개 짖는 소리의 의성어 — 각 언어에서 관용적으로 쓰는 흉내말(영어 'woof', 일본어 ワンワン, 중국어 汪汪). 동사 '짖다'가 아니라 소리를 관습적으로 적은 형태.","zh":"狗吠声的拟声词 — 各语言约定俗成的摹声词（英语 'woof'、日语 ワンワン、汉语 汪汪）。不是动词「吠」，而是对声音的习惯写法。","yue":"狗吠聲嘅擬聲詞 — 各語言約定俗成嘅摹聲詞（英語 'woof'、日語 ワンワン、漢語 汪汪）。唔係動詞「吠」，係對聲音嘅慣用寫法。","vi":"Từ tượng thanh cho tiếng chó sủa — dạng mô phỏng quy ước của mỗi ngôn ngữ (Anh 'woof', Nhật ワンワン, Hán 汪汪). KHÔNG phải động từ 'sủa'.","th":"คำเลียนเสียงเห่าของหมา — รูปเลียนเสียงที่แต่ละภาษาใช้กันจนเป็นแบบแผน (อังกฤษ 'woof', ญี่ปุ่น ワンワン, จีน 汪汪) ไม่ใช่คำกริยา 'เห่า'","id":"Onomatope untuk gonggongan anjing — bentuk tiruan bunyi yang lazim di tiap bahasa (Inggris 'woof', Jepang ワンワン, Mandarin 汪汪). BUKAN kata kerja 'menggonggong'.","hi":"कुत्ते के भौंकने की ध्वनि का अनुकरणात्मक शब्द — हर भाषा का प्रचलित नक़ल-शब्द (अंग्रेज़ी 'woof', जापानी ワンワン, चीनी 汪汪)। यह क्रिया 'भौंकना' नहीं है।","de":"Die Lautmalerei für das Bellen eines Hundes — das übliche Nachahmungswort jeder Sprache (englisch 'woof', japanisch ワンワン, chinesisch 汪汪). NICHT das Verb 'bellen'.","fr":"L'onomatopée de l'aboiement d'un chien — le mot imitatif conventionnel de chaque langue (anglais 'woof', japonais ワンワン, chinois 汪汪). PAS le verbe « aboyer ».","it":"L'onomatopea dell'abbaiare di un cane — la parola imitativa convenzionale di ogni lingua (inglese 'woof', giapponese ワンワン, cinese 汪汪). NON il verbo «abbaiare».","es":"La onomatopeya del ladrido de un perro — la palabra imitativa convencional de cada lengua (inglés 'woof', japonés ワンワン, chino 汪汪). NO el verbo 'ladrar'.","es_eu":"La onomatopeya del ladrido de un perro — la palabra imitativa convencional de cada lengua (inglés 'woof', japonés ワンワン, chino 汪汪). NO el verbo 'ladrar'.","es_mx":"La onomatopeya del ladrido de un perro — la palabra imitativa convencional de cada lengua (inglés 'woof', japonés ワンワン, chino 汪汪). NO el verbo 'ladrar'.","pt":"A onomatopeia do latido de um cão — a palavra imitativa convencional de cada língua (inglês 'woof', japonês ワンワン, chinês 汪汪). NÃO o verbo 'latir'.","pt_eu":"A onomatopeia do latido de um cão — a palavra imitativa convencional de cada língua (inglês 'woof', japonês ワンワン, chinês 汪汪). NÃO o verbo 'latir'.","pt_br":"A onomatopeia do latido de um cachorro — a palavra imitativa convencional de cada língua (inglês 'woof', japonês ワンワン, chinês 汪汪). NÃO o verbo 'latir'.","ru":"Звукоподражание лаю собаки — принятое в каждом языке подражательное слово (англ. 'woof', яп. ワンワン, кит. 汪汪). НЕ глагол «лаять».","uk":"Звуконаслідування гавкоту собаки — усталене в кожній мові наслідувальне слово (англ. 'woof', яп. ワンワン, кит. 汪汪). НЕ дієслово «гавкати».","ar":"محاكاة صوتية لنباح الكلب — الكلمة المحاكية المتعارف عليها في كل لغة (الإنجليزية 'woof'، اليابانية ワンワン، الصينية 汪汪). ليست الفعل 'ينبح'.","he":"מילת הברה לנביחת כלב — מילת החיקוי המקובלת בכל שפה (אנגלית 'woof', יפנית ワンワン, סינית 汪汪). לא הפועל 'לנבוח'.","sw":"Onomatopeia ya mbwa kubweka — neno la kuiga sauti linalozoeleka katika kila lugha (Kiingereza 'woof', Kijapani ワンワン, Kichina 汪汪). SI kitenzi 'kubweka'."},"partial":true},"computer":{"label":{"en":"Computer","ja":"コンピューター","ko":"컴퓨터","zh":"电脑","yue":"電腦","vi":"Máy tính","th":"คอมพิวเตอร์","id":"Komputer","hi":"कंप्यूटर","de":"Computer","fr":"Ordinateur","it":"Computer","es":"Computadora","es_eu":"Ordenador","es_mx":"Computadora","pt":"Computador","pt_eu":"Computador","pt_br":"Computador","ru":"Компьютер","uk":"Комп’ютер","ar":"حاسوب","he":"מחשב","sw":"Kompyuta"},"definition":{"en":"A general-purpose electronic digital computer. The ordinary modern noun; not a person who computes, and not specifically a laptop, desktop, or smartphone. In historical and reconstructed languages the cell holds the nearest pre-electronic equivalent instead: a counting device such as an abacus or counting rods, or a person who reckons.","ja":"汎用の電子式デジタル計算機を表す普通名詞。計算する人を指さず、ノート型・デスクトップ型・スマートフォンのいずれかに限定しない。歴史言語・祖語の欄には、電子計算機以前の最も近いもの——そろばんや算木のような計算具、あるいは計算を行う人——が入る。","ko":"범용 전자 디지털 컴퓨터를 뜻하는 일반 명사. 계산하는 사람을 뜻하지 않으며 노트북·데스크톱·스마트폰 중 하나로 한정하지 않는다.역사 언어와 조어 칸에는 전자 계산기 이전의 가장 가까운 것, 즉 주판이나 산목 같은 계산 도구 또는 계산하는 사람이 들어간다.","zh":"指通用电子数字计算机的普通名词；不是从事计算的人，也不专指笔记本、台式机或智能手机。历史语言与原始语的格子里放的是电子计算机出现之前最接近的事物：算盘、算筹一类的计算工具，或从事计算的人。","yue":"指通用電子數碼電腦嘅普通名詞；唔係做計算嘅人，亦唔專指手提、桌面電腦或者智能電話。歷史語言同原始語嘅格入面放嘅係電子計算機出現之前最接近嘅嘢：算盤、算籌一類嘅計算工具，或者從事計算嘅人。","vi":"Danh từ thông thường chỉ máy tính điện tử số đa dụng; không phải người tính toán và không riêng máy xách tay, máy bàn hay điện thoại thông minh.Ở các ngôn ngữ lịch sử và ngôn ngữ tiền thân, ô này chứa thứ gần nhất trước thời điện tử: một công cụ tính như bàn tính hay que tính, hoặc người làm tính.","th":"คำนามทั่วไปหมายถึงเครื่องคอมพิวเตอร์ดิจิทัลอิเล็กทรอนิกส์อเนกประสงค์ ไม่ใช่คนคำนวณ และไม่จำกัดว่าเป็นแล็ปท็อป เดสก์ท็อป หรือสมาร์ตโฟนในภาษาโบราณและภาษาต้นตระกูล ช่องนี้บรรจุสิ่งที่ใกล้เคียงที่สุดก่อนยุคอิเล็กทรอนิกส์ ได้แก่ อุปกรณ์นับอย่างลูกคิดหรือไม้นับ หรือผู้ทำการคำนวณ","id":"Nomina umum untuk komputer digital elektronik serbaguna; bukan orang yang menghitung dan tidak khusus laptop, desktop, atau ponsel pintar.Pada bahasa historis dan proto, sel ini berisi padanan terdekat sebelum era elektronik: alat hitung seperti sempoa atau batang hitung, atau orang yang melakukan perhitungan.","hi":"सामान्य प्रयोजन वाला इलेक्ट्रॉनिक डिजिटल कंप्यूटर; गणना करने वाला व्यक्ति नहीं और विशेष रूप से लैपटॉप, डेस्कटॉप या स्मार्टफ़ोन नहीं।ऐतिहासिक और पुनर्निर्मित भाषाओं में यह खाना इलेक्ट्रॉनिक युग से पहले की निकटतम वस्तु रखता है: अबेकस या गणना-छड़ जैसा उपकरण, या गणना करने वाला व्यक्ति।","de":"Allgemeines Substantiv für einen universell einsetzbaren elektronischen Digitalrechner; keine rechnende Person und nicht speziell Laptop, Desktop oder Smartphone. In historischen und rekonstruierten Sprachen steht hier stattdessen das nächstliegende vorelektronische Äquivalent: ein Rechengerät wie Abakus oder Rechenstäbchen oder eine Person, die rechnet.","fr":"Nom courant désignant une machine électronique numérique polyvalente ; pas une personne qui calcule, ni spécialement un portable, un ordinateur de bureau ou un smartphone. Dans les langues historiques et reconstruites, la case contient l’équivalent pré-électronique le plus proche : un instrument de calcul comme l’abaque ou les baguettes à calculer, ou une personne qui calcule.","it":"Nome comune per un calcolatore elettronico digitale generico; non una persona che calcola né specificamente un portatile, desktop o smartphone. Nelle lingue storiche e ricostruite la casella contiene invece l’equivalente pre-elettronico più vicino: uno strumento di calcolo come l’abaco o i bastoncini da conto, oppure una persona che calcola.","es":"Sustantivo común para una computadora digital electrónica de uso general; no una persona que calcula ni específicamente una portátil, de escritorio o un teléfono inteligente. En las lenguas históricas y reconstruidas la celda contiene el equivalente preelectrónico más cercano: un instrumento de cálculo como el ábaco o las varillas de contar, o una persona que calcula.","es_eu":"Sustantivo común para un ordenador digital electrónico de uso general; no una persona que calcula ni específicamente un portátil, sobremesa o teléfono inteligente. En las lenguas históricas y reconstruidas la celda contiene el equivalente preelectrónico más cercano: un instrumento de cálculo como el ábaco o las varillas de contar, o una persona que calcula.","es_mx":"Sustantivo común para una computadora digital electrónica de uso general; no una persona que calcula ni específicamente una laptop, computadora de escritorio o teléfono inteligente. En las lenguas históricas y reconstruidas la celda contiene el equivalente preelectrónico más cercano: un instrumento de cálculo como el ábaco o las varillas de contar, o una persona que calcula.","pt":"Substantivo comum para um computador digital eletrónico de uso geral; não uma pessoa que calcula nem especificamente um portátil, desktop ou smartphone. Nas línguas históricas e reconstruídas a célula contém o equivalente pré-eletrónico mais próximo: um instrumento de cálculo como o ábaco ou as varetas de contagem, ou uma pessoa que calcula.","pt_eu":"Substantivo comum para um computador digital eletrónico de uso geral; não uma pessoa que calcula nem especificamente um portátil, computador de secretária ou smartphone. Nas línguas históricas e reconstruídas a célula contém o equivalente pré-eletrónico mais próximo: um instrumento de cálculo como o ábaco ou as varetas de contagem, ou uma pessoa que calcula.","pt_br":"Substantivo comum para um computador digital eletrônico de uso geral; não uma pessoa que calcula nem especificamente um notebook, desktop ou smartphone. Nas línguas históricas e reconstruídas a célula contém o equivalente pré-eletrónico mais próximo: um instrumento de cálculo como o ábaco ou as varetas de contagem, ou uma pessoa que calcula.","ru":"Обычное существительное для универсального электронного цифрового компьютера; не человек, который считает, и не конкретно ноутбук, настольный компьютер или смартфон. В исторических и реконструированных языках в ячейке стоит ближайший доэлектронный эквивалент: счётное устройство вроде абака или счётных палочек либо человек, производящий вычисления.","uk":"Звичайний іменник для універсального електронного цифрового комп’ютера; не людина, яка обчислює, і не конкретно ноутбук, настільний комп’ютер чи смартфон. В історичних і реконструйованих мовах у комірці стоїть найближчий доелектронний відповідник: лічильний пристрій на кшталт абака чи лічильних паличок або людина, яка обчислює.","ar":"اسم عام للحاسوب الرقمي الإلكتروني متعدد الأغراض؛ لا يعني الشخص الذي يحسب، ولا يختص بالحاسوب المحمول أو المكتبي أو الهاتف الذكي. في اللغات التاريخية والمُعاد بناؤها تحتوي الخانة على أقرب مكافئ سابق للعصر الإلكتروني: أداة حساب كالمِعداد أو عيدان العد، أو شخص يقوم بالحساب.","he":"שם עצם כללי למחשב דיגיטלי אלקטרוני רב־תכליתי; לא אדם שמחשב, ולא דווקא מחשב נייד, שולחני או טלפון חכם. בשפות היסטוריות ומשוחזרות התא מכיל את המקבילה הקרובה ביותר מלפני העידן האלקטרוני: מכשיר חישוב כגון חשבונייה או מקלות ספירה, או אדם המבצע חישובים.","sw":"Nomino ya kawaida ya kompyuta ya kidijitali ya kielektroniki yenye matumizi mengi; si mtu anayehesabu wala hasa laptopu, kompyuta ya mezani au simu janja. Katika lugha za kihistoria na za asili, kisanduku hiki kina kifaa cha karibu zaidi cha kabla ya enzi ya kielektroniki: chombo cha kuhesabu kama abakasi au vijiti vya kuhesabu, au mtu anayehesabu."},"partial":true},"sushi":{"label":{"en":"Sushi","ja":"寿司","ko":"초밥","zh":"寿司","yue":"壽司","vi":"Sushi","th":"ซูชิ","id":"Susyi","hi":"सुशी","de":"Sushi","fr":"Sushi","it":"Sushi","es":"Sushi","es_eu":"Sushi","es_mx":"Sushi","pt":"Sushi","pt_eu":"Sushi","pt_br":"Sushi","ru":"Суши","uk":"Суші","ar":"سوشي","he":"סושי","sw":"Sushi"},"definition":{"en":"The Japanese dish built around seasoned vinegared rice, usually served with toppings or fillings. Not raw fish in general and not sashimi. In historical languages the cell holds the ancestral dish instead: salted or fermented preserved fish. Vinegared-rice sushi is an Edo-period development, so even the Heian and Middle Japanese 鮓 is narezushi — fish preserved in rice — not the modern dish.","ja":"酢で味付けした飯を中心に、具や種と組み合わせる日本料理。生魚一般や刺身のことではない。歴史言語の欄には祖型の食品——塩蔵・発酵させた保存魚——が入る。酢飯の寿司は江戸期の産物なので、平安・中世日本語の「鮓」も現代の寿司ではなく熟れ鮓（飯に漬けた保存魚）を指す。","ko":"식초로 간한 밥에 재료를 얹거나 넣어 만드는 일본 음식. 날생선 일반이나 사시미를 뜻하지 않는다.역사 언어 칸에는 그 조상격 음식, 곧 소금에 절이거나 발효시킨 보존 생선이 들어간다. 초밥은 에도 시대의 산물이므로 헤이안·중세 일본어의 「鮓」도 현대의 초밥이 아니라 나레즈시(밥에 절인 보존 생선)를 뜻한다.","zh":"以醋调味的米饭为基础、通常配以配料或馅料的日本料理；不是泛指生鱼，也不是生鱼片。历史语言的格子里放的是其祖型食物：盐渍或发酵的保存鱼。醋饭寿司是江户时代的产物，因此平安、中世日语的「鮓」也指熟寿司（用饭腌渍的保存鱼），而非今日的寿司。","yue":"以醋調味嘅飯為主、通常配搭餸料或者餡料嘅日本料理；唔係泛指生魚，亦唔係刺身。歷史語言嘅格入面放嘅係佢嘅祖型食物：鹽醃或者發酵嘅保存魚。醋飯壽司係江戶時代先有，所以平安、中世日語嘅「鮓」都係指熟壽司（用飯醃嘅保存魚），唔係今日嗰種。","vi":"Món ăn Nhật Bản lấy cơm trộn giấm làm nền, thường ăn với nguyên liệu phủ hoặc cuộn bên trong; không phải cá sống nói chung hay sashimi.Ở các ngôn ngữ lịch sử, ô này chứa món ăn tiền thân: cá ướp muối hoặc lên men để bảo quản. Sushi cơm giấm là sản phẩm thời Edo, nên chữ 鮓 trong tiếng Nhật thời Heian và trung đại cũng chỉ narezushi — cá ủ trong cơm — chứ không phải món ngày nay.","th":"อาหารญี่ปุ่นที่มีข้าวปรุงน้ำส้มสายชูเป็นหลัก มักเสิร์ฟพร้อมหน้าหรือไส้ ไม่ได้หมายถึงปลาดิบทั่วไปหรือซาชิมิในภาษาโบราณ ช่องนี้บรรจุอาหารต้นแบบ คือปลาหมักเกลือหรือปลาหมักถนอมอาหาร ซูชิข้าวปรุงน้ำส้มสายชูเกิดในสมัยเอโดะ ดังนั้นคำว่า 鮓 ในภาษาญี่ปุ่นสมัยเฮอันและยุคกลางจึงหมายถึงนาเรซูชิ ปลาหมักในข้าว มิใช่ซูชิอย่างปัจจุบัน","id":"Hidangan Jepang berbahan utama nasi berbumbu cuka, biasanya dengan lauk di atas atau isian; bukan ikan mentah secara umum dan bukan sashimi.Pada bahasa historis, sel ini berisi hidangan leluhurnya: ikan yang diawetkan dengan garam atau fermentasi. Sushi dengan nasi bercuka baru muncul pada zaman Edo, sehingga 鮓 dalam bahasa Jepang Heian dan pertengahan pun berarti narezushi — ikan yang diawetkan dalam nasi — bukan hidangan masa kini.","hi":"सिरके से स्वाद दिए चावल पर आधारित जापानी व्यंजन, जिसे आम तौर पर ऊपर रखी सामग्री या भरावन के साथ परोसा जाता है; सामान्य कच्ची मछली या साशिमी नहीं।ऐतिहासिक भाषाओं में यह खाना उसका पूर्वज व्यंजन रखता है: नमक लगाकर या किण्वित करके सुरक्षित की गई मछली। सिरकेदार चावल वाला सुशी एदो काल की देन है, इसलिए हेइआन और मध्यकालीन जापानी का 鮓 भी नरेज़ुशी है — चावल में सुरक्षित मछली — आज का व्यंजन नहीं।","de":"Japanisches Gericht auf der Grundlage von gewürztem Essigreis, meist mit Belag oder Füllung; nicht roher Fisch allgemein und nicht Sashimi. In historischen Sprachen steht hier stattdessen das Vorläufergericht: gesalzener oder fermentierter Fisch als Konserve. Sushi mit gesäuertem Reis ist eine Entwicklung der Edo-Zeit, weshalb auch das 鮓 des Heian- und Mitteljapanischen Narezushi meint — in Reis eingelegten Fisch — und nicht das heutige Gericht.","fr":"Plat japonais à base de riz vinaigré assaisonné, généralement garni ou fourré ; pas le poisson cru en général ni le sashimi. Dans les langues historiques, la case contient le plat ancestral : du poisson salé ou fermenté, conservé. Le sushi au riz vinaigré est une création de l’époque d’Edo ; le 鮓 du japonais de Heian et du moyen japonais désigne donc le narezushi — du poisson conservé dans du riz — et non le plat actuel.","it":"Piatto giapponese a base di riso condito con aceto, di solito con guarnizioni o ripieni; non pesce crudo in generale né sashimi. Nelle lingue storiche la casella contiene il piatto antenato: pesce salato o fermentato, conservato. Il sushi con riso all’aceto è un’invenzione del periodo Edo, quindi anche il 鮓 del giapponese di Heian e medio indica il narezushi — pesce conservato nel riso — non il piatto odierno.","es":"Plato japonés basado en arroz avinagrado sazonado, normalmente con ingredientes encima o como relleno; no pescado crudo en general ni sashimi. En las lenguas históricas la celda contiene el plato antecesor: pescado salado o fermentado en conserva. El sushi de arroz avinagrado es una creación del período Edo, de modo que el 鮓 del japonés de Heian y medieval designa el narezushi — pescado conservado en arroz — y no el plato actual.","es_eu":"Plato japonés basado en arroz avinagrado sazonado, normalmente con ingredientes encima o como relleno; no pescado crudo en general ni sashimi. En las lenguas históricas la celda contiene el plato antecesor: pescado salado o fermentado en conserva. El sushi de arroz avinagrado es una creación del período Edo, de modo que el 鮓 del japonés de Heian y medieval designa el narezushi — pescado conservado en arroz — y no el plato actual.","es_mx":"Platillo japonés basado en arroz avinagrado sazonado, normalmente con ingredientes encima o como relleno; no pescado crudo en general ni sashimi. En las lenguas históricas la celda contiene el plato antecesor: pescado salado o fermentado en conserva. El sushi de arroz avinagrado es una creación del período Edo, de modo que el 鮓 del japonés de Heian y medieval designa el narezushi — pescado conservado en arroz — y no el plato actual.","pt":"Prato japonês à base de arroz temperado com vinagre, normalmente com coberturas ou recheios; não peixe cru em geral nem sashimi. Nas línguas históricas a célula contém o prato ancestral: peixe salgado ou fermentado em conserva. O sushi de arroz avinagrado é uma criação do período Edo, pelo que o 鮓 do japonês de Heian e medieval designa o narezushi — peixe conservado em arroz — e não o prato atual.","pt_eu":"Prato japonês à base de arroz temperado com vinagre, normalmente com coberturas ou recheios; não peixe cru em geral nem sashimi. Nas línguas históricas a célula contém o prato ancestral: peixe salgado ou fermentado em conserva. O sushi de arroz avinagrado é uma criação do período Edo, pelo que o 鮓 do japonês de Heian e medieval designa o narezushi — peixe conservado em arroz — e não o prato atual.","pt_br":"Prato japonês à base de arroz temperado com vinagre, geralmente com coberturas ou recheios; não peixe cru em geral nem sashimi. Nas línguas históricas a célula contém o prato ancestral: peixe salgado ou fermentado em conserva. O sushi de arroz avinagrado é uma criação do período Edo, pelo que o 鮓 do japonês de Heian e medieval designa o narezushi — peixe conservado em arroz — e não o prato atual.","ru":"Японское блюдо на основе приправленного уксусом риса, обычно с начинкой или добавками сверху; не сырая рыба вообще и не сашими. В исторических языках в ячейке стоит блюдо-предшественник: солёная или ферментированная рыба длительного хранения. Суси на подкислённом рисе — изобретение эпохи Эдо, поэтому 鮓 хэйанского и среднеяпонского означает нарэдзуси — рыбу, выдержанную в рисе, — а не современное блюдо.","uk":"Японська страва на основі приправленого оцтом рису, зазвичай із начинкою або додатками зверху; не сира риба взагалі й не сашимі. В історичних мовах у комірці стоїть страва-попередниця: солона або ферментована риба тривалого зберігання. Суші на підкисленому рисі — винахід доби Едо, тож 鮓 хейанської та середньояпонської означає нарезусі — рибу, витриману в рисі, — а не сучасну страву.","ar":"طبق ياباني أساسه أرز متبل بالخل، ويُقدَّم عادةً مع إضافات فوقه أو حشوات؛ لا يعني السمك النيئ عموماً ولا الساشيمي. في اللغات التاريخية تحتوي الخانة على الطبق السَّلَف: سمك مملَّح أو مخمَّر للحفظ. فالسوشي بأرز الخل نشأ في عصر إيدو، ولذلك فإن 鮓 في اليابانية الهيانية والوسطى تعني ناريزوشي — سمكًا محفوظًا في الأرز — لا الطبق الحالي.","he":"מאכל יפני המבוסס על אורז מתובל בחומץ, בדרך כלל עם תוספות או מילוי; לא דג נא באופן כללי ולא סשימי. בשפות היסטוריות התא מכיל את המאכל הקדום: דג מלוח או מותסס לשימור. סושי על אורז מוחמץ הוא התפתחות של תקופת אדו, ולכן גם 鮓 ביפנית של הֵיאָן וביפנית התיכונה פירושו נָרֶזוּשִׁי — דג משומר באורז — ולא המאכל של ימינו.","sw":"Chakula cha Kijapani chenye msingi wa wali uliokolezwa siki, kwa kawaida pamoja na vitu vya juu au vya kujaza; si samaki mbichi kwa ujumla wala sashimi. Katika lugha za kihistoria, kisanduku hiki kina chakula cha awali: samaki waliotiwa chumvi au kuchachushwa ili kuhifadhiwa. Sushi ya wali wa siki ilianza katika enzi ya Edo, hivyo 鮓 ya Kijapani cha Heian na cha kati humaanisha narezushi — samaki waliohifadhiwa katika wali — si chakula cha leo."},"partial":true},"tea":{"label":{"en":"Tea","ja":"お茶（茶）","ko":"차(茶)","zh":"茶","yue":"茶","vi":"Trà","th":"ชา","id":"Teh","hi":"चाय","de":"Tee","fr":"Thé","it":"Tè","es":"Té","es_eu":"Té","es_mx":"Té","pt":"Chá","pt_eu":"Chá","pt_br":"Chá","ru":"Чай","uk":"Чай","ar":"شاي","he":"תה","sw":"Chai"},"definition":{"en":"Tea — the hot beverage brewed from the leaves of Camellia sinensis, and the world's second most-drunk drink after water. Its name almost everywhere traces to one of two routes out of China: the overland Silk Road spread northern-Chinese chá (giving chai, chay, çay, shāy), while Dutch ships carrying Fujianese tê by sea spread it as tea, thé, Tee. A few languages (Polish herbata, Lithuanian arbata) keep a third, Latin-derived root.","ja":"茶（ちゃ）——ツバキ科の植物チャノキの葉から淹れる温かい飲み物で、水に次いで世界で最も飲まれている。その呼び名は世界中でほぼ、中国から広まった二つの経路のいずれかに由来する。陸のシルクロードは北方中国語の「chá」を広め（chai・çay・シャーイ）、海路で福建語の「tê」を運んだオランダ船は「tea・thé・Tee」を広めた。ポーランド語 herbata やリトアニア語 arbata のように、ラテン語由来の第三の語源を保つ言語もある。","ko":"차(茶) — 동백나무과 식물인 차나무의 잎으로 우려낸 따뜻한 음료로, 물 다음으로 세계에서 가장 많이 마시는 음료이다. 그 이름은 거의 어디서나 중국에서 퍼져 나간 두 경로 중 하나에서 유래한다. 육상 실크로드는 북방 중국어 ‘차(chá)’를 퍼뜨렸고(chai·çay·샤이), 바닷길로 푸젠어 ‘테(tê)’를 실어 나른 네덜란드 배는 ‘tea·thé·Tee’를 퍼뜨렸다. 폴란드어 herbata, 리투아니아어 arbata처럼 라틴어에서 온 제3의 어원을 지닌 언어도 있다.","zh":"茶——用山茶科植物茶树的叶子冲泡的热饮，是仅次于水的全球第二大饮品。它的名称几乎在世界各地都源自茶叶走出中国的两条路线之一：陆上丝绸之路传播了北方汉语的「chá」（chai、çay、shāy），而由海路运送福建话「tê」的荷兰商船则传播了「tea、thé、Tee」。少数语言（波兰语 herbata、立陶宛语 arbata）保留了源自拉丁语的第三种词根。","yue":"茶——用山茶科植物「茶樹」（Camellia sinensis）嘅葉沖泡出嚟嘅熱飲，係全世界飲得第二多嘅飲品，僅次於水。呢個名喺全球幾乎都係嚟自中國嘅兩條路線之一：陸路絲綢之路將北方中文嘅 cha 呢個讀音傳咗出去（衍生出 chai、chay、cay、shay呢啲叫法），而荷蘭船隻就沿住海路將福建話嘅 te 呢個讀音帶出去，變成咗 tea、the、Tee。少數語言（好似波蘭文 herbata、立陶宛文 arbata）就保留住第三個、源自拉丁文嘅詞根。","vi":"Trà — thức uống nóng được pha từ lá cây trà (Camellia sinensis), và là loại đồ uống được tiêu thụ nhiều thứ hai trên thế giới, chỉ sau nước lã. Tên gọi của nó ở hầu như khắp nơi đều bắt nguồn từ một trong hai con đường mà nó rời khỏi Trung Quốc: con đường tơ lụa trên bộ đã truyền bá cách phát âm cha của tiếng Hán phương Bắc (sinh ra chai, chay, cay, shay), trong khi các tàu Hà Lan chở cách phát âm te của tiếng Phúc Kiến theo đường biển đã truyền bá nó thành tea, the, Tee. Một vài ngôn ngữ (tiếng Ba Lan herbata, tiếng Litva arbata) vẫn giữ một gốc từ thứ ba, bắt nguồn từ tiếng Latinh.","th":"ชา — เครื่องดื่มร้อนที่ชงจากใบของต้นชา (Camellia sinensis) และเป็นเครื่องดื่มที่มีผู้บริโภคมากเป็นอันดับสองของโลก รองจากน้ำเปล่า ชื่อเรียกของมันในเกือบทุกภาษาสืบย้อนไปถึงเส้นทางใดเส้นทางหนึ่งจากสองเส้นทางที่แพร่ออกจากจีน คือเส้นทางสายไหมทางบกซึ่งแพร่คำว่า cha ในภาษาจีนเหนือ (กลายเป็น chai, chay, cay, shay) ขณะที่เรือของชาวดัตช์ซึ่งขนคำว่า te ในภาษาฮกเกี้ยนของฝูเจี้ยนไปทางทะเล ได้แพร่คำนี้ในรูป tea, the, Tee ส่วนบางภาษา (เช่น herbata ในภาษาโปแลนด์ และ arbata ในภาษาลิทัวเนีย) ยังคงรากศัพท์ที่สามซึ่งมาจากภาษาละตินไว้","id":"Teh — minuman panas yang diseduh dari daun tanaman teh (Camellia sinensis), dan merupakan minuman yang paling banyak diminum kedua di dunia setelah air. Namanya di hampir semua tempat dapat ditelusuri ke salah satu dari dua jalur keluarnya dari Tiongkok: Jalur Sutra darat menyebarkan kata cha dari bahasa Tionghoa Utara (melahirkan chai, chay, cay, shay), sementara kapal-kapal Belanda yang membawa kata te dari bahasa Hokkien (Fujian) lewat laut menyebarkannya sebagai tea, the, Tee. Beberapa bahasa (bahasa Polandia herbata, bahasa Lituania arbata) mempertahankan akar kata ketiga yang berasal dari bahasa Latin.","hi":"चाय — कैमेलिया साइनेंसिस (Camellia sinensis) की पत्तियों से बनाया जाने वाला गरम पेय, जो पानी के बाद दुनिया में सबसे ज़्यादा पिया जाने वाला पेय है। लगभग हर जगह इसका नाम चीन से बाहर फैलने के दो रास्तों में से किसी एक से निकला है: स्थल मार्ग रेशम मार्ग (सिल्क रोड) ने उत्तरी चीनी भाषा के cha को फैलाया (जिससे chai, chay, cay, shay बने), जबकि डच जहाज़ों ने समुद्री मार्ग से फ़ुज़ियानी भाषा के te को tea, the, Tee के रूप में फैलाया। कुछ भाषाएँ (पोलिश herbata, लिथुआनियाई arbata) एक तीसरी, लैटिन-मूल जड़ को बनाए रखती हैं।","de":"Tee — das heiße Getränk, das aus den Blättern der Pflanze Camellia sinensis aufgebrüht wird, und weltweit das am zweithäufigsten getrunkene Getränk nach Wasser. Sein Name lässt sich fast überall auf einen von zwei Wegen zurückführen, auf denen er China verließ: Die Seidenstraße auf dem Landweg verbreitete das nordchinesische cha (woraus chai, chay, cay, shay wurden), während holländische Schiffe, die das fujianesische te auf dem Seeweg beförderten, es als tea, the, Tee verbreiteten. Einige Sprachen (polnisch herbata, litauisch arbata) bewahren eine dritte, aus dem Lateinischen stammende Wurzel.","fr":"Thé — boisson chaude infusée à partir des feuilles du théier (Camellia sinensis), et deuxième boisson la plus consommée au monde après l'eau. Son nom remonte presque partout à l'une des deux routes par lesquelles il a quitté la Chine : la route de la soie terrestre a répandu le mot chinois du nord cha (donnant chai, chay, cay, shay), tandis que les navires hollandais transportant par voie maritime le mot fujianais te l'ont répandu sous les formes tea, the, Tee. Quelques langues (le polonais herbata, le lituanien arbata) conservent une troisième racine, d'origine latine.","it":"Tè — la bevanda calda ottenuta dall'infusione delle foglie della pianta Camellia sinensis, e la seconda bevanda più consumata al mondo dopo l'acqua. Il suo nome, quasi ovunque, risale a una delle due vie con cui uscì dalla Cina: la Via della Seta terrestre diffuse il termine cinese settentrionale cha (da cui chai, chay, cay, shay), mentre le navi olandesi che trasportavano via mare il termine hokkien (fujianese) te lo diffusero come tea, the, Tee. Alcune lingue (il polacco herbata, il lituano arbata) conservano una terza radice, di origine latina.","es":"Té — bebida caliente que se prepara con las hojas de Camellia sinensis, y la segunda bebida más consumida del mundo después del agua. Su nombre, en casi todas partes, se remonta a una de dos rutas de salida de China: la Ruta de la Seda terrestre difundió el cha del chino septentrional (dando chai, chay, cay, shay), mientras que los barcos holandeses que transportaban el te de Fujian por mar lo difundieron como tea, the, Tee. Unas pocas lenguas (el polaco herbata, el lituano arbata) conservan una tercera raíz, de origen latino.","es_eu":"Té — bebida caliente que se prepara con las hojas de Camellia sinensis, y la segunda bebida más consumida del mundo después del agua. Su nombre, en casi todas partes, se remonta a una de dos rutas de salida de China: la Ruta de la Seda terrestre difundió el cha del chino septentrional (dando chai, chay, cay, shay), mientras que los barcos holandeses que transportaban el te de Fujian por mar lo difundieron como tea, the, Tee. Unas pocas lenguas (el polaco herbata, el lituano arbata) conservan una tercera raíz, de origen latino.","es_mx":"Té — bebida caliente que se prepara con las hojas de Camellia sinensis, y la segunda bebida más consumida del mundo después del agua. Su nombre, en casi todas partes, se remonta a una de dos rutas de salida de China: la Ruta de la Seda terrestre difundió el cha del chino septentrional (dando chai, chay, cay, shay), mientras que los barcos holandeses que transportaban el te de Fujian por mar lo difundieron como tea, the, Tee. Unas pocas lenguas (el polaco herbata, el lituano arbata) conservan una tercera raíz, de origen latino.","pt":"Chá — bebida quente preparada a partir das folhas da Camellia sinensis, e a segunda bebida mais consumida do mundo depois da água. Seu nome, em quase toda parte, remonta a uma de duas rotas de saída da China: a Rota da Seda terrestre difundiu o cha do chinês setentrional (dando origem a chai, chay, cay, shay), enquanto navios holandeses que transportavam o te de Fujian por via marítima o difundiram como tea, the, Tee. Algumas poucas línguas (o polonês herbata, o lituano arbata) conservam uma terceira raiz, de origem latina.","pt_eu":"Chá — bebida quente preparada a partir das folhas da Camellia sinensis, e a segunda bebida mais consumida do mundo depois da água. Seu nome, em quase toda parte, remonta a uma de duas rotas de saída da China: a Rota da Seda terrestre difundiu o cha do chinês setentrional (dando origem a chai, chay, cay, shay), enquanto navios holandeses que transportavam o te de Fujian por via marítima o difundiram como tea, the, Tee. Algumas poucas línguas (o polonês herbata, o lituano arbata) conservam uma terceira raiz, de origem latina.","pt_br":"Chá — bebida quente preparada a partir das folhas da Camellia sinensis, e a segunda bebida mais consumida do mundo depois da água. Seu nome, em quase toda parte, remonta a uma de duas rotas de saída da China: a Rota da Seda terrestre difundiu o cha do chinês setentrional (dando origem a chai, chay, cay, shay), enquanto navios holandeses que transportavam o te de Fujian por via marítima o difundiram como tea, the, Tee. Algumas poucas línguas (o polonês herbata, o lituano arbata) conservam uma terceira raiz, de origem latina.","ru":"Чай — горячий напиток, завариваемый из листьев Camellia sinensis, второй по популярности напиток в мире после воды. Его название почти повсюду восходит к одному из двух путей распространения из Китая: сухопутный Шёлковый путь разнёс севернокитайское cha (отсюда chai, chay, cay, shay), тогда как голландские корабли, везшие морем фуцзяньское te, распространили его как tea, the, Tee. Некоторые языки (польское herbata, литовское arbata) сохраняют третий, латинский по происхождению, корень.","uk":"Чай — гарячий напій, який заварюють з листя Camellia sinensis, другий за поширеністю напій у світі після води. Його назва майже всюди походить від одного з двох шляхів поширення з Китаю: сухопутний Шовковий шлях поширив північнокитайське cha (звідси chai, chay, cay, shay), тоді як голландські кораблі, що везли морем фуцзянське te, поширили його як tea, the, Tee. Кілька мов (польська herbata, литовська arbata) зберігають третій, латинський за походженням, корінь.","ar":"الشاي — مشروب ساخن يُحضَّر من أوراق نبات Camellia sinensis، وهو ثاني أكثر المشروبات استهلاكًا في العالم بعد الماء. يعود اسمه في كل مكان تقريبًا إلى أحد طريقين خرجا من الصين: طريق الحرير البري نشر كلمة cha الصينية الشمالية (ومنها chai وchay وcay وshay)، بينما نقلت السفن الهولندية كلمة te من منطقة فوجيان عبر البحر فانتشرت باسم tea وthe وTee. تحتفظ لغات قليلة (البولندية herbata والليتوانية arbata) بجذر ثالث مشتق من اللاتينية.","he":"תה — משקה חם המוכן מעליו של צמח ה-Camellia sinensis, והמשקה השני הנצרך ביותר בעולם אחרי מים. שמו כמעט בכל מקום מתחקה אחר אחד משני נתיבים שיצאו מסין: דרך המשי היבשתית הפיצה את המילה הסינית-הצפונית cha (שממנה chai, chay, cay, shay), בעוד ספינות הולנדיות שהובילו בים את המילה te מפוג'יאן הפיצו אותה כ-tea, the, Tee. שפות מעטות (הפולנית herbata והליטאית arbata) שומרות על שורש שלישי, ממקור לטיני.","sw":"Chai — kinywaji cha moto kinachotengenezwa kwa majani ya Camellia sinensis, na ni kinywaji cha pili kinachonywewa zaidi duniani baada ya maji. Jina lake karibu kila mahali linatokana na mojawapo ya njia mbili zilizotoka Uchina: Barabara ya Hariri ya nchi kavu ilieneza neno cha la Kichina cha kaskazini (likizaa chai, chay, cay, shay), huku meli za Kiholanzi zilizosafirisha neno te la Fujian baharini zikilieneza kama tea, the, Tee. Lugha chache (Kipolandi herbata na Kilithuania arbata) zinadumisha mzizi wa tatu, wenye asili ya Kilatini."},"partial":true},"orange":{"label":{"en":"Orange","ja":"オレンジ","ko":"오렌지","zh":"橙","yue":"橙","vi":"Cam","th":"ส้ม","id":"Jeruk","hi":"संतरा","de":"Orange","fr":"Orange","it":"Arancia","es":"Naranja","es_eu":"Naranja","es_mx":"Naranja","pt":"Laranja","pt_eu":"Laranja","pt_br":"Laranja","ru":"Апельсин","uk":"Апельсин","ar":"برتقال","he":"תפוז","sw":"Chungwa"},"definition":{"en":"Orange — the sweet citrus fruit, and a map of four different answers to the same question. The fruit reached Europe twice. The bitter orange came overland along Persian and Arab trade in the Middle Ages, carrying Sanskrit नारङ्ग with it: نارنج → Spanish naranja, Italian arancia, French and English orange. The sweet orange came by sea in the 16th century in Portuguese ships, and half the eastern Mediterranean simply named it after the traders — Greek πορτοκάλι, Turkish portakal, Arabic برتقال, Amharic ብርቱካን, Georgian ფორთოხალი, Persian پرتقال. Northern Europe took a third answer from Dutch merchants, who called it the \"apple from China\": sinaasappel, Apfelsine, апельсин, appelsiini. And a good part of the world just kept its own word.","ja":"オレンジ——甘い柑橘の果実であり、同じ問いに対する四つの答えが並ぶ地図でもある。この果実はヨーロッパに二度渡ってきた。まず中世、ダイダイがペルシア・アラブの陸路交易でもたらされ、サンスクリット語 नारङ्ग を伴っていた：نارنج → スペイン語 naranja、イタリア語 arancia、フランス語・英語 orange。次に16世紀、甘いオレンジがポルトガル船によって海路で届き、東地中海の半分はそれを運んだ商人の名で呼んだ——ギリシャ語 πορτοκάλι、トルコ語 portakal、アラビア語 برتقال、アムハラ語 ብርቱካን、ジョージア語 ფორთოხალი、ペルシア語 پرتقال。北ヨーロッパはオランダ商人から第三の答えを受け取った。彼らはこれを「中国のりんご」と呼んだ：sinaasappel、Apfelsine、апельсин、appelsiini。そして世界のかなりの部分は、自前の語をそのまま使い続けた。","ko":"오렌지 — 달콤한 감귤류 열매이자, 같은 물음에 대한 네 가지 대답이 나란히 놓인 지도. 이 열매는 유럽에 두 번 건너왔다. 중세에는 쓴 오렌지가 페르시아·아랍의 육상 교역을 따라 들어오면서 산스크리트어 नारङ्ग을 함께 실어 왔다: نارنج → 스페인어 naranja, 이탈리아어 arancia, 프랑스어·영어 orange. 16세기에는 단 오렌지가 포르투갈 배로 바닷길을 통해 도착했고, 동지중해의 절반은 그것을 실어 온 상인들의 이름으로 불렀다 — 그리스어 πορτοκάλι, 튀르키예어 portakal, 아랍어 برتقال, 암하라어 ብርቱካን, 조지아어 ფორთოხალი, 페르시아어 پرتقال. 북유럽은 네덜란드 상인에게서 세 번째 대답을 받았다. 그들은 이것을 \"중국에서 온 사과\"라고 불렀다: sinaasappel, Apfelsine, апельсин, appelsiini. 그리고 세계의 상당 부분은 그냥 자기 말을 지켰다.","zh":"橙——甜味的柑橘类水果，也是同一个问题的四种答案并列的地图。这种水果两度传入欧洲。中世纪时，酸橙沿波斯与阿拉伯的陆路贸易传来，带着梵语 नारङ्ग 一同上路：نارنج → 西班牙语 naranja、意大利语 arancia、法语和英语 orange。16 世纪，甜橙随葡萄牙商船由海路而至，东地中海有一半地区干脆用运来它的商人来命名——希腊语 πορτοκάλι、土耳其语 portakal、阿拉伯语 برتقال、阿姆哈拉语 ብርቱካን、格鲁吉亚语 ფორთოხალი、波斯语 پرتقال。北欧从荷兰商人那里得到第三种答案，他们称之为「中国来的苹果」：sinaasappel、Apfelsine、апельсин、appelsiini。而世界上相当一部分地区，就一直用着自己原有的词。","yue":"橙——甜味嘅柑橘類水果，亦係同一個問題四種答案並列嘅地圖。呢種水果兩次傳入歐洲。中世紀時，酸橙沿住波斯同阿拉伯嘅陸路貿易傳嚟，帶埋梵語 नारङ्ग 一齊上路：نارنج → 西班牙文 naranja、意大利文 arancia、法文同英文 orange。16 世紀，甜橙隨葡萄牙商船由海路嚟到，東地中海有一半地方索性用運佢嚟嘅商人嚟命名——希臘文 πορτοκάλι、土耳其文 portakal、阿拉伯文 برتقال、阿姆哈拉文 ብርቱካን、格魯吉亞文 ფორთოხალი、波斯文 پرتقال。北歐由荷蘭商人度得到第三種答案，佢哋叫佢做「中國嚟嘅蘋果」：sinaasappel、Apfelsine、апельсин、appelsiini。而世界上相當一部分地方，就一直用緊自己本身嘅詞。","vi":"Cam — loại quả có múi vị ngọt, và cũng là một tấm bản đồ của bốn câu trả lời khác nhau cho cùng một câu hỏi. Loại quả này đến châu Âu hai lần. Cam đắng đến bằng đường bộ theo thương mại Ba Tư và Ả Rập thời Trung cổ, mang theo tiếng Phạn नारङ्ग: نارنج → tiếng Tây Ban Nha naranja, tiếng Ý arancia, tiếng Pháp và tiếng Anh orange. Cam ngọt đến bằng đường biển vào thế kỷ 16 trên tàu Bồ Đào Nha, và một nửa vùng đông Địa Trung Hải đơn giản gọi nó theo tên những thương nhân ấy — tiếng Hy Lạp πορτοκάλι, tiếng Thổ Nhĩ Kỳ portakal, tiếng Ả Rập برتقال, tiếng Amhara ብርቱካን, tiếng Gruzia ფორთოხალი, tiếng Ba Tư پرتقال. Bắc Âu nhận câu trả lời thứ ba từ thương nhân Hà Lan, những người gọi nó là \"quả táo Trung Hoa\": sinaasappel, Apfelsine, апельсин, appelsiini. Còn một phần không nhỏ của thế giới thì cứ giữ từ của riêng mình.","th":"ส้ม — ผลไม้ตระกูลส้มรสหวาน และเป็นแผนที่ของคำตอบสี่แบบต่อคำถามเดียวกัน ผลไม้ชนิดนี้เดินทางถึงยุโรปสองครั้ง ส้มขมมาทางบกตามเส้นทางการค้าเปอร์เซียและอาหรับในยุคกลาง โดยพาคำสันสกฤต नारङ्ग มาด้วย: نارنج → สเปน naranja, อิตาลี arancia, ฝรั่งเศสและอังกฤษ orange ส่วนส้มหวานมาทางทะเลในศตวรรษที่ 16 บนเรือโปรตุเกส และครึ่งหนึ่งของเมดิเตอร์เรเนียนตะวันออกก็เรียกมันตามชื่อพ่อค้าเหล่านั้นเลย — กรีก πορτοκάλι, ตุรกี portakal, อาหรับ برتقال, อัมฮารา ብርቱካን, จอร์เจีย ფორთოხალი, เปอร์เซีย پرتقال ยุโรปเหนือได้คำตอบที่สามจากพ่อค้าชาวดัตช์ ผู้เรียกมันว่า \"แอปเปิลจากจีน\": sinaasappel, Apfelsine, апельсин, appelsiini และโลกอีกส่วนไม่น้อยก็ใช้คำของตัวเองต่อไป","id":"Jeruk — buah sitrus manis, sekaligus peta empat jawaban berbeda untuk satu pertanyaan yang sama. Buah ini sampai ke Eropa dua kali. Jeruk pahit datang lewat darat mengikuti perdagangan Persia dan Arab pada Abad Pertengahan, membawa serta kata Sanskerta नारङ्ग: نارنج → bahasa Spanyol naranja, Italia arancia, Prancis dan Inggris orange. Jeruk manis datang lewat laut pada abad ke-16 di kapal-kapal Portugis, dan separuh Mediterania timur begitu saja menamainya menurut para pedagang itu — Yunani πορτοκάλι, Turki portakal, Arab برتقال, Amhara ብርቱካን, Georgia ფორთოხალი, Persia پرتقال. Eropa Utara mengambil jawaban ketiga dari pedagang Belanda, yang menyebutnya \"apel dari Tiongkok\": sinaasappel, Apfelsine, апельсин, appelsiini. Dan sebagian besar dunia lainnya tetap memakai katanya sendiri.","hi":"संतरा — मीठा नींबू-वंशी फल, और एक ही सवाल के चार अलग-अलग जवाबों का नक़्शा। यह फल यूरोप दो बार पहुँचा। खट्टा संतरा मध्यकाल में फ़ारसी और अरब व्यापार के स्थल मार्ग से आया और अपने साथ संस्कृत नारङ्ग लेकर आया: نارنج → स्पेनी naranja, इतालवी arancia, फ़्रेंच और अंग्रेज़ी orange। मीठा संतरा 16वीं सदी में पुर्तगाली जहाज़ों पर समुद्र के रास्ते आया, और पूर्वी भूमध्यसागर के आधे हिस्से ने उसे उन्हीं व्यापारियों के नाम से पुकारा — यूनानी πορτοκάλι, तुर्की portakal, अरबी برتقال, अम्हारी ብርቱካን, जॉर्जियाई ფორთოხალი, फ़ारसी پرتقال। उत्तरी यूरोप को तीसरा जवाब डच व्यापारियों से मिला, जो उसे \"चीन का सेब\" कहते थे: sinaasappel, Apfelsine, апельсин, appelsiini। और दुनिया का एक बड़ा हिस्सा अपना ही शब्द बनाए रहा।","de":"Orange — die süße Zitrusfrucht und eine Karte von vier verschiedenen Antworten auf dieselbe Frage. Die Frucht erreichte Europa zweimal. Die Bitterorange kam im Mittelalter über den Landweg mit dem persischen und arabischen Handel und brachte das Sanskritwort नारङ्ग mit: نارنج → spanisch naranja, italienisch arancia, französisch und englisch orange. Die Süßorange kam im 16. Jahrhundert auf portugiesischen Schiffen über See, und der halbe östliche Mittelmeerraum benannte sie schlicht nach den Händlern — griechisch πορτοκάλι, türkisch portakal, arabisch برتقال, amharisch ብርቱካን, georgisch ფორთოხალი, persisch پرتقال. Nordeuropa nahm eine dritte Antwort von niederländischen Kaufleuten, die sie den „Apfel aus China“ nannten: sinaasappel, Apfelsine, апельсин, appelsiini. Und ein guter Teil der Welt behielt einfach sein eigenes Wort.","fr":"Orange — l'agrume sucré, et une carte de quatre réponses différentes à la même question. Le fruit est arrivé deux fois en Europe. L'orange amère est venue par voie terrestre avec le commerce persan et arabe au Moyen Âge, apportant avec elle le sanskrit नारङ्ग : نارنج → espagnol naranja, italien arancia, français et anglais orange. L'orange douce est venue par la mer au XVIe siècle sur des navires portugais, et la moitié de la Méditerranée orientale l'a tout simplement nommée d'après les marchands — grec πορτοκάλι, turc portakal, arabe برتقال, amharique ብርቱካን, géorgien ფორთოხალი, persan پرتقال. L'Europe du Nord a pris une troisième réponse chez les marchands néerlandais, qui l'appelaient la « pomme de Chine » : sinaasappel, Apfelsine, апельсин, appelsiini. Et une bonne partie du monde a simplement gardé son propre mot.","it":"Arancia — l'agrume dolce, e una mappa di quattro risposte diverse alla stessa domanda. Il frutto arrivò in Europa due volte. L'arancia amara giunse via terra con il commercio persiano e arabo nel Medioevo, portando con sé il sanscrito नारङ्ग: نارنج → spagnolo naranja, italiano arancia, francese e inglese orange. L'arancia dolce arrivò via mare nel Cinquecento sulle navi portoghesi, e metà del Mediterraneo orientale la chiamò semplicemente con il nome dei mercanti — greco πορτοκάλι, turco portakal, arabo برتقال, amarico ብርቱካን, georgiano ფორთოხალი, persiano پرتقال. Il Nord Europa prese una terza risposta dai mercanti olandesi, che la chiamavano la «mela della Cina»: sinaasappel, Apfelsine, апельсин, appelsiini. E buona parte del mondo tenne semplicemente la propria parola.","es":"Naranja — el cítrico dulce, y un mapa de cuatro respuestas distintas a la misma pregunta. La fruta llegó dos veces a Europa. La naranja amarga vino por tierra con el comercio persa y árabe en la Edad Media, trayendo consigo el sánscrito नारङ्ग: نارنج → español naranja, italiano arancia, francés e inglés orange. La naranja dulce llegó por mar en el siglo XVI en barcos portugueses, y media cuenca oriental del Mediterráneo la nombró sencillamente por los mercaderes — griego πορτοκάλι, turco portakal, árabe برتقال, amárico ብርቱካን, georgiano ფორთოხალი, persa پرتقال. El norte de Europa tomó una tercera respuesta de los mercaderes neerlandeses, que la llamaban la «manzana de China»: sinaasappel, Apfelsine, апельсин, appelsiini. Y buena parte del mundo simplemente conservó su propia palabra.","es_eu":"Naranja — el cítrico dulce, y un mapa de cuatro respuestas distintas a la misma pregunta. La fruta llegó dos veces a Europa. La naranja amarga vino por tierra con el comercio persa y árabe en la Edad Media, trayendo consigo el sánscrito नारङ्ग: نارنج → español naranja, italiano arancia, francés e inglés orange. La naranja dulce llegó por mar en el siglo XVI en barcos portugueses, y media cuenca oriental del Mediterráneo la nombró sencillamente por los mercaderes — griego πορτοκάλι, turco portakal, árabe برتقال, amárico ብርቱካን, georgiano ფორთოხალი, persa پرتقال. El norte de Europa tomó una tercera respuesta de los mercaderes neerlandeses, que la llamaban la «manzana de China»: sinaasappel, Apfelsine, апельсин, appelsiini. Y buena parte del mundo simplemente conservó su propia palabra.","es_mx":"Naranja — el cítrico dulce, y un mapa de cuatro respuestas distintas a la misma pregunta. La fruta llegó dos veces a Europa. La naranja amarga vino por tierra con el comercio persa y árabe en la Edad Media, trayendo consigo el sánscrito नारङ्ग: نارنج → español naranja, italiano arancia, francés e inglés orange. La naranja dulce llegó por mar en el siglo XVI en barcos portugueses, y media cuenca oriental del Mediterráneo la nombró sencillamente por los mercaderes — griego πορτοκάλι, turco portakal, árabe برتقال, amárico ብርቱካን, georgiano ფორთოხალი, persa پرتقال. El norte de Europa tomó una tercera respuesta de los mercaderes neerlandeses, que la llamaban la «manzana de China»: sinaasappel, Apfelsine, апельсин, appelsiini. Y buena parte del mundo simplemente conservó su propia palabra.","pt":"Laranja — o citrino doce, e um mapa de quatro respostas diferentes para a mesma pergunta. O fruto chegou à Europa duas vezes. A laranja azeda veio por terra com o comércio persa e árabe na Idade Média, trazendo consigo o sânscrito नारङ्ग: نارنج → espanhol naranja, italiano arancia, francês e inglês orange. A laranja doce chegou por mar no século XVI em navios portugueses, e metade do Mediterrâneo oriental passou simplesmente a chamá-la pelo nome dos mercadores — grego πορτοκάλι, turco portakal, árabe برتقال, amárico ብርቱካን, georgiano ფორთოხალი, persa پرتقال. O norte da Europa tomou uma terceira resposta dos mercadores neerlandeses, que lhe chamavam a «maçã da China»: sinaasappel, Apfelsine, апельсин, appelsiini. E boa parte do mundo simplesmente manteve a sua própria palavra.","pt_eu":"Laranja — o citrino doce, e um mapa de quatro respostas diferentes para a mesma pergunta. O fruto chegou à Europa duas vezes. A laranja azeda veio por terra com o comércio persa e árabe na Idade Média, trazendo consigo o sânscrito नारङ्ग: نارنج → espanhol naranja, italiano arancia, francês e inglês orange. A laranja doce chegou por mar no século XVI em navios portugueses, e metade do Mediterrâneo oriental passou simplesmente a chamá-la pelo nome dos mercadores — grego πορτοκάλι, turco portakal, árabe برتقال, amárico ብርቱካን, georgiano ფორთოხალი, persa پرتقال. O norte da Europa tomou uma terceira resposta dos mercadores neerlandeses, que lhe chamavam a «maçã da China»: sinaasappel, Apfelsine, апельсин, appelsiini. E boa parte do mundo simplesmente manteve a sua própria palavra.","pt_br":"Laranja — o citrino doce, e um mapa de quatro respostas diferentes para a mesma pergunta. O fruto chegou à Europa duas vezes. A laranja azeda veio por terra com o comércio persa e árabe na Idade Média, trazendo consigo o sânscrito नारङ्ग: نارنج → espanhol naranja, italiano arancia, francês e inglês orange. A laranja doce chegou por mar no século XVI em navios portugueses, e metade do Mediterrâneo oriental passou simplesmente a chamá-la pelo nome dos mercadores — grego πορτοκάλι, turco portakal, árabe برتقال, amárico ብርቱካን, georgiano ფორთოხალი, persa پرتقال. O norte da Europa tomou uma terceira resposta dos mercadores neerlandeses, que lhe chamavam a «maçã da China»: sinaasappel, Apfelsine, апельсин, appelsiini. E boa parte do mundo simplesmente manteve a sua própria palavra.","ru":"Апельсин — сладкий цитрус и карта четырёх разных ответов на один и тот же вопрос. Плод попал в Европу дважды. Горький апельсин пришёл по суше с персидской и арабской торговлей в Средние века, принеся с собой санскритское नारङ्ग: نارنج → испанское naranja, итальянское arancia, французское и английское orange. Сладкий апельсин пришёл морем в XVI веке на португальских кораблях, и половина восточного Средиземноморья просто назвала его по имени торговцев — греческое πορτοκάλι, турецкое portakal, арабское برتقال, амхарское ብርቱካን, грузинское ფორთოხალი, персидское پرتقال. Северная Европа взяла третий ответ у голландских купцов, называвших его «яблоком из Китая»: sinaasappel, Apfelsine, апельсин, appelsiini. А немалая часть мира просто сохранила своё собственное слово.","uk":"Апельсин — солодкий цитрус і карта чотирьох різних відповідей на одне й те саме питання. Плід потрапив до Європи двічі. Гіркий апельсин прийшов суходолом із перською та арабською торгівлею в Середньовіччі, принісши з собою санскритське नारङ्ग: نارنج → іспанське naranja, італійське arancia, французьке й англійське orange. Солодкий апельсин прийшов морем у XVI столітті на португальських кораблях, і половина східного Середземномор'я просто назвала його на честь торговців — грецьке πορτοκάλι, турецьке portakal, арабське برتقال, амхарське ብርቱካን, грузинське ფორთოხალი, перське پرتقال. Північна Європа взяла третю відповідь у голландських купців, які називали його «яблуком із Китаю»: sinaasappel, Apfelsine, апельсин, appelsiini. А чимала частина світу просто зберегла власне слово.","ar":"البرتقال — ثمرة الحمضيات الحلوة، وخريطة لأربع إجابات مختلفة عن السؤال نفسه. وصلت الثمرة إلى أوروبا مرتين. جاء النارنج المرّ برًّا مع التجارة الفارسية والعربية في العصور الوسطى، حاملًا معه الكلمة السنسكريتية नारङ्ग: نارنج ← الإسبانية naranja، الإيطالية arancia، الفرنسية والإنجليزية orange. وجاء البرتقال الحلو بحرًا في القرن السادس عشر على السفن البرتغالية، فسمّاه نصف شرق المتوسط ببساطة باسم التجار — اليونانية πορτοκάλι، التركية portakal، العربية برتقال، الأمهرية ብርቱካን، الجورجية ფორთოხალი، الفارسية پرتقال. أما شمال أوروبا فأخذ إجابة ثالثة من التجار الهولنديين الذين سمّوه «تفاحة الصين»: sinaasappel وApfelsine وапельсин وappelsiini. وجزء كبير من العالم احتفظ ببساطة بكلمته الخاصة.","he":"תפוז — פרי ההדר המתוק, ומפה של ארבע תשובות שונות לאותה שאלה. הפרי הגיע לאירופה פעמיים. התפוז המר הגיע ביבשה עם הסחר הפרסי והערבי בימי הביניים, ונשא עמו את המילה הסנסקריטית नारङ्ग: نارنج ← ספרדית naranja, איטלקית arancia, צרפתית ואנגלית orange. התפוז המתוק הגיע בים במאה ה-16 באוניות פורטוגליות, ומחצית מזרח הים התיכון פשוט קראה לו על שם הסוחרים — יוונית πορτοκάλι, טורקית portakal, ערבית برتقال, אמהרית ብርቱካን, גיאורגית ფორთოხალი, פרסית پرتقال. צפון אירופה לקחה תשובה שלישית מסוחרים הולנדים, שקראו לו \"התפוח מסין\": sinaasappel, Apfelsine, апельсин, appelsiini. וחלק לא מבוטל מן העולם פשוט שמר על המילה שלו.","sw":"Chungwa — tunda tamu la jamii ya michungwa, na ramani ya majibu manne tofauti kwa swali lilelile. Tunda hili lilifika Ulaya mara mbili. Chungwa chungu lilikuja nchi kavu na biashara ya Kiajemi na Kiarabu enzi za kati, likibeba neno la Kisanskriti नारङ्ग: نارنج → Kihispania naranja, Kiitaliano arancia, Kifaransa na Kiingereza orange. Chungwa tamu lilikuja baharini katika karne ya 16 kwa meli za Kireno, na nusu ya Mediterania ya mashariki ikaliita tu kwa jina la wafanyabiashara hao — Kigiriki πορτοκάλι, Kituruki portakal, Kiarabu برتقال, Kiamhari ብርቱካን, Kijojia ფორთოხალი, Kiajemi پرتقال. Ulaya ya Kaskazini ilichukua jibu la tatu kutoka kwa wafanyabiashara wa Kiholanzi, walioliita \"tufaha kutoka Uchina\": sinaasappel, Apfelsine, апельсин, appelsiini. Na sehemu kubwa ya dunia iliendelea tu na neno lake yenyewe."},"partial":true},"dopamine":{"label":{"en":"Dopamine","ja":"ドーパミン","ko":"도파민","zh":"多巴胺","yue":"多巴胺","vi":"Dopamine","th":"โดพามีน","id":"Dopamin","hi":"डोपामाइन","de":"Dopamin","fr":"Dopamine","it":"Dopamina","es":"Dopamina","es_eu":"Dopamina","es_mx":"Dopamina","pt":"Dopamina","pt_eu":"Dopamina","pt_br":"Dopamina","ru":"Дофамин","uk":"Дофамін","ar":"دوبامين","he":"דופמין","sw":"Dopamini"},"definition":{"en":"The neurotransmitter dopamine — a catecholamine that carries reward, motivation and movement signals in the brain. The brain chemical itself, not a drug or a mood.","ja":"神経伝達物質のドーパミン（カテコールアミンの一種）。脳内で報酬・意欲・運動の信号を担う物質そのもので、薬や気分一般のことではない。","ko":"신경전달물질 도파민(카테콜아민의 하나). 뇌에서 보상·동기·운동 신호를 전달하는 화학물질 자체이며, 약물이나 기분 일반이 아니다.","zh":"神经递质多巴胺（一种儿茶酚胺），在大脑中传递奖赏、动机和运动信号。指该脑内化学物质本身，不是药物，也不泛指情绪。","yue":"神經遞質多巴胺（兒茶酚胺嘅一種），喺腦入面傳遞獎賞、動機同運動信號。係指嗰種腦部化學物質本身，唔係藥物，亦唔泛指情緒。","vi":"Chất dẫn truyền thần kinh dopamine (một catecholamine) truyền tín hiệu thưởng, động lực và vận động trong não. Là chính chất hóa học trong não, không phải thuốc hay cảm xúc nói chung.","th":"สารสื่อประสาทโดพามีน (แคทีโคลามีนชนิดหนึ่ง) ที่ส่งสัญญาณรางวัล แรงจูงใจ และการเคลื่อนไหวในสมอง หมายถึงสารเคมีในสมองเอง ไม่ใช่ยาหรืออารมณ์ทั่วไป","id":"Neurotransmiter dopamin (sejenis katekolamina) yang membawa sinyal imbalan, motivasi, dan gerak di otak. Zat kimia otak itu sendiri, bukan obat atau suasana hati.","hi":"तंत्रिका-संचारक डोपामाइन (एक कैटेकोलामाइन), जो मस्तिष्क में पुरस्कार, प्रेरणा और गति के संकेत ले जाता है। यह मस्तिष्क का रासायनिक पदार्थ है, कोई दवा या मनोदशा नहीं।","de":"Der Neurotransmitter Dopamin (ein Katecholamin), der im Gehirn Belohnungs-, Antriebs- und Bewegungssignale überträgt. Der Botenstoff selbst, kein Medikament und keine Stimmung.","fr":"Le neurotransmetteur dopamine (une catécholamine) qui porte dans le cerveau les signaux de récompense, de motivation et de mouvement. La substance cérébrale elle-même, pas un médicament ni une humeur.","it":"Il neurotrasmettitore dopamina (una catecolamina) che nel cervello trasmette segnali di ricompensa, motivazione e movimento. La sostanza cerebrale stessa, non un farmaco né un umore.","es":"El neurotransmisor dopamina (una catecolamina) que lleva en el cerebro las señales de recompensa, motivación y movimiento. La sustancia cerebral en sí, no un fármaco ni un estado de ánimo.","es_eu":"El neurotransmisor dopamina (una catecolamina) que lleva en el cerebro las señales de recompensa, motivación y movimiento. La sustancia cerebral en sí, no un fármaco ni un estado de ánimo.","es_mx":"El neurotransmisor dopamina (una catecolamina) que lleva en el cerebro las señales de recompensa, motivación y movimiento. La sustancia cerebral en sí, no un fármaco ni un estado de ánimo.","pt":"O neurotransmissor dopamina (uma catecolamina) que transmite no cérebro sinais de recompensa, motivação e movimento. A substância cerebral em si, não um medicamento nem um humor.","pt_eu":"O neurotransmissor dopamina (uma catecolamina) que transmite no cérebro sinais de recompensa, motivação e movimento. A substância cerebral em si, não um medicamento nem um humor.","pt_br":"O neurotransmissor dopamina (uma catecolamina) que transmite no cérebro sinais de recompensa, motivação e movimento. A substância cerebral em si, não um medicamento nem um humor.","ru":"Нейромедиатор дофамин (катехоламин), передающий в мозге сигналы вознаграждения, мотивации и движения. Само вещество мозга, а не лекарство и не настроение.","uk":"Нейромедіатор дофамін (катехоламін), що передає в мозку сигнали винагороди, мотивації та руху. Сама речовина мозку, а не ліки чи настрій.","ar":"الناقل العصبي دوبامين (أحد الكاتيكولامينات) الذي ينقل في الدماغ إشارات المكافأة والدافعية والحركة. المادة الدماغية نفسها، لا دواء ولا مزاج.","he":"המוליך העצבי דופמין (קטכולאמין) שמעביר במוח אותות של תגמול, מוטיבציה ותנועה. החומר המוחי עצמו, לא תרופה ולא מצב רוח.","sw":"Kisafirishaji-neva dopamini (katekolamini) kinachopeleka ishara za tuzo, motisha na mwendo ubongoni. Ni kemikali ya ubongo yenyewe, si dawa wala hisia."},"partial":true},"atsign":{"label":{"en":"At sign (@)","ja":"アットマーク（＠）","ko":"골뱅이 (@)","zh":"@ 符号（艾特）","yue":"@ 符號","vi":"Dấu @","th":"เครื่องหมาย @","id":"Tanda @","hi":"@ चिह्न","de":"At-Zeichen (@)","fr":"Arobase (@)","it":"Chiocciola (@)","es":"Arroba (@)","pt":"Arroba (@)","ru":"Собака (@)","uk":"Равлик (@)","ar":"علامة @","he":"שטרודל (@)","sw":"Alama ya @"},"definition":{"en":"The name spoken for the “@” symbol — which varies wildly by language, often a playful animal (snail, monkey's tail, dog) or food (strudel, rollmops), and elsewhere simply a borrowing of English “at”.","ja":"記号「＠」の呼び名。言語によって大きく異なり、動物（かたつむり・猿のしっぽ・犬・あひるの子）や食べ物（シュトルーデル・酢漬け魚）になぞらえた愛称が多く、英語の“at”を借用する言語もある。","ko":"‘@’ 기호를 부르는 이름. 언어마다 크게 다르며, 동물(달팽이·원숭이 꼬리·개)이나 음식(슈트루델·청어절임)에 빗댄 애칭이 많고, 영어 ‘at’을 빌려 쓰는 언어도 있다.","zh":"“@”符号的读法。各语言差异很大，常以动物（蜗牛、猴尾、狗）或食物（苹果卷、腌鲱鱼）来命名，也有语言直接借用英语“at”。"},"partial":true},"poop":{"label":{"en":"Poop","ja":"うんち","ko":"똥","zh":"便便","yue":"屎","vi":"Phân","th":"อึ","id":"Pup","hi":"टट्टी","de":"Kacke","fr":"Caca","it":"Cacca","es":"Caca","es_eu":"Caca","es_mx":"Caca","pt":"Cocô","pt_eu":"Cocó","pt_br":"Cocô","ru":"Кака","uk":"Кака","ar":"كاكا","he":"קקי","sw":"Kinyesi"},"definition":{"en":"Poop — the everyday, informal/childish word for excrement, not the clinical term (feces/stool).","ja":"うんち——排泄物を指す日常的・幼児語的な言い方。医学用語の「便」ではない。","ko":"똥 — 배설물을 가리키는 일상적·유아어적인 말. 의학 용어인 '대변'이 아니다.","zh":"便便——指排泄物的日常、儿语化说法，不是临床用语「粪便」。","yue":"屎——指排泄物嘅日常、口語講法，唔係臨床用語。","vi":"Phân — từ thông dụng, đời thường để chỉ chất thải của cơ thể; không phải thuật ngữ y khoa.","th":"อึ — คำเรียกอุจจาระแบบลำลองหรือคำเด็ก ไม่ใช่ศัพท์ทางการแพทย์","id":"Pup — kata sehari-hari/kata anak-anak untuk kotoran manusia; bukan istilah medis.","hi":"टट्टी — मल के लिए रोज़मर्रा का, बच्चों जैसा शब्द; चिकित्सकीय शब्द नहीं।","de":"Kacke — das umgangssprachliche, kindliche Wort für Kot; kein medizinischer Fachbegriff.","fr":"Caca — le mot familier et enfantin pour les excréments ; pas le terme médical.","it":"Cacca — la parola informale e infantile per gli escrementi; non il termine clinico.","es":"Caca — la palabra informal e infantil para las heces; no el término clínico.","es_eu":"Caca — la palabra informal e infantil para las heces; no el término clínico.","es_mx":"Caca — la palabra informal e infantil para las heces; no el término clínico.","pt":"Cocô — a palavra informal e infantil para as fezes; não o termo clínico.","pt_eu":"Cocó — a palavra informal e infantil para as fezes; não o termo clínico.","pt_br":"Cocô — a palavra informal e infantil para as fezes; não o termo clínico.","ru":"Кака — разговорное, детское слово для обозначения испражнений; не медицинский термин.","uk":"Кака — розмовне, дитяче слово для позначення випорожнень; не медичний термін.","ar":"كاكا — الكلمة العامية والطفولية للبراز؛ وليست المصطلح الطبي.","he":"קקי — המילה היומיומית והילדית לצואה; לא המונח הרפואי.","sw":"Kinyesi — neno la kawaida la kila siku kwa mavi; si neno la kitaalamu."},"partial":true}};
